65	async function paged(gh, path) {
66	  const out = [];
67	  for (let page = 1; ; page += 1) {
68	    const sep = path.includes('?') ? '&' : '?';
69	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
70	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
71	    out.push(...json);
72	    if (json.length < 100) break;
73	  }
74	  return out;
75	}
