101	// corpus-only exclusion: the PR listing has no file list, and resolving one per
102	// PR would cost a read per PR across the whole window. It does not need to —
103	// a corpus-only PR's merge commit is already non-substantive, so no task with a
104	// `commits`-gated precondition ever reaches this listing on its account. The housekeeping regex already covers
105	// the growth tasks' own `Claudinite growth: …` PRs and the scheduler's
106	// `[claudinite-task]` titles, so the self-trigger guards survive the widening.
107	const isMinablePr = (p) => {
108	  if ((p.user?.login ?? '').endsWith('[bot]')) return false;
