304	  //
305	  // Three shapes of answer, and the difference between the last two is the whole of
306	  // F27: `gone` (the API says it does not exist) is a fact a precondition can
307	  // decline on, while `unreadable` (a rate limit, a 500) is one it must NOT — a
308	  // decline's write-back cannot reach an issue it cannot read.
309	  async request(gh, ctx) {
310	    const number = ctx.item?.request ?? null;
311	    if (!number) return null;
