328	      // this login is not one. The first is a repo-configuration fault and the
329	      // second is the ordinary "a stranger opened it" case, and only the API can
330	      // tell them apart — so a 404 is `none` and anything else stops the read.
331	      let value;
332	      if (res.status === 200) value = res.json?.role_name ?? res.json?.permission ?? 'none';
333	      else if (res.status === 404) value = 'none';
334	      else { failed = `the permission API answered ${res.status} for @${login}`; value = 'none'; }
