1	// The usage fold's SECOND source, and a HISTORICAL one: the retired slot scheduler's
2	// own Actions runs (skill-usage-metrics DESIGN §4.2). Each of its runs printed one
3	// machine-readable record per due task saying what it did with it — dispatched an
4	// agent, ran it as code-work only, skipped it on its precondition, failed it, or
5	// deferred it. This module reads those records back out of the run logs.
6	//
7	// NOTHING WRITES THEM ANY MORE (#974). The reader stays because the logs it reads are
8	// still inside Actions retention and are still real; when they age out it returns
9	// nothing, which is the correct answer rather than a fault. The queue keeps each
10	// occurrence's outcome as a label on its own work item instead — a better record and
11	// a different read, tracked as #994.
12	//
13	// It lives in this task's folder because nothing else uses it, and it holds no
14	// counting logic: it turns "runs since the watermark" into `[{ date, pack, task,
15	// outcome }]`, and fold-usage.mjs does the arithmetic.
16	//
17	// FORWARD-ONLY, past a watermark — unlike the capture files, which the fold
18	// re-reads from scratch every night. The reason is the source, not the taste: the
19	// logs branch is local git (one tree read plus one blob read, no budget to spend),
20	// while these are paged REST reads over a rate-limited API, two calls per run, and
21	// re-reading a 10-day window every night would cost ~20x the calls for an identical
22	// answer. So each fold reads only what is new and the aggregate carries how far it
23	// got. The cost is stated where the trade is made (fold-usage.mjs `foldTaskRuns`):
24	// a counting bug fixed later applies from the fix forward, it does not heal history.
25	//
26	// FAIL-SOFT. Every failure here — an unreadable ledger, a log that 404s, a run whose
27	// jobs cannot be listed — degrades this ONE source to "nothing new this run" and
28	// leaves the watermark where it was, so the next fold retries the same runs. The
29	// skill and check counts do not depend on it and must not be lost with it.
30	
31	import { SCHEDULER_WORKFLOW_FILE } from '../../../../engine/scheduler/signals/gh.mjs';
32	import { parseTaskRuns } from '../../../../engine/scheduler/run-record.mjs';
33	
34	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
35	
36	// How many runs one fold will pull logs for. An hourly scheduler files ~24 runs a
37	// day, so this is ~10 days of catch-up in a single pass at two API calls each —
38	// enough to absorb a long fold outage, bounded so a pathological backlog cannot eat
39	// the run's whole rate budget in one go. A truncated pass advances the watermark to
40	// the last run it read, so the next fold continues from there; the caller LOGS the
41	// remainder rather than leaving a silent cap.
42	export const MAX_RUNS_PER_FOLD = 240;
43	
44	// How far back the FIRST fold looks when the aggregate carries no run watermark yet.
45	// Deliberately short: there is no history to reconstruct here, only a series to
46	// start, and a repo adopting this should not spend hundreds of API calls back-filling
47	// days whose numbers nobody will read.
48	export const FIRST_FOLD_LOOKBACK_DAYS = 2;
49	
50	// A tiny REST reader. Separate from the scheduler's `makeGh` because that one parses
51	// JSON and the job-log endpoint answers with a redirect to plain text; `fetchImpl` is
52	// injected so the tests drive both shapes without a network.
53	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
54	  const headers = {
55	    accept: 'application/vnd.github+json',
56	    'x-github-api-version': '2022-11-28',
57	    'user-agent': 'claudinite-usage-fold',
58	    ...(token ? { authorization: `Bearer ${token}` } : {}),
59	  };
60	  return {
61	    async json(path) {
62	      const res = await fetchImpl(`${api}${path}`, { headers });
63	      if (res.status !== 200) return null;
64	      try { return await res.json(); } catch { return null; }
65	    },
66	    async text(path) {
67	      const res = await fetchImpl(`${api}${path}`, { headers });
68	      if (res.status !== 200) return null;
69	      try { return await res.text(); } catch { return null; }
70	    },
71	  };
72	}
73	
74	export const lookbackFrom = (nowIso, days = FIRST_FOLD_LOOKBACK_DAYS) =>
75	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
76	
77	// The scheduler-workflow runs to read this fold: completed runs started strictly after the
78	// watermark, oldest first.
79	//
80	// Only COMPLETED runs — an in-progress run's log is still being written, and the
81	// fold itself runs inside one (its own). That is safe against a gap because the
82	// workflow serializes on a concurrency group: a prior run has finished before the
83	// current one starts, so "completed and newer than the watermark" cannot skip a run
84	// that was still running when an earlier fold looked.
85	export async function schedulerRuns(reader, repo, { since, workflow = SCHEDULER_WORKFLOW_FILE, maxPages = 5 }) {
86	  const runs = [];
87	  for (let page = 1; page <= maxPages; page++) {
88	    const path = `/repos/${repo}/actions/workflows/${workflow}/runs`
89	      + `?status=completed&per_page=100&page=${page}&created=%3E%3D${encodeURIComponent(String(since).slice(0, 10))}`;
90	    const json = await reader.json(path);
91	    const batch = json?.workflow_runs;
92	    if (!Array.isArray(batch) || batch.length === 0) break;
93	    for (const run of batch) {
94	      const at = run.run_started_at || run.created_at;
95	      if (!at || !run.id) continue;
96	      if (at <= since) continue;           // already folded (the `created` filter is day-grained)
97	      runs.push({ id: run.id, startedAt: at });
98	    }
99	    if (batch.length < 100) break;
100	  }
101	  // The API answers newest-first; fold oldest-first so a truncated pass leaves a
102	  // watermark the next fold can continue from.
103	  return runs.sort((a, b) => (a.startedAt < b.startedAt ? -1 : a.startedAt > b.startedAt ? 1 : a.id - b.id));
104	}
105	
106	// One run's whole log text — every job's, concatenated. Two calls: list the jobs,
107	// then read each one's log. A job whose log cannot be read contributes nothing
108	// rather than sinking the run.
109	export async function runLogText(reader, repo, runId) {
110	  const json = await reader.json(`/repos/${repo}/actions/runs/${runId}/jobs?per_page=100`);
111	  const jobs = Array.isArray(json?.jobs) ? json.jobs : [];
112	  const texts = [];
113	  for (const job of jobs) {
114	    if (!job?.id) continue;
115	    const text = await reader.text(`/repos/${repo}/actions/jobs/${job.id}/logs`);
116	    if (text) texts.push(text);
117	  }
118	  return texts.join('\n');
119	}
120	
121	// The whole read: `{ records, watermark, remaining }`.
122	//   records   — [{ date, pack, task, outcome }], the date being the run's UTC start
123	//               day, which is the day the work was scheduled for.
124	//   watermark — the new `runsFoldedThrough`, or the old one when nothing was read.
125	//   remaining — runs left unread because of the per-fold cap (0 normally). The
126	//               caller logs it; a cap that truncates silently reads as "covered
127	//               everything" when it did not.
128	export async function readTaskRuns({ reader, repo, since, now, max = MAX_RUNS_PER_FOLD }) {
129	  const from = since || lookbackFrom(now);
130	  let runs;
131	  try {
132	    runs = await schedulerRuns(reader, repo, { since: from });
133	  } catch {
134	    return { records: [], watermark: since, remaining: 0, error: 'the scheduler run ledger could not be read' };
135	  }
136	  const remaining = Math.max(0, runs.length - max);
137	  const records = [];
138	  let watermark = since;
139	  for (const run of runs.slice(0, max)) {
140	    let text = '';
141	    try { text = await runLogText(reader, repo, run.id); } catch { text = ''; }
142	    const date = run.startedAt.slice(0, 10);
143	    for (const rec of parseTaskRuns(text)) records.push({ date, ...rec });
144	    // Advance past a run whose log held no records too: an idle hour (nothing due)
145	    // legitimately prints none, and re-reading it every night forever would be the
146	    // one way this stays expensive.
147	    watermark = run.startedAt;
148	  }
149	  return { records, watermark, remaining };
150	}
