1	// The deep dive: one repo's scheduler in full — every declared task, the live queue,
2	// and the runs behind them. Reached from the fleet view or by `?repo=` directly.
3	
4	import * as gh from './github.mjs';
5	import {
6	  buildRoster, describeItem, isWorkItem, parseDeclaration, taskDeclarationPaths, periodMs,
7	  NEEDS_HUMAN,
8	} from './model.mjs';
9	import {
10	  $, el, ago, until, stamp, duration, chip, head, groupedHead, columnCount, groupStarts,
11	  emptyRow, issueLink, tiles, segmentBar, warnNodes, OUTCOME_COLOR,
12	} from './ui.mjs';
13	
14	// The roster answers three questions about a task and they do not mix: what it was
15	// DECLARED as, where it stands NOW, and what it has done. Same split as the fleet
16	// grid's, one level down.
17	const ROSTER_GROUPS = [
18	  ['', ['Task']],
19	  ['Declared', ['Cadence', 'Model', 'Ceiling']],
20	  ['Now', ['Current item', 'Next ask']],
21	  ['History', ['Last outcome', 'Outcomes seen']],
22	];
23	const ROSTER_STARTS = groupStarts(ROSTER_GROUPS);
24	const bandedRoster = (cells) => cells.map((cell, i) => {
25	  if (ROSTER_STARTS.includes(i)) cell.classList.add('group-start');
26	  return cell;
27	});
28	
29	function renderTiles(rows, open, runs, now) {
30	  const inflight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued');
31	  const parked = open.filter((i) => i.state === NEEDS_HUMAN);
32	  const warned = open.filter((i) => i.warnings.length && i.state !== NEEDS_HUMAN);
33	  // The soonest DATED ask. A ready or running task is acting now, not "in 0m", so it
34	  // is the queue panel's news rather than this tile's.
35	  const soonest = rows.map((r) => r.nextAsk?.at).filter(Boolean).sort((a, b) => a - b)[0] ?? null;
36	
37	  tiles($('tiles'), [
38	    [rows.length, 'tasks declared'],
39	    [open.length, 'open work items'],
40	    [parked.length, 'parked for a human', parked.length ? 'var(--critical)' : null],
41	    [warned.length, 'tripping recovery', warned.length ? 'var(--serious)' : null],
42	    [inflight.length, 'runs in flight', inflight.length ? 'var(--s-yellow)' : null],
43	    [soonest ? until(soonest, now).replace('in ', '') : '—', 'to next ask'],
44	  ]);
45	}
46	
47	// The Next ask cell: what will actually happen to this task next, and — where the
48	// standing item rolled — why the last ask declined. The lever each state answers to
49	// is one line, because the reader's next question is always "so what do I do".
50	function nextAskCell(r, now) {
51	  const ask = r.nextAsk ?? { kind: 'note', note: r.anchorNote };
52	  const sub = (text) => el('div', { className: 'sub', textContent: text });
53	  const declined = r.current?.lastVerdict
54	    ? el('div', { className: 'sub', textContent: `last ask declined: ${r.current.lastVerdict.reason}` }) : null;
55	  switch (ask.kind) {
56	    case 'ready':
57	      return el('td', {}, [el('div', { textContent: ask.urgent ? 'queued — urgent, next pick' : 'queued — next pick' })]);
58	    case 'running':
59	      return el('td', {}, [el('div', { textContent: `running now (${ask.phase})` })]);
60	    case 'wake':
61	      return el('td', { className: 'num' }, [el('div', { textContent: until(ask.at, now) }), sub(stamp(ask.at.toISOString())), declined]);
62	    case 'anchor':
63	      return el('td', { className: 'num' }, [el('div', { textContent: until(ask.at, now) }), sub(stamp(ask.at.toISOString()))]);
64	    case 'held':
65	      return el('td', {}, [
66	        el('div', { className: 'warn critical', textContent: 'schedule held' }),
67	        sub('no next run until the park is cleared or re-queued'),
68	      ]);
69	    case 'deps':
70	      return el('td', {}, [el('div', { textContent: `after ${ask.on.map((n) => `#${n}`).join(', ')}` })]);
71	    case 'ready-soon':
72	      return el('td', {}, [el('div', { textContent: 'due — the next scheduler run readies it' })]);
73	    case 'off-machine':
74	      return el('td', {}, [el('div', { className: 'warn warning', textContent: 'off the state machine — janitor repairs it' })]);
75	    default:
76	      return el('td', {}, [sub(ask.note ?? '—')]);
77	  }
78	}
79	
80	// Sort key for the roster: what acts soonest first. Acting now beats every date,
81	// dated asks order by time, and a held or unreadable schedule sinks to the bottom —
82	// it has no "next".
83	function askOrder(r) {
84	  const ask = r.nextAsk ?? { kind: 'note' };
85	  if (ask.kind === 'ready' || ask.kind === 'running' || ask.kind === 'ready-soon') return 0;
86	  if (ask.at) return ask.at.getTime();
87	  return Infinity;
88	}
89	
90	function renderRoster(rows, repo, now, scanComplete) {
91	  const body = groupedHead($('roster'), ROSTER_GROUPS);
92	  if (!rows.length) {
93	    body.append(emptyRow(columnCount(ROSTER_GROUPS), 'No declared task has a tasks/ directory in this repo.'));
94	    return;
95	  }
96	
97	  for (const r of rows.sort((a, b) => askOrder(a) - askOrder(b))) {
98	    const d = r.declaration ?? {};
99	    const tally = { done: 0, delivered: 0, obsolete: 0, none: 0 };
100	    for (const h of r.history) tally[h.outcome ?? 'none'] += 1;
101	
102	    const nowCell = r.current
103	      ? el('td', {}, [chip(r.current.state), ...warnNodes(r.current.warnings),
104	        el('div', { className: 'sub' }, [issueLink(repo, r.current.number), ` · ${duration(r.current.idleMs)} idle`])])
105	      : el('td', {}, [el('span', { className: 'sub', textContent: 'no open item' })]);
106	
107	    body.append(el('tr', {}, bandedRoster([
108	      el('td', {}, [
109	        el('div', { className: 'name', textContent: r.task }),
110	        el('div', { className: 'sub', textContent: r.pack }),
111	      ]),
112	      el('td', {}, [
113	        el('div', { className: 'nw', textContent: r.frequency ?? 'unknown' }),
114	        d.precondition_signals?.length
115	          ? el('div', { className: 'sub', textContent: d.precondition_signals.join(', ') })
116	          : el('div', { className: 'sub', textContent: d.has_precondition ? 'unconditional signals' : 'no precondition' }),
117	      ]),
118	      el('td', { className: 'nw', textContent: d.agent_model ?? '—' }),
119	      el('td', { className: 'nw', textContent: d.expected_outcome ?? '—' }),
120	      nowCell,
121	      nextAskCell(r, now),
122	      el('td', {}, r.lastClosed
123	        ? [el('div', { textContent: r.lastClosed.outcome ?? 'none' }),
124	          el('div', { className: 'sub', textContent: ago(r.lastClosed.closedAt, now) })]
125	        : [el('span', { className: 'sub', textContent: scanComplete ? 'never run' : 'none in window' })]),
126	      el('td', {}, [
127	        segmentBar(Object.entries(tally).map(([k, n]) => [k, n, OUTCOME_COLOR[k]])),
128	        el('div', { className: 'sub num', textContent: `${r.history.length} closed` }),
129	      ]),
130	    ])));
131	  }
132	}
133	
134	function renderQueue(open, repo, now) {
135	  const body = head($('queue'), ['Item', 'Task', 'State', 'Waiting on', 'Idle', 'Comments']);
136	  if (!open.length) { body.append(emptyRow(6, 'The queue is empty — no open work item.')); return; }
137	
138	  // Parked and warned first: the reason to open this panel is what is wrong.
139	  const rank = (i) => (i.state === NEEDS_HUMAN ? 0 : i.warnings.length ? 1 : 2);
140	  for (const i of open.sort((a, b) => rank(a) - rank(b) || b.idleMs - a.idleMs)) {
141	    const waiting = [];
142	    if (i.blockedBy.length) waiting.push(`blocked by ${i.blockedBy.map((n) => `#${n}`).join(', ')}`);
143	    if (i.notBefore) waiting.push(`wakes ${stamp(i.notBefore)}`);
144	
145	    body.append(el('tr', {}, [
146	      el('td', {}, [issueLink(repo, i.number), i.urgent ? el('span', { className: 'chip urgent', textContent: 'urgent' }) : null]),
147	      el('td', {}, [
148	        el('div', { className: 'name', textContent: i.task ?? '(unparsed title)' }),
149	        el('div', { className: 'sub', textContent: i.pack ?? '' }),
150	      ]),
151	      el('td', {}, [chip(i.state), ...warnNodes(i.warnings)]),
152	      el('td', { className: 'sub' }, [
153	        el('div', { textContent: waiting.join(' · ') || '—' }),
154	        // The roll's record: why the last ask declined, so "why didn't it run" is
155	        // answered on the row instead of a click into the issue.
156	        i.lastVerdict ? el('div', { className: 'sub', textContent: `declined: ${i.lastVerdict.reason}` }) : null,
157	      ]),
158	      el('td', { className: 'num', textContent: duration(i.idleMs) }),
159	      el('td', { className: 'num', textContent: String(i.comments) }),
160	    ]));
161	  }
162	}
163	
164	function renderRuns(runs, now) {
165	  const body = head($('runs'), ['Workflow', 'Status', 'Event', 'Branch', 'Started']);
166	  if (!runs.length) { body.append(emptyRow(5, 'No Actions runs visible.')); return; }
167	
168	  const color = (r) => {
169	    if (r.status !== 'completed') return 'var(--s-yellow)';
170	    if (r.conclusion === 'success') return 'var(--good)';
171	    if (r.conclusion === 'cancelled' || r.conclusion === 'skipped') return 'var(--muted)';
172	    return 'var(--critical)';
173	  };
174	  for (const r of runs.slice(0, 20)) {
175	    const label = r.status === 'completed' ? (r.conclusion ?? 'completed') : r.status.replace('_', ' ');
176	    body.append(el('tr', {}, [
177	      el('td', {}, [el('a', { href: r.html_url, target: '_blank', rel: 'noopener', textContent: r.name ?? '(workflow)' })]),
178	      // Icon + word, so a run's health never rests on the dot's colour.
179	      el('td', {}, [el('span', { className: 'chip' }, [el('i', { className: 'dot', style: `background:${color(r)}` }), label])]),
180	      el('td', { className: 'sub', textContent: r.event ?? '—' }),
181	      el('td', { className: 'sub', textContent: r.head_branch ?? '—' }),
182	      el('td', { className: 'num sub', textContent: ago(r.created_at, now) }),
183	    ]));
184	  }
185	}
186	
187	export async function loadRepo({ repo, token, onError }) {
188	  gh.resetCounters();
189	  const now = Date.now();
190	
191	  const meta = await gh.getRepo(repo, token);
192	  const sha = await gh.getHeadSha(repo, meta.default_branch, token);
193	
194	  const configText = await gh.getTextAtSha(repo, sha, '.claudinite-checks.json', token);
195	  if (!configText) onError?.(`${repo} has no .claudinite-checks.json — it does not run Claudinite, so there are no declared tasks.`);
196	  let declaration = null;
197	  try { declaration = configText ? JSON.parse(configText) : null; } catch {
198	    onError?.('.claudinite-checks.json is present but is not valid JSON — the roster will be empty.');
199	  }
200	  const schedule = declaration?.taskScheduler ?? null;
201	  if (declaration && !schedule) onError?.('No taskScheduler block — next-anchor times cannot be computed.');
202	
203	  const [{ paths, truncated }, runs, issuePage] = await Promise.all([
204	    gh.listTreeAtSha(repo, sha, token),
205	    gh.listRuns(repo, token).catch((e) => { onError?.(`Actions unreadable — ${e.message}`); return []; }),
206	    gh.listIssues(repo, token),
207	  ]);
208	  if (truncated) onError?.('GitHub truncated the tree listing — some tasks may be missing from the roster.');
209	
210	  const declPaths = declaration ? taskDeclarationPaths(paths, declaration) : [];
211	  const tasks = await Promise.all(declPaths.map(async (t) => ({
212	    ...t,
213	    declaration: parseDeclaration(await gh.getTextAtSha(repo, sha, t.path, token)),
214	  })));
215	
216	  const items = issuePage.issues.filter(isWorkItem);
217	  // Whether a Blocked-by issue is still open, from the page already fetched. A
218	  // blocker outside that window answers null — unknown, which is never alarmed on.
219	  const byNumber = new Map(issuePage.issues.map((i) => [i.number, i.state === 'open']));
220	  const isOpen = (n) => byNumber.get(n) ?? null;
221	  const rows = buildRoster({ tasks, items, now, schedule, isOpen });
222	  const periodFor = (k) => {
223	    const f = rows.find((r) => r.key === k)?.frequency;
224	    return f && f !== 'manual' ? periodMs(f) : null;
225	  };
226	  const open = items.filter((i) => i.state === 'open').map((i) => describeItem(i, now, { periodFor, isOpen }));
227	
228	  renderTiles(rows, open, runs, now);
229	  renderRoster(rows, repo, now, issuePage.complete);
230	  renderQueue(open, repo, now);
231	  renderRuns(runs, now);
232	
233	  return { now, sha, branch: meta.default_branch, taskCount: tasks.length, itemCount: items.length, issuePage };
234	}
235

