1	// The GitHub read client, and the only I/O in the dashboard. Every call is a READ;
2	// nothing here writes to a repo.
3	//
4	// ACCESS CONTROL IS THE VIEWER'S CREDENTIAL and there is nothing else — no backend,
5	// no shared token, no service account. Whichever provider `auth.mjs` used, the page
6	// calls api.github.com as that person, so a repo they cannot read stays unreadable
7	// and this page grants no access anyone did not already have.
8	//
9	// Caching is not an optimisation here, it is what makes a fleet view viable: see
10	// `cache.mjs` for why the three strategies differ. The rate-limit accounting below
11	// distinguishes calls that SPENT budget from 304s that did not, because "how much
12	// did that cost" is the question a viewer asks when a fleet sweep feels slow.
13	
14	import { immutable, validated, ageing, rateState, projectIssue, projectPull, projectRun, DAY_MS } from './cache.mjs';
15	
16	const API = 'https://api.github.com';
17	
18	export const rate = {
19	  remaining: null, limit: null, reset: null,
20	  spent: 0, revalidated: 0, served: 0, withheld: 0,
21	  // Set when GitHub says the budget is gone. Every later call in the same load reads
22	  // it and skips the request: twelve members' worth of calls that can only fail is
23	  // twelve more chances to trip the SECONDARY limit, which is measured in requests
24	  // made rather than in budget left.
25	  exhaustedUntil: null,
26	};
27	
28	export const resetCounters = () => { rate.spent = 0; rate.revalidated = 0; rate.served = 0; rate.withheld = 0; };
29	
30	// Told whenever GitHub restates the budget, so a display of it can be the LIVE figure
31	// rather than the one the load was planned on. A fleet sweep spends over the seconds
32	// it runs, and a readout taken before those reads answers "how many calls have I
33	// left" as of before everything that would change the answer.
34	let onRate = null;
35	export const onRateChange = (fn) => { onRate = fn; };
36	
37	// The budget policy this page is reading under. `budget.mjs` decides it; everything
38	// here only obeys it. The default is the old unconditional behaviour, so a caller
39	// that never sets one behaves exactly as before.
40	export let policy = { mode: 'live', minAge: 0, historyTtl: DAY_MS, spendCeiling: Infinity, extras: true };
41	export const setPolicy = (p) => { policy = { ...policy, ...p }; };
42	
43	// Refusing to spend is not an error in the data — it is this page choosing to keep
44	// the viewer's remaining requests. Rendered as a row that says so, never as a fault
45	// of the repo being read.
46	export class RateBudgetError extends Error {
47	  constructor(path) {
48	    super('not read — saving the remaining rate limit');
49	    this.status = 'budget';
50	    this.path = path;
51	  }
52	}
53	
54	const budgetLeft = () => rate.spent < policy.spendCeiling;
55	
56	const frozen = (now = Date.now()) => Number.isFinite(rate.exhaustedUntil) && rate.exhaustedUntil > now;
57	
58	// Carry the last known budget across page loads. Without it every fresh tab starts
59	// blind, reads live, and only learns it was nearly out AFTER spending a sweep's worth
60	// of requests finding out.
61	export function restoreRate() {
62	  const s = rateState.get();
63	  if (!s) return null;
64	  rate.remaining = s.remaining ?? null;
65	  rate.limit = s.limit ?? null;
66	  rate.reset = s.reset ?? null;
67	  rate.exhaustedUntil = s.exhaustedUntil ?? null;
68	  return s;
69	}
70	
71	export class GitHubError extends Error {
72	  constructor(status, path, detail) {
73	    super(`GitHub ${status} on ${path}${detail ? ` — ${detail}` : ''}`);
74	    this.status = status;
75	    this.path = path;
76	  }
77	}
78	
79	// An ABSENT rate-limit header means "this response did not say", which is not zero.
80	// `Number(null)` is 0 and passes `isFinite`, so reading the header straight through
81	// makes any response without one report a budget of zero — the last such response
82	// wins and the page claims the viewer is rate-limited when they are not.
83	const headerNumber = (res, name) => {
84	  const raw = res.headers.get(name);
85	  if (raw === null || raw === '') return null;
86	  const n = Number(raw);
87	  return Number.isFinite(n) ? n : null;
88	};
89	
90	function noteRate(res) {
91	  const r = headerNumber(res, 'x-ratelimit-remaining');
92	  if (r !== null) rate.remaining = r;
93	  const l = headerNumber(res, 'x-ratelimit-limit');
94	  if (l !== null) rate.limit = l;
95	  const t = headerNumber(res, 'x-ratelimit-reset');
96	  if (t !== null) rate.reset = t;
97	
98	  // A 403/429 with nothing left is the primary limit, and it stays spent until the
99	  // window rolls. `retry-after` is honoured when present because the secondary limit
100	  // sends that instead of a zeroed remaining.
101	  if ((res.status === 403 || res.status === 429)) {
102	    const retryAfter = headerNumber(res, 'retry-after');
103	    if (retryAfter !== null) rate.exhaustedUntil = Date.now() + retryAfter * 1000;
104	    else if (rate.remaining === 0 && Number.isFinite(rate.reset)) rate.exhaustedUntil = rate.reset * 1000;
105	  } else if (rate.remaining > 0) {
106	    rate.exhaustedUntil = null;
107	  }
108	  rateState.set({ remaining: rate.remaining, limit: rate.limit, reset: rate.reset, exhaustedUntil: rate.exhaustedUntil });
109	  // Never let a display's failure break a read: this is a readout, and the sweep
110	  // behind it matters more than the number beside it.
111	  try { onRate?.(rate); } catch { /* a broken readout is not a broken load */ }
112	}
113	
114	// The one call GitHub does not charge for: `/rate_limit` reports the budget without
115	// spending any of it. Asked once at boot so the FIRST load of a tab is planned on the
116	// real number rather than on a guess — which is the whole difference between a fleet
117	// sweep that fits in an anonymous 60 and one that dies a third of the way through.
118	export async function preflightRate(token) {
119	  try {
120	    const res = await raw('/rate_limit', { token });
121	    noteRate(res);
122	    if (!res.ok) return null;
123	    const body = await res.json();
124	    const core = body?.resources?.core ?? body?.rate;
125	    if (core && Number.isFinite(core.remaining)) {
126	      rate.remaining = core.remaining;
127	      rate.limit = core.limit ?? rate.limit;
128	      rate.reset = core.reset ?? rate.reset;
129	      if (core.remaining > 0) rate.exhaustedUntil = null;
130	      rateState.set({ remaining: rate.remaining, limit: rate.limit, reset: rate.reset, exhaustedUntil: rate.exhaustedUntil });
131	    }
132	    return { remaining: rate.remaining, limit: rate.limit, reset: rate.reset };
133	  } catch {
134	    return null;   // an unreachable preflight plans nothing and breaks nothing
135	  }
136	}
137	
138	async function raw(path, { token, accept = 'application/vnd.github+json', etag = null } = {}) {
139	  const res = await fetch(`${API}${path}`, {
140	    headers: {
141	      Accept: accept,
142	      'X-GitHub-Api-Version': '2022-11-28',
143	      ...(token ? { Authorization: `Bearer ${token}` } : {}),
144	      ...(etag ? { 'If-None-Match': etag } : {}),
145	    },
146	  });
147	  noteRate(res);
148	  return res;
149	}
150	
151	async function fail(res, path) {
152	  let detail = '';
153	  try { detail = (await res.json())?.message ?? ''; } catch { /* not json */ }
154	  return new GitHubError(res.status, path, detail);
155	}
156	
157	// A call whose result is live: cached with its ETag and revalidated every time. A
158	// 304 costs no rate-limit budget, so this is free freshness — never stale data.
159	async function conditional(path, token, { transform = (x) => x } = {}) {
160	  const hit = validated.get(path);
161	
162	  // Under pressure a young entry is served with NO request at all. An ETag
163	  // revalidation costs no primary budget, but it is still a request against the
164	  // secondary limit and still a round trip — and when the budget is nearly gone,
165	  // "the page reloads for free" is worth more than a few minutes of freshness.
166	  if (hit && policy.minAge > 0 && Date.now() - (hit.at ?? 0) < policy.minAge) {
167	    rate.served += 1;
168	    return hit.data;
169	  }
170	  if (frozen() || !budgetLeft()) {
171	    if (hit) { rate.withheld += 1; return hit.data; }
172	    throw new RateBudgetError(path);
173	  }
174	
175	  const res = await raw(path, { token, etag: hit?.etag });
176	  if (res.status === 304 && hit) {
177	    rate.revalidated += 1;
178	    validated.touch(path);
179	    return hit.data;
180	  }
181	  rate.spent += 1;
182	  if (!res.ok) throw await fail(res, path);
183	  const data = transform(await res.json());
184	  validated.set(path, res.headers.get('etag'), data);
185	  return data;
186	}
187	
188	export const getRepo = (repo, token) =>
189	  conditional(`/repos/${repo}`, token, {
190	    // `stargazers_count` rides along in a response the page already makes: what KIND
191	    // of repo this is belongs in the fleet row's Status group, and asking separately
192	    // for it would be a per-member call the budget does not have.
193	    transform: (r) => ({
194	      default_branch: r.default_branch, private: r.private, full_name: r.full_name,
195	      stars: r.stargazers_count ?? null, archived: Boolean(r.archived),
196	    }),
197	  });
198	
199	// The head commit of the default branch — the cache key everything immutable hangs
200	// off. One cheap call buys the right to skip every content read when nothing landed.
201	//
202	// Its DATE is kept alongside the sha because the same response already carries it:
203	// "when did this repo last move" is a fleet question that would otherwise cost a
204	// per-member call, and a read already made is the only kind #995's budget allows.
205	export const getHead = (repo, branch, token) =>
206	  conditional(`/repos/${repo}/commits/${encodeURIComponent(branch)}`, token, {
207	    transform: (c) => ({ sha: c.sha, committedAt: c.commit?.committer?.date ?? c.commit?.author?.date ?? null }),
208	  });
209	
210	export const getHeadSha = async (repo, branch, token) => (await getHead(repo, branch, token)).sha;
211	
212	// A file's text AT A SHA, therefore immutable and cached forever. This is where the
213	// bulk of a repeat load's savings come from: a roster of task declarations is one
214	// call each on a cold cache and zero on a warm one.
215	//
216	// 404 is an ANSWER, not a failure — an unadopted repo has no declaration file — and
217	// it is cached as such, so a fleet sweep does not re-ask every member every time.
218	export async function getTextAtSha(repo, sha, path, token) {
219	  const hit = immutable.get(repo, sha, path);
220	  if (hit !== undefined) { rate.served += 1; return hit; }
221	
222	  if (frozen() || !budgetLeft()) throw new RateBudgetError(path);
223	  const res = await raw(`/repos/${repo}/contents/${encodeURI(path)}?ref=${encodeURIComponent(sha)}`,
224	    { token, accept: 'application/vnd.github.raw' });
225	  rate.spent += 1;
226	  if (res.status === 404) { immutable.set(repo, sha, path, null); return null; }
227	  if (!res.ok) throw await fail(res, path);
228	  const text = await res.text();
229	  immutable.set(repo, sha, path, text);
230	  return text;
231	}
232	
233	// The tree at a sha — immutable for the same reason, and the single most expensive
234	// response the page fetches on a large repo.
235	export async function listTreeAtSha(repo, sha, token) {
236	  const hit = immutable.get(repo, sha, '::tree');
237	  if (hit !== undefined && hit !== null) { rate.served += 1; return hit; }
238	
239	  if (frozen() || !budgetLeft()) throw new RateBudgetError(`/repos/${repo}/git/trees`);
240	  const res = await raw(`/repos/${repo}/git/trees/${encodeURIComponent(sha)}?recursive=1`, { token });
241	  rate.spent += 1;
242	  if (!res.ok) throw await fail(res, `/repos/${repo}/git/trees`);
243	  const t = await res.json();
244	  const out = {
245	    paths: (t.tree ?? []).filter((n) => n.type === 'blob').map((n) => n.path),
246	    // The tree API caps at 100k entries; a truncated listing means the roster may be
247	    // missing tasks, which the page states rather than quietly implying completeness.
248	    truncated: Boolean(t.truncated),
249	  };
250	  immutable.set(repo, sha, '::tree', out);
251	  return out;
252	}
253	
254	// Issues, newest first. The LIST api and never the search index — search is
255	// eventually consistent, which is how a just-created item goes missing from a view
256	// whose whole job is showing what is happening right now.
257	//
258	// Two-tier by design, and this is the shape the 24h TTL actually applies to:
259	//   - page 1 is live (it holds every open item) → conditional, revalidated always;
260	//   - pages 2..n are settled history → TTL, default 24h.
261	// So the open queue is never stale, and yesterday's history is not re-fetched.
262	export async function listIssues(repo, token, { pages = 5, perPage = 100, historyTtl = null } = {}) {
