292	      // Page 1 holds every open item, so it is never served from a TTL — it is
293	      // revalidated on every load, which is free when nothing changed.
294	      batch = await conditional(path, token, { transform: project });
295	    } else {
296	      const ck = `issues:${repo}:p${page}`;
297	      const hit = ageing.get(ck, ttl);
298	      if (hit !== undefined) {
