300	        fromCache += 1;
301	        rate.served += 1;
302	      } else if (frozen() || !budgetLeft()) {
303	        // History is the cheapest thing to go without: page 1 already holds the live
304	        // queue, so a withheld page 2 costs depth, never correctness.
