1	// Shared rendering vocabulary. Both views draw from this so a state, a duration or a
2	// severity looks and reads the same whether you are looking at one repo or twelve —
3	// a fleet page whose "blocked" chip differs from the repo page's is a page you have
4	// to learn twice.
5	
6	import {
7	  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN,
8	} from '../../engine/scheduler/queue/work-item.mjs';
9	
10	export const $ = (id) => document.getElementById(id);
11	
12	export const el = (tag, props = {}, kids = []) => {
13	  const n = Object.assign(document.createElement(tag), props);
14	  for (const k of [].concat(kids)) if (k !== null && k !== undefined && k !== '') n.append(k);
15	  return n;
16	};
17	
18	// --- formatting ---------------------------------------------------------------
19	
20	const DUR = [['d', 86400e3], ['h', 3600e3], ['m', 60e3]];
21	
22	export function duration(msVal) {
23	  if (msVal == null || !Number.isFinite(msVal)) return '—';
24	  const v = Math.abs(msVal);
25	  for (const [suffix, unit] of DUR) if (v >= unit) return `${Math.floor(v / unit)}${suffix}`;
26	  return '<1m';
27	}
28	
29	export const ago = (at, now) => {
30	  const t = at == null ? null : (typeof at === 'number' ? at : new Date(at).getTime());
31	  return t ? `${duration(now - t)} ago` : '—';
32	};
33	export const until = (date, now) => (date ? `in ${duration(date.getTime() - now)}` : '—');
34	export const stamp = (iso) => (iso ? new Date(iso).toISOString().replace('T', ' ').slice(0, 16) : '—');
35	
36	// --- state and severity ---------------------------------------------------------
37	
38	export const STATE_UI = {
39	  [BLOCKED]:     { cls: 'blocked',   label: 'blocked' },
40	  [READY]:       { cls: 'ready',     label: 'ready' },
41	  [EXECUTING]:   { cls: 'executing', label: 'executing' },
42	  [AGENT]:       { cls: 'agent',     label: 'agent' },
43	  [NEEDS_HUMAN]: { cls: 'human',     label: 'needs human' },
44	  torn:          { cls: 'torn',      label: 'torn labels' },
45	  unlabelled:    { cls: 'torn',      label: 'no state label' },
46	  closed:        { cls: 'idle',      label: 'closed' },
47	};
48	
49	// The order the queue's states are shown in everywhere: the sequence an item moves
50	// through, so a row reads left to right as progress.
51	export const STATE_ORDER = [BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN];
52	
53	// Keyed by the canonical outcome words `outcomeOf` decodes to, so a spelling
54	// migration in the labels never reaches this table.
55	export const OUTCOME_COLOR = {
56	  done: 'var(--good)',
57	  delivered: 'var(--s-violet)',
58	  obsolete: 'var(--muted)',
59	  none: 'var(--critical)',
60	};
61	
62	export const STATE_COLOR = {
63	  [BLOCKED]: 'var(--s-blue)',
64	  [READY]: 'var(--s-aqua)',
65	  [EXECUTING]: 'var(--s-yellow)',
66	  [AGENT]: 'var(--s-violet)',
67	  [NEEDS_HUMAN]: 'var(--critical)',
68	};
69	
70	// Severity always ships as colour PLUS a glyph and words — the status palette is
71	// reserved and never carries meaning on its own.
72	export const LEVEL_GLYPH = { critical: '●', serious: '▲', warning: '▲', info: '·', ok: '✓' };
73	
74	export function chip(state) {
75	  const ui = STATE_UI[state] ?? { cls: 'idle', label: state ?? 'idle' };
76	  return el('span', { className: `chip ${ui.cls}` }, [el('i', { className: 'dot' }), ui.label]);
77	}
78	
79	export const reasonNodes = (reasons) =>
80	  reasons.map((r) => el('span', {
81	    className: `warn ${r.level}`,
82	    textContent: `${LEVEL_GLYPH[r.level] ?? '▲'} ${r.text}`,
83	  }));
84	
85	export const warnNodes = reasonNodes;
86	
87	// --- marks ----------------------------------------------------------------------
88	
89	// A thin proportional bar. Segments are `[label, count, color]`; zero-count segments
90	// are dropped rather than drawn as slivers.
91	export function segmentBar(segments, { width = 108, title = (l, n) => `${n} ${l}` } = {}) {
92	  const bar = el('div', { className: 'bar', style: `width:${width}px` });
93	  let any = false;
94	  for (const [label, count, color] of segments) {
95	    if (!count) continue;
96	    any = true;
97	    bar.append(el('i', { style: `flex:${count};background:${color}`, title: title(label, count) }));
98	  }
99	  if (!any) bar.append(el('i', { className: 'bar-empty', style: 'flex:1' }));
100	  return bar;
101	}
102	
103	// --- the member row's compact marks ----------------------------------------------
104	
105	// A fleet grid is thirteen columns wide, and three of them were spending a whole
106	// column each on something a glyph carries: a star count, a pass/fail word, and one
107	// relative date. These three fold that back — the row reads at the same glance and
108	// gives the width to the panels that need it.
109	
110	// The star count, as the mark itself over the number. It rides ahead of the name
111	// rather than in the Status group because it is not a health signal: it says what
112	// KIND of repo this is, which is the frame you read the rest of the row in.
113	export const starMark = (stars) => el('div', {
114	  className: 'stars',
115	  title: stars == null ? 'stars unknown' : `${stars} stargazer${stars === 1 ? '' : 's'}`,
116	}, [
117	  el('div', { className: 'glyph', textContent: '★' }),
118	  el('div', { className: 'n num', textContent: stars == null ? '—' : String(stars) }),
119	]);
120	
121	// CI as a dot with its age under it. The dot is never the whole message — it carries
122	// a `title` and an `aria-label` in words, because a colour alone is unreadable to a
123	// reader who cannot see the difference between this green and this red.
124	//
125	// The age is bare: "7h", not "7h ago". In a column of them the word is on every row
126	// and carries no information, and the header says what the number is.
127	export function ciMark(ui, when) {
128	  return el('div', { className: 'ci-mark' }, [
129	    el('i', {
130	      className: `dot ${ui.cls}`,
131	      role: 'img',
132	      title: `CI ${ui.label}`,
133	      'aria-label': `CI ${ui.label}`,
134	    }),
135	    el('div', { className: 'sub', textContent: when }),
136	  ]);
137	}
138	
139	// The pack count, with the mount's verdict worn as a badge on it. Two facts that are
140	// read together — how much Claudinite is declared here, and whether what is declared
141	// is current — and almost always the badge says the same thing, so it earns a corner
142	// rather than a column. The detail is the hover.
143	export function packMark(count, mount) {
144	  const badge = MOUNT_BADGE[mount?.state] ?? MOUNT_BADGE.unknown;
145	  return el('div', { className: 'pack-mark', title: badge.title(mount) }, [
146	    el('div', { className: 'n num', textContent: count == null ? '—' : String(count) }),
147	    el('div', { className: `badge ${badge.cls}`, textContent: badge.glyph, role: 'img', 'aria-label': badge.title(mount) }),
148	  ]);
149	}
150	
151	// `unknown` is not `current`: with no canon configured there is nothing to compare
152	// against, and a scheduler run there would claim a check that never happened.
153	const packList = (mount) => (mount.behindPacks ?? [])
154	  .map((p) => `${p.pack} v${p.version} < canon v${p.canonVersion}`).join('\n');
155	
156	const MOUNT_BADGE = {
157	  current: { glyph: '✓', cls: 'ok', title: (m) => `mount current — engine v${m.engineVersion}` },
158	  behind: { glyph: '⏱', cls: 'info', title: (m) => `mount behind canon:\n${packList(m)}` },
159	  'behind-engine': { glyph: '⏱', cls: 'serious', title: (m) => `mount on engine v${m.engineVersion}, canon is v${m.canonEngineVersion}` },
160	  unversioned: { glyph: '?', cls: 'warning', title: () => 'the mount stamp carries no versions — it predates the versioned update flows' },
161	  none: { glyph: '?', cls: 'warning', title: () => 'declares Claudinite but carries no mount stamp' },
162	  unknown: { glyph: '·', cls: 'idle', title: () => 'mount freshness unknown — no canon configured to compare against' },
163	};
164	
165	// A member's last 90 days of commits, as a filled area over time.
166	//
167	// A curve rather than a grid of day-squares: at this size the question a reader is
168	// asking is "is this repo being worked on, and was it always" — a shape answers that
169	// across the column in one glance, where 90 separate squares have to be counted.
170	//
171	// Drawn WEEKLY. A quarter at daily resolution is a sawtooth — an ordinary repo's
172	// weekend is a trough and its Tuesday a spike — and a sawtooth has no shape to read.
173	// The daily counts still supply the total, the peak and the hover.
174	//
175	// Three empty states, and they are three different facts. A null series is a read
176	// that did not happen (withheld for budget, or GitHub still computing); a null DAY is
177	// outside the year of statistics the API returns; and zeroes are a repo that was
178	// genuinely quiet. The curve breaks over unread days rather than drawing them at the
179	// floor, so a gap in the data never renders as a quiet stretch.
180	export function commitGraph(series, { width = 108, height = 26, note = null } = {}) {
181	  if (!series) return el('div', { className: 'sub', textContent: 'not read' });
182	
183	  const NS = 'http://www.w3.org/2000/svg';
184	  const svgEl = (tag, attrs = {}) => {
185	    const n = document.createElementNS(NS, tag);
186	    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
187	    return n;
188	  };
189	
190	  const { days, buckets, total, peak, unread } = series;
191	  const svg = svgEl('svg', {
192	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none',
193	    class: 'commits', role: 'img',
194	    'aria-label': `${total} commits over ${days.length} days, busiest day ${peak}`,
195	  });
196	
197	  const step = buckets.length > 1 ? width / (buckets.length - 1) : width;
198	  // Scaled to the row's own busiest WEEK. A shared scale across members was the
199	  // alternative and it is worse: one member vendoring a tree flattens every other row
200	  // to a floor, which is the reading — "nothing happens in these repos" — the column
201	  // exists to disprove. The hover carries the numbers, so the scale is never guessed.
202	  const top = buckets.reduce((n, b) => Math.max(n, b.count ?? 0), 0);
203	  const y = (count) => height - 1 - (top > 0 ? (count / top) * (height - 2) : 0);
204	
205	  // Contiguous runs of READ weeks. A run of one still draws, so a single week
206	  // surrounded by unread ones is visible rather than dropped.
207	  let run = [];
208	  const flush = () => {
209	    if (!run.length) { return; }
210	    const line = run.map((p, i) => `${i ? 'L' : 'M'}${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ');
211	    svg.append(svgEl('path', {
212	      d: `${line} L${run[run.length - 1].x.toFixed(2)},${height} L${run[0].x.toFixed(2)},${height} Z`,
213	      class: 'commit-area',
214	    }));
215	    svg.append(svgEl('path', { d: line, class: 'commit-line' }));
216	    run = [];
217	  };
218	  buckets.forEach((b, i) => {
219	    if (b.count == null) { flush(); return; }
220	    run.push({ x: i * step, y: y(b.count) });
221	  });
222	  flush();
223	
224	  const title = svgEl('title');
225	  title.textContent = [
226	    `${total} commit${total === 1 ? '' : 's'} over ${days.length} days, by week`,
227	    peak ? `busiest day ${peak}, busiest week ${top}` : null,
228	    unread ? `${unread} day(s) outside the year GitHub reports` : null,
229	  ].filter(Boolean).join(' · ');
230	  svg.append(title);
231	
232	  return el('div', { className: 'commit-graph' }, [
233	    svg,
234	    el('div', {
235	      className: 'sub',
236	      textContent: [total === 0 && !unread ? 'none' : String(total), note].filter(Boolean).join(' · '),
237	    }),
238	  ]);
239	}
240	
241	// --- tables ---------------------------------------------------------------------
242	
243	export const head = (table, cols) => {
244	  table.replaceChildren();
245	  table.append(el('thead', {}, [el('tr', {}, cols.map((c) => el('th', { textContent: c })))]));
246	  return table.appendChild(el('tbody'));
247	};
248	
249	export const emptyRow = (span, text) =>
250	  el('tr', {}, [el('td', { colSpan: span, className: 'empty', textContent: text })]);
251	
252	export const issueLink = (repo, n) =>
253	  el('a', { href: `https://github.com/${repo}/issues/${n}`, target: '_blank', rel: 'noopener', textContent: `#${n}` });
254	
255	export const repoLink = (repo) =>
256	  el('a', { href: `https://github.com/${repo}`, target: '_blank', rel: 'noopener', textContent: repo });
257	
258	// --- counting up ----------------------------------------------------------------
259	
260	// A fleet load repaints on EVERY member's read landing, so a headline number is
261	// rebuilt a dozen times in a couple of seconds and each rebuild replaces the digits
262	// outright. The eye reads that as flicker rather than as arrival: you cannot tell
263	// whether 7 became 9 or whether two different numbers were drawn.
264	//
265	// So a number that CHANGED tweens from what the reader was last shown to what it is
266	// now, and only that. A first paint has nothing to count from and simply appears; a
267	// value that did not move is not re-animated; anything non-numeric — `3/12`, `—` —
268	// has nothing to interpolate and is set outright.
269	//
270	// `key` is the identity across paints, because the node is not: `replaceChildren`
271	// discards the element the last tween was writing into. It is the tile's own label,
272	// which is what makes two tiles two counters.
273	const displayed = new Map();
274	const inFlight = new Map();
275	
276	const COUNT_MS = 400;
277	
278	// Motion here is decoration on a page whose job is fault-finding, so a reader who has
279	// asked the platform for less of it gets the number and none of the movement.
280	const stillness = () => typeof matchMedia === 'function'
281	  && matchMedia('(prefers-reduced-motion: reduce)').matches;
282	
283	// Decelerating, so the counter reads as landing on its value rather than as stopping
284	// mid-climb.
285	const ease = (t) => 1 - (1 - t) ** 3;
286	
287	export function countUp(node, key, value) {
288	  const stop = inFlight.get(key);
289	  if (stop) { stop(); inFlight.delete(key); }
290	
291	  const to = Number(value);
292	  const from = displayed.get(key);
293	  const set = (n) => { node.textContent = String(n); };
294	
295	  if (!Number.isFinite(to) || typeof requestAnimationFrame !== 'function' || stillness()) {
296	    set(value);
297	    displayed.set(key, Number.isFinite(to) ? to : null);
298	    return node;
299	  }
300	  if (!Number.isFinite(from) || from === to) {
301	    set(to);
302	    displayed.set(key, to);
303	    return node;
304	  }
305	
306	  const t0 = performance.now();
307	  let frame = 0;
308	  const step = (t) => {
309	    // Clamped at BOTH ends. A rAF callback is handed the timestamp of the frame it
310	    // belongs to, which can predate the `performance.now()` taken while scheduling it
311	    // — and a fractionally negative progress run through an ease that overshoots
312	    // backwards drew a counter passing through −12 on its way up from zero.
313	    const p = Math.min(1, Math.max(0, (t - t0) / COUNT_MS));
314	    const at = Math.round(from + (to - from) * ease(p));
315	    set(at);
316	    displayed.set(key, p < 1 ? at : to);
317	    if (p < 1) frame = requestAnimationFrame(step);
318	    else inFlight.delete(key);
319	  };
320	  // The landing value is recorded up front, so a tween cut short by the next paint
321	  // still leaves the counter's memory on the number that paint asked for.
322	  displayed.set(key, from);
323	  set(from);
324	  frame = requestAnimationFrame(step);
325	  inFlight.set(key, () => cancelAnimationFrame(frame));
326	  return node;
327	}
328	
329	// Forget every counter — the next paint's numbers then appear rather than climb.
330	// What a cleared cache and a switched view have in common: the figures after are not
331	// a continuation of the figures before, and tweening between them would draw a
332	// change that did not happen.
333	export const resetCountUps = () => { for (const stop of inFlight.values()) stop(); inFlight.clear(); displayed.clear(); };
334	
335	// --- tiles ----------------------------------------------------------------------
336	
337	// `[value, label, color?, hint?]`. Colour is applied only when the tile is reporting
338	// something — a zero never gets an alarm colour, so a coloured tile always means
339	// "look at this". `hint` may be nodes rather than a string where the tile itemises
340	// what its number is made of.
341	export function tiles(node, rows) {
342	  node.replaceChildren(...rows.map(([v, k, color, hint]) => el('div', { className: 'tile' }, [
343	    countUp(el('div', { className: 'v num', style: color ? `color:${color}` : '' }), k, v),
344	    el('div', { className: 'k', textContent: k }),
345	    hint == null || hint === '' ? null
346	      : (typeof hint === 'string' ? el('div', { className: 'sub', textContent: hint }) : hint),
347	  ])));
348	}
349	
350	// --- grouped table heads --------------------------------------------------------
351	
352	// A header BAND above the column names, so a wide row reads as a few questions rather
353	// than as a wall of columns. `groups` is `[title, [col, …]]`; a group whose title is
354	// empty spans its columns unlabelled, which is what the identity column at the left
355	// edge wants — it belongs to no question.
356	export const groupedHead = (table, groups) => {
357	  table.replaceChildren();
358	  table.append(el('thead', {}, [
359	    el('tr', { className: 'band' }, groups.map(([title, cols]) =>
360	      el('th', { colSpan: cols.length, className: title ? 'group' : 'group blank', textContent: title }))),
361	    el('tr', {}, groups.flatMap(([, cols], gi) => cols.map((c, ci) =>
362	      el('th', { className: ci === 0 && gi > 0 ? 'group-start' : '', textContent: c })))),
363	  ]));
364	  return table.appendChild(el('tbody'));
365	};
366	
367	export const columnCount = (groups) => groups.reduce((n, [, cols]) => n + cols.length, 0);
368	
369	// Which cells start a group, so the body can carry the same vertical rule the band
370	// draws. Returns the flat column indexes a `groupedHead(groups)` would open a group at.
371	export const groupStarts = (groups) => {
372	  const out = [];
373	  let i = 0;
374	  for (const [gi, [, cols]] of groups.entries()) {
375	    if (gi > 0) out.push(i);
376	    i += cols.length;
377	  }
378	  return out;
379	};
380	
381	// --- the day chart --------------------------------------------------------------
382	
383	// A stacked column per day. SVG rather than divs because the whole point is comparing
384	// heights across a fortnight, and one element per segment with a `<title>` gives the
385	// hover text for free.
386	//
387	// The scale is stated, never implied: an unlabelled column chart invites reading two
388	// panels' bars against each other when their maxima differ.
389	export function stackedColumns(days, series, { height = 84, label = (d) => d.day } = {}) {
390	  const NS = 'http://www.w3.org/2000/svg';
391	  const svgEl = (tag, attrs = {}) => {
392	    const n = document.createElementNS(NS, tag);
393	    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, String(v));
394	    return n;
395	  };
396	  // `append` returns nothing, so the title is built and filled before it goes in.
397	  const titled = (node, text) => {
398	    const t = svgEl('title');
399	    t.textContent = text;
400	    node.append(t);
401	    return node;
402	  };
403	
404	  const totals = days.map((d) => series.reduce((n, s) => n + (s.value(d) || 0), 0));
405	  const peak = Math.max(1, ...totals);
406	  const cols = Math.max(1, days.length);
407	  const gap = 3;
408	  const width = 100;                       // a viewBox unit grid; the CSS sizes it
409	  const colW = (width - gap * (cols - 1)) / cols;
410	
411	  const svg = svgEl('svg', {
412	    viewBox: `0 0 ${width} ${height}`, preserveAspectRatio: 'none',
413	    class: 'chart', role: 'img',
414	    'aria-label': `${days.length} days, peak ${peak} on ${days[totals.indexOf(peak)]?.day ?? '—'}`,
415	  });
416	
417	  days.forEach((d, i) => {
418	    const x = i * (colW + gap);
419	    let y = height;
420	    let drawn = false;
421	    for (const s of series) {
422	      const v = s.value(d) || 0;
423	      if (!v) continue;
424	      const h = (v / peak) * (height - 2);
425	      y -= h;
426	      drawn = true;
427	      svg.append(titled(svgEl('rect', { x, y, width: colW, height: h, fill: s.color, class: 'col' }),
428	        `${label(d)} — ${v} ${s.label}`));
429	    }
430	    if (!drawn) {
431	      svg.append(titled(svgEl('rect', { x, y: height - 1, width: colW, height: 1, fill: 'var(--rule)' }),
432	        `${label(d)} — nothing`));
433	    }
434	  });
435	
436	  return el('div', { className: 'chart-wrap' }, [
437	    svg,
438	    el('div', { className: 'chart-axis' }, [
439	      el('span', { className: 'sub', textContent: days[0]?.day ?? '' }),
440	      el('span', { className: 'sub', textContent: `peak ${peak}/day` }),
441	      el('span', { className: 'sub', textContent: days[days.length - 1]?.day ?? '' }),
442	    ]),
443	  ]);
444	}
445	
446	export const chartLegend = (series) =>
447	  el('div', { className: 'legend' }, series.map((s) =>
448	    el('span', {}, [el('i', { className: 'sw', style: `background:${s.color}` }), s.label])));
449	
450	// --- windowed figures -----------------------------------------------------------
451	
452	// A number with its change against the window before it. The arrow is never the whole
453	// message — the previous window's figure is spelled out, because a delta with nothing
454	// to compare it against is the vanity total this panel exists to avoid.
455	//
456	// Which DIRECTION is good is the caller's to say: more completed work is progress and
457	// more items needing a person is not, and a green up-arrow on the second would read as
458	// a boast about the fleet needing more hand-holding.
459	export function windowFigure(value, label, change, note, { better = 'up' } = {}) {
460	  const arrow = change?.dir === 'up' ? '▲' : change?.dir === 'down' ? '▼' : '—';
461	  const sense = !change || change.dir === 'flat' ? 'flat' : (change.dir === better ? 'good' : 'bad');
462	  return el('div', { className: 'tile' }, [
463	    countUp(el('div', { className: 'v num' }), label, value),
464	    el('div', { className: 'k', textContent: label }),
465	    change
466	      ? el('div', { className: `sub delta ${sense}`, textContent: `${arrow} ${change.by} vs the week before` })
467	      : null,
468	    note ? el('div', { className: 'sub', textContent: note }) : null,
469	  ]);
470	}
471

