1	// The shell: configure, authenticate, and route between the two views.
2	//
3	// ROUTING IS THE URL. No `?repo=` and a roster with more than one member means the
4	// fleet; anything else means that repo. So the fleet page is what a fleet deployment
5	// opens on, a single-member deployment goes straight to its own dashboard with no
6	// pointless one-row overview, and every view is a link someone can send.
7	
8	import * as gh from './github.mjs';
9	import * as auth from './auth.mjs';
10	import { loadConfig, loadRoster } from './config.mjs';
11	import { clearAll, stats } from './cache.mjs';
12	import { planPolicy, credentialAdvice, MINUTE_MS } from './budget.mjs';
13	import { $, el, resetCountUps } from './ui.mjs';
14	import { loadRepo } from './view-repo.mjs';
15	import { loadFleet } from './view-fleet.mjs';
16	
17	let CONFIG = null;
18	let ROSTER = [];
19	
20	const showError = (msg) => $('errors').append(el('div', { className: 'err', textContent: msg }));
21	const showNotice = (msg) => $('errors').append(el('div', { className: 'notice', textContent: msg }));
22	
23	// --- rate budget ----------------------------------------------------------------
24	
25	// How this load will be paid for, decided BEFORE it starts. The budget is whatever
26	// GitHub last told us — carried across page loads, and confirmed by the free
27	// `/rate_limit` preflight when it has aged — so a fresh tab plans on the real number
28	// instead of discovering the limit by running into it.
29	async function planBudget(token) {
30	  const carried = gh.restoreRate();
31	  // The preflight costs no primary budget. Skipped only when the carried number is
32	  // young enough to still be true.
33	  if (!Number.isFinite(gh.rate.remaining) || Date.now() - (carried?.at ?? 0) > 2 * MINUTE_MS) {
34	    await gh.preflightRate(token);
35	  }
36	  const plan = planPolicy({
37	    remaining: gh.rate.remaining,
38	    limit: gh.rate.limit,
39	    reset: gh.rate.reset,
40	    memberCount: wantsFleet() ? ROSTER.length : 1,
41	  });
42	  gh.setPolicy(plan);
43	  return plan;
44	}
45	
46	// The pill is the honest version of "why is this not fresh". A page that quietly
47	// serves an hour-old fleet without saying so is worse than one that refuses.
48	//
49	// It is LIVE, not a reading taken at the start. The plan is decided before the sweep
50	// and the sweep is what spends the budget, so a pill drawn once — as this was — shows
51	// the viewer the number from before every request that would have changed it. The
52	// figure a viewer opens this for is what is left NOW.
53	//
54	// The plan itself is not re-decided mid-load: this load reads under the policy it was
55	// planned with, and re-planning halfway would make a row's freshness depend on where
56	// in the sweep it happened to land. Only the number moves.
57	let currentPlan = null;
58	let pillQueued = false;
59	
60	function renderRatePill(plan = currentPlan) {
61	  if (!plan) return;
62	  currentPlan = plan;
63	  const pill = $('rate');
64	  pill.hidden = false;
65	  pill.className = `pill${plan.mode === 'frozen' || plan.mode === 'scarce' ? ' stop-pill' : (plan.mode === 'low' || plan.mode === 'tight' ? ' warn-pill' : '')}`;
66	  const left = Number.isFinite(gh.rate.remaining) ? `${gh.rate.remaining}/${gh.rate.limit ?? '?'}` : 'budget unknown';
67	  const held = plan.minAge > 0 ? ` · cached ${Math.round(plan.minAge / MINUTE_MS)}m` : '';
68	  const spent = gh.rate.spent ? ` · −${gh.rate.spent} this load` : '';
69	  pill.textContent = `${left} · ${plan.tier}${held}${spent}`;
70	  pill.title = `${plan.reason}\nthis load so far: ${gh.rate.spent} spent, ${gh.rate.revalidated} revalidated free, ${gh.rate.served} from cache`;
71	}
72	
73	// A fleet sweep can restate the budget eighty times in a few seconds. Redrawing the
74	// pill on each would be eighty layouts for a number the eye reads once, so the
75	// arrivals are coalesced onto the next frame.
76	function ratePillLater() {
77	  if (pillQueued || !currentPlan) return;
78	  pillQueued = true;
79	  const draw = () => { pillQueued = false; renderRatePill(); };
80	  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(draw);
81	  else draw();
82	}
83	
84	const repoParam = () => new URL(location.href).searchParams.get('repo');
85	const wantsFleet = () => !repoParam() && ROSTER.length > 1;
86	const currentRepo = () => repoParam() || CONFIG?.defaultRepo || ROSTER[0] || '';
87	
88	function go(repo) {
89	  const url = new URL(location.href);
90	  if (repo) url.searchParams.set('repo', repo);
91	  else url.searchParams.delete('repo');
92	  history.pushState(null, '', url);
93	  render();
94	}
95	
96	// --- chrome ---------------------------------------------------------------------
97	
98	function renderAuth(viewer) {
99	  const box = $('auth');
100	  box.replaceChildren();
101	
102	  if (viewer) {
103	    box.append(
104	      el('img', { className: 'avatar', src: viewer.avatar_url, alt: '', width: 22, height: 22 }),
105	      el('span', { className: 'hint', textContent: viewer.login }),
106	      // Signing out drops the CACHE as well as the credential. Everything stored was
107	      // read as this person — a private repo's issues included — and a token that dies
108	      // with the tab while its data outlives it on a shared machine is not a sign-out.
109	      el('button', { textContent: 'Sign out', onclick: () => { auth.signOut(); clearAll(); location.reload(); } }),
110	    );
111	    return;
112	  }
113	  if (auth.isOAuthConfigured(CONFIG)) {
114	    box.append(el('button', { className: 'primary', textContent: 'Sign in with GitHub', onclick: () => auth.beginSignIn(CONFIG) }));
115	    return;
116	  }
117	  const input = el('input', { type: 'password', placeholder: 'GitHub token', autocomplete: 'off' });
118	  const use = () => { auth.setPastedToken(input.value); render(); };
119	  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') use(); });
120	  box.append(input, el('button', { textContent: 'Use token', onclick: use }));
121	}
