1	// Where the page gets its deployment-specific facts. Everything host-specific lives
2	// in a `dashboard.config.json` beside the page, never in the code — the same mounted
3	// dashboard serves a member repo checked out locally and a fleet-wide Pages site,
4	// and only the config differs.
5	//
6	// Absent config is a valid deployment, not a broken one: it means the token-paste
7	// provider and whatever repo the URL names. So every key here is optional and every
8	// miss is a plain default.
9	//
10	// Shape:
11	//   {
12	//     "clientId":    "Iv1.abc123",                       // GitHub App / OAuth App client id
13	//     "exchangeUrl": "https://…/github-oauth",           // the code→token endpoint
14	//     "redirectUri": "https://owner.github.io/Repo/",    // defaults to this page's URL
15	//     "scope":       "repo",                             // classic OAuth Apps only
16	//     "rosterUrl":   "./fleet-roster.GENERATED.json",    // the repo selector's source
17	//     "repos":       ["owner/a", "owner/b"],             // an inline roster instead
18	//     "defaultRepo": "owner/a",
19	//     "digestsRepo": "owner/enforcer",                  // where the fleet digests are written
20	//     "digestsPath": "digests"                           // the directory inside it
21	//   }
22	
23	export const DEFAULTS = {
24	  clientId: null,
25	  exchangeUrl: null,
26	  redirectUri: null,
27	  scope: null,
28	  rosterUrl: null,
29	  repos: [],
30	  defaultRepo: null,
31	  // The fleet's morning briefs live in whichever repo runs the digest task — the fleet
32	  // enforcer's, never this one by assumption — so the repo is named rather than
33	  // guessed, and an unset key means this deployment has no digests panel.
34	  digestsRepo: null,
35	  digestsPath: 'digests',
36	};
37	
38	export async function loadConfig(url = './dashboard.config.json') {
39	  try {
40	    const res = await fetch(url, { cache: 'no-store' });
41	    if (!res.ok) return { ...DEFAULTS };
42	    return { ...DEFAULTS, ...(await res.json()) };
43	  } catch {
44	    return { ...DEFAULTS };
45	  }
46	}
47	
48	// The repo list for the selector. Three sources, in precedence order: an explicit
49	// inline list, a roster artifact, or nothing — and "nothing" is a single-repo
50	// deployment, which is the member case.
51	//
52	// A roster is read for its KEYS under `repos` when it is a fleet artifact (the shape
53	// Shepherd already generates), or as a plain array of names. Both are accepted
54	// because the artifact's job is not to serve this page and its shape is not ours to
55	// dictate.
56	export function rosterFrom(doc) {
57	  if (Array.isArray(doc)) return doc.filter((x) => typeof x === 'string');
58	  if (Array.isArray(doc?.repos)) return doc.repos.filter((x) => typeof x === 'string');
59	  if (doc?.repos && typeof doc.repos === 'object') return Object.keys(doc.repos);
60	  return [];
61	}
62	
63	export async function loadRoster(config) {
64	  if (config.repos?.length) return config.repos;
65	  if (!config.rosterUrl) return [];
66	  try {
67	    const res = await fetch(config.rosterUrl, { cache: 'no-store' });
68	    if (!res.ok) return [];
69	    return rosterFrom(await res.json());
70	  } catch {
71	    return [];
72	  }
73	}
