1	// The fleet view's derivation — many members' raw reads in, one ranked overview out.
2	// Pure: no clock, no I/O, no DOM.
3	//
4	// A fleet page answers a different question from the per-repo one. Per repo the
5	// question is "what is this scheduler doing"; across a fleet it is "WHERE DO I NEED
6	// TO LOOK", and a page that answers the first question twelve times over does not
7	// answer the second. So nothing here is a total for its own sake: every number is
8	// either something that needs a human, something that is about to, or the context
9	// needed to tell those apart.
10	//
11	// Three ideas do the work:
12	//
13	//   ATTENTION IS EARNED, NOT COUNTED. A member surfaces because something is true of
14	//   it — an item parked, a leash blown, a scheduler failing, a mount that stopped
15	//   converging — and each of those arrives as a REASON with a severity, not as a
16	//   number to be summed. The ranking is over the worst reason, so a member with one
17	//   parked item outranks one with forty healthy work items.
18	//
19	//   ABSENCE IS A STATE. A member that does not run Claudinite, one the viewer cannot
20	//   read, and one that is running fine are three different answers and never collapse
21	//   into "0". A fleet view whose blanks are ambiguous is worse than no fleet view.
22	//
23	//   ONE MEMBER'S FAILURE IS ONE ROW'S PROBLEM. Every member is summarised
24	//   independently and a read that failed becomes a row saying so, so a single private
25	//   repo or a rate-limit stumble cannot blank the page.
26	
27	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
28	import { periodMs } from '../../engine/scheduler/queue/anchors.mjs';
29	import {
30	  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN, URGENT,
31	  NEEDS_HUMAN_APPROVAL, outcomeOf, isParked,
32	} from '../../engine/scheduler/queue/work-item.mjs';
33	import { canonicalPackVersions } from '../../engine/pack_loader/renamed-packs.mjs';
34	import { VERSION_SOURCE, versionFromLiteral, isVersion, versionAbove } from '../../engine/version.mjs';
35	import { describeItem, isWorkItem, parseWorkItemTitle, taskDeclarationPaths } from './model.mjs';
36	import { commitDays } from './activity.mjs';
37	
38	// Severity ladder, worst first. The order IS the sort, so it is stated once here
39	// rather than implied by comparisons scattered through the render.
40	export const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
41	const levelRank = (l) => {
42	  const i = LEVELS.indexOf(l);
43	  return i === -1 ? LEVELS.length : i;
44	};
45	
46	const ms = (t) => (t == null ? null : new Date(t).getTime());
47	
48	// --- the canon side of the comparison ---------------------------------------------
49	
50	// The canon's versions are lifted as TEXT, like every declaration field: the page
51	// reads the canon over the API, where there is nothing to import. Comment-stripped
52	// so prose naming the field can never be mistaken for it, and null — never a guess —
53	// when the pattern is not there.
54	const ENGINE_VERSION_RE = new RegExp(String.raw`ENGINE_VERSION\s*=\s*'?(${VERSION_SOURCE})'?`);
55	const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[{,\s])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
56	
57	export function parseEngineVersion(text) {
58	  const m = ENGINE_VERSION_RE.exec(stripComments(String(text ?? '')));
59	  return m ? versionFromLiteral(m[1]) : null;
60	}
61	
62	export function parsePackVersion(text) {
63	  const m = PACK_VERSION_RE.exec(stripComments(String(text ?? '')));
64	  return m ? versionFromLiteral(m[1]) : null;
65	}
66	
67	// --- mount freshness ------------------------------------------------------------
68	
69	// Whether a member's mount is current. Judged on the stamp's `engineVersion` and
70	// `packVersions` and NEVER on `ref` or `updated`: the versioned flows stamp versions
71	// and nothing else, so those two hold the provenance of the last FULL re-vendor —
72	// a member converging nightly carries a months-old ref and updated forever, and
73	// judging either reads every healthy member as behind or stalled (#1065; the same
74	// class as #786). `updated` travels through as display-only provenance.
75	//
76	// `canon` is the reference to compare against: its live `engineVersion` and the
77	// canon's own per-pack versions (`packVersions`, possibly partial — the loader
78	// fetches only the packs members actually stamp). A pack the canon side cannot
79	// price is counted `unknownPacks`, never silently judged current. With no canon
80	// supplied the honest answer is `unknown`, not `current`.
81	export function mountState(stamp, canon = null) {
82	  if (!stamp) return { state: 'none', engineVersion: null, updated: null };
83	  const engineVersion = stamp.engineVersion ?? null;
84	  // The stamp is stored data: a pack renamed since it was written still keys its
85	  // version under the old spelling, which must compare rather than read as unknown.
86	  const packVersions = stamp.packVersions ? canonicalPackVersions(stamp.packVersions) : null;
87	  const updated = stamp.updated ?? null;
88	
89	  if (engineVersion == null && packVersions == null) {
90	    // A stamp with no versions predates the versioned flows entirely — this member
91	    // has not converged since they landed, which is its own kind of stale.
92	    return { state: 'unversioned', engineVersion, updated };
93	  }
94	  if (canon?.engineVersion == null) return { state: 'unknown', engineVersion, updated };
95	
96	  if (isVersion(engineVersion) && versionAbove(canon.engineVersion, engineVersion)) {
97	    return { state: 'behind-engine', engineVersion, canonEngineVersion: canon.engineVersion, updated };
98	  }
99	
100	  const behindPacks = [];
101	  let comparedPacks = 0;
102	  let unknownPacks = 0;
103	  for (const [pack, version] of Object.entries(packVersions ?? {})) {
104	    const canonVersion = canon.packVersions?.[pack];
105	    if (canonVersion == null) { unknownPacks += 1; continue; }
106	    comparedPacks += 1;
107	    if (versionAbove(canonVersion, version)) behindPacks.push({ pack, version, canonVersion });
108	  }
109	  if (behindPacks.length) {
110	    return { state: 'behind', engineVersion, behindPacks, comparedPacks, unknownPacks, updated };
111	  }
112	  return { state: 'current', engineVersion, comparedPacks, unknownPacks, updated };
113	}
114	
115	// --- one member -----------------------------------------------------------------
116	
117	// Everything a fleet row shows about one member, plus the reasons it needs looking
118	// at. `read` is what the loader managed to fetch; a member it could not read arrives
119	// with `error` set and every other field absent.
120	export function summariseMember(read, { now, canon = null } = {}) {
121	  const {
122	    repo, error = null, declaration = null, items = null, runs = null, paths = null,
123	    prs = null, head = null, stars = null, defaultBranch = null, commits = undefined,
124	  } = read ?? {};
125	
126	  if (error) {
127	    // A read the page DECLINED to make is not the same fact as one it could not make:
128	    // the repo is fine, the budget is not, and the row must not read as a fault of the
129	    // member. It is raised a rung above a permissions miss because it is the one the
130	    // viewer can act on — sign in, or wait for the reset.
131	    const withheld = error?.status === 'budget';
132	    return {
133	      repo,
134	      status: withheld ? 'withheld' : 'unreadable',
135	      level: withheld ? 'warning' : 'info',
136	      error,
137	      // Not being able to read a member is not the member being broken. It is almost
138	      // always a private repo outside this viewer's grant, so it is reported at the
139	      // bottom of the page rather than raised as an alarm.
140	      reasons: [{ level: withheld ? 'warning' : 'info', text: describeReadError(error) }],
141	    };
142	  }
143	
144	  if (!declaration) {
145	    return {
146	      repo,
147	      status: 'not-adopted',
148	      level: 'info',
149	      reasons: [{ level: 'info', text: 'does not run Claudinite' }],
150	    };
151	  }
152	
153	  const work = (items ?? []).filter(isWorkItem);
154	  const open = work.filter((i) => i.state === 'open');
155	  const closed = work.filter((i) => i.state === 'closed');
156	
157	  const declaredTasks = paths ? taskDeclarationPaths(paths, declaration).length : null;
158	  const periodFor = () => null;   // the fleet row needs no per-task cadence
159	  const described = open.map((i) => describeItem(i, now, { periodFor }));
160	
161	  const byState = { [BLOCKED]: 0, [READY]: 0, [EXECUTING]: 0, [AGENT]: 0, [NEEDS_HUMAN]: 0, other: 0 };
162	  for (const d of described) {
163	    if (byState[d.state] === undefined) byState.other += 1;
164	    else byState[d.state] += 1;
165	  }
166	
167	  const parked = described.filter((d) => d.state === NEEDS_HUMAN);
168	  // The triage split (tasks-dispatch DESIGN §4): a failure park — or one an older
169	  // engine left unclassified — holds its task's lane; an action or decision park is
170	  // a person's inbox; an approval park is a run that SUCCEEDED and waits on a merge.
171	  // Three different alarms, because a page that rings identically for all four
172	  // teaches the reader to ignore the ring.
173	  const holding = parked.filter((d) => d.blockingPark);
174	  const approvals = parked.filter((d) => !d.blockingPark && d.triage === NEEDS_HUMAN_APPROVAL);
175	  const inbox = parked.filter((d) => !d.blockingPark && d.triage !== NEEDS_HUMAN_APPROVAL);
176	  const warned = described.filter((d) => d.state !== NEEDS_HUMAN && d.warnings.length);
177	
178	  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
179	  for (const i of closed) outcomes[outcomeOf(i) ?? 'none'] += 1;
180	
181	  const lastActivity = closed
182	    .map((i) => ms(i.closed_at) ?? ms(i.updated_at))
183	    .filter(Boolean)
184	    .sort((a, b) => b - a)[0] ?? null;
185	
186	  const runSummary = summariseRuns(runs ?? [], now);
187	  const ci = ciStatus(runs ?? [], defaultBranch);
188	  const mount = mountState(declaration.claudinite, canon);
189	
190	  const n = (count, word) => `${count} ${word}${count > 1 ? 's' : ''}`;
191	  // Every reason carries a `kind`, because the row shows some of these twice
192	  // otherwise: parks have their own column with an estimate beside them, the mount
193	  // is a badge on the pack count, and CI is a dot. The RANKING still reads all of
194	  // them — a member is ordered by everything true of it — and only the rendering
195	  // drops what already has a cell of its own.
196	  const reasons = [];
197	  if (holding.length) {
198	    reasons.push({ kind: 'park', level: 'critical', text: `${n(holding.length, 'item')} parked broken — holding the task's lane` });
199	  }
200	  if (inbox.length) {
201	    reasons.push({ kind: 'park', level: 'serious', text: `${n(inbox.length, 'item')} parked for a person — an action or a decision` });
202	  }
203	  if (approvals.length) {
204	    reasons.push({ kind: 'park', level: 'warning', text: `${n(approvals.length, 'PR')} waiting for approval` });
205	  }
206	  if (runSummary.consecutiveFailures > 0) {
207	    reasons.push({
208	      kind: 'scheduler',
209	      level: runSummary.consecutiveFailures > 1 ? 'critical' : 'serious',
210	      text: `scheduler last run failed${runSummary.consecutiveFailures > 1 ? ` (${runSummary.consecutiveFailures} in a row)` : ''}`,
211	    });
212	  }
213	  if (warned.length) {
214	    reasons.push({ kind: 'park', level: 'serious', text: `${n(warned.length, 'item')} tripping a recovery rule` });
215	  }
216	  if (mount.state === 'behind-engine') {
217	    reasons.push({ kind: 'mount', level: 'serious', text: `mount is on engine v${mount.engineVersion}, canon is v${canon?.engineVersion}` });
218	  } else if (mount.state === 'behind') {
219	    reasons.push({ kind: 'mount', level: 'info', text: `mount behind canon on ${mount.behindPacks.map((p) => p.pack).join(', ')}` });
220	  } else if (mount.state === 'unversioned') {
221	    reasons.push({ kind: 'mount', level: 'warning', text: 'mount stamp carries no versions — it predates the versioned update flows' });
222	  } else if (mount.state === 'none') {
223	    reasons.push({ kind: 'mount', level: 'warning', text: 'declares Claudinite but carries no mount stamp' });
224	  }
225	  // A repo that declares tasks and has never produced a work item is not idle — its
226	  // scheduler is not running. That is invisible in every per-repo number here, which
227	  // is exactly why the fleet view is the place it shows up.
228	  if (declaredTasks !== null && declaredTasks > 0 && work.length === 0) {
229	    reasons.push({ kind: 'scheduler', level: 'serious', text: `${declaredTasks} task${declaredTasks > 1 ? 's' : ''} declared, no work item ever created` });
230	  }
231	  if (ci.state === 'failing') {
232	    // The member's own CI, said in the member's own words: this is not the scheduler
233	    // failing, and the two must not read as the same alarm.
234	    reasons.push({ kind: 'ci', level: 'warning', text: 'the repo\'s own CI is failing on its default branch' });
235	  }
236	  if (declaration.packs?.length === 0) {
237	    reasons.push({ kind: 'packs', level: 'warning', text: 'declares no packs' });
238	  }
239	
240	  const level = reasons.length ? reasons.map((r) => r.level).sort((a, b) => levelRank(a) - levelRank(b))[0] : 'ok';
241	
242	  return {
243	    repo,
244	    status: 'adopted',
245	    level,
246	    reasons,
247	    packs: (declaration.packs ?? []).map((p) => (typeof p === 'string' ? p : p?.id)).filter(Boolean),
248	    declaredTasks,
249	    open: { total: open.length, byState, urgent: described.filter((d) => d.urgent).length },
250	    parked: parked.length,
251	    parkedHolding: holding.length,
252	    parkedApprovals: approvals.length,
253	    parkedInbox: inbox.length,
254	    warned: warned.length,
255	    closedSeen: closed.length,
256	    outcomes,
257	    lastActivity,
258	    runs: runSummary,
259	    ci,
260	    stars,
261	    lastCommit: head?.committedAt ? ms(head.committedAt) : null,
262	    // Null all the way through when the read did not happen, so the row draws "not
263	    // read" rather than an empty quarter that reads as a repo nobody touched.
264	    commits: commitDays(commits, { now }),
265	    work: humanWork(items, prs, now),
266	    mount,
267	    schedule: declaration.taskScheduler ?? null,
268	  };
269	}
270	
271	// A read that failed says something different depending on how. 404 on a repo the
272	// roster names is almost always "not shared with this viewer", which is a permissions
273	// fact rather than a fault.
274	function describeReadError(error) {
275	  const status = error?.status;
276	  if (status === 'budget') return 'not read — this page is holding back your last requests; sign in or wait for the reset';
277	  if (status === 404) return 'not visible to you — the roster names it, your credential cannot see it';
278	  if (status === 403) return 'forbidden — rate limit, or your credential lacks access';
279	  if (status === 401) return 'your credential was rejected';
280	  return error?.message ? `unreadable — ${error.message}` : 'unreadable';
281	}
282	
283	// The repo's OWN CI, which is a different question from the scheduler's health: one
284	// says whether this project builds, the other whether Claudinite is running here. They
285	// are read from the same list and must never be conflated — a green scheduler on a
286	// repo whose tests are red is not a healthy member.
287	//
288	// The default branch's most recent completed run is the answer; a `schedule` run is
289	// excluded because that is the queue's own scheduler run, reported separately.
290	export function ciStatus(runs, defaultBranch) {
291	  const mine = (runs ?? []).filter((r) => r.event !== 'schedule'
292	    && (!defaultBranch || !r.head_branch || r.head_branch === defaultBranch));
293	  const inFlight = mine.some((r) => r.status === 'in_progress' || r.status === 'queued');
294	  const last = mine.find((r) => r.status === 'completed');
295	  if (!last) return { state: inFlight ? 'running' : 'unknown', at: null, name: null };
296	  const state = last.conclusion === 'success' ? 'passing'
297	    : (last.conclusion === 'cancelled' || last.conclusion === 'skipped') ? 'unknown'
298	      : 'failing';
299	  return { state: inFlight ? 'running' : state, at: ms(last.created_at), name: last.name ?? null, url: last.html_url ?? null };
300	}
301	
302	// What is waiting on a PERSON here, as opposed to on the queue: issues that are not
303	// Claudinite work items, and open pull requests. Both come out of the issue page the
304	// row already reads, so this costs nothing and stops at that window — an issue older
305	// than the window is not counted, and the panel says the window is a window.
306	export function humanWork(items, prs, now) {
307	  const open = (items ?? []).filter((i) => i.state === 'open' && !isWorkItem(i));
308	  const oldest = (list) => list.map((i) => ms(i.created_at)).filter(Boolean).sort((a, b) => a - b)[0] ?? null;
309	  const openPrs = (prs ?? []).filter((p) => !p.draft);
310	  return {
311	    issues: open.length,
312	    issuesOldest: oldest(open),
313	    prs: openPrs.length,
314	    drafts: (prs ?? []).length - openPrs.length,
315	    prsOldest: oldest(openPrs),
316	    now,
317	  };
318	}
319	
320	// The scheduler's own health. Only the workflow that drives the queue matters here —
321	// a failing unrelated CI run is the repo's business, not the fleet scheduler's — so
322	// runs are filtered to scheduled ones before anything is counted.
323	export function summariseRuns(runs, now) {
324	  const scheduled = runs.filter((r) => r.event === 'schedule');
325	  const completed = scheduled.filter((r) => r.status === 'completed');
326	  const inFlight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued').length;
327	
328	  // Consecutive failures from the most recent backwards: one failure is noise, a run
329	  // of them is a member that has stopped working.
330	  let consecutiveFailures = 0;
331	  for (const r of completed) {
332	    if (r.conclusion === 'success') break;
333	    if (r.conclusion === 'cancelled' || r.conclusion === 'skipped') continue;
334	    consecutiveFailures += 1;
335	  }
336	
337	  const lastAt = scheduled.map((r) => ms(r.created_at)).filter(Boolean).sort((a, b) => b - a)[0] ?? null;
338	
339	  return {
340	    scheduled: scheduled.length,
341	    inFlight,
342	    consecutiveFailures,
343	    lastAt,
344	    // No scheduled run at all is not "healthy" — it is "we have never seen this
345	    // member's scheduler", which the row must be able to say.
346	    everRan: scheduled.length > 0,
347	  };
348	}
349	
350	// --- the fleet ------------------------------------------------------------------
351	
352	// Worst first, then by how much is waiting. Ties break on the repo name so the order
353	// is stable across loads — a table that reshuffles under you is unreadable.
354	export function rankMembers(summaries) {
355	  return [...summaries].sort((a, b) =>
356	    levelRank(a.level) - levelRank(b.level)
357	    || (b.parked ?? 0) - (a.parked ?? 0)
358	    || (b.warned ?? 0) - (a.warned ?? 0)
359	    || (b.open?.total ?? 0) - (a.open?.total ?? 0)
360	    || a.repo.localeCompare(b.repo));
361	}
362	
363	// The headline numbers. Each is a count of MEMBERS needing something, not a count of
364	// things — "3 members need you" is actionable where "47 open items" is not.
365	export function rollUp(summaries) {
366	  const adopted = summaries.filter((s) => s.status === 'adopted');
367	  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
368	  for (const s of adopted) for (const [k, v] of Object.entries(s.outcomes ?? {})) outcomes[k] += v;
369	
370	  return {
371	    members: summaries.length,
372	    adopted: adopted.length,
373	    notAdopted: summaries.filter((s) => s.status === 'not-adopted').length,
374	    unreadable: summaries.filter((s) => s.status === 'unreadable').length,
375	    withheld: summaries.filter((s) => s.status === 'withheld').length,
376	    needAttention: adopted.filter((s) => levelRank(s.level) <= levelRank('serious')).length,
377	    parkedMembers: adopted.filter((s) => s.parked > 0).length,
378	    parkedItems: adopted.reduce((n, s) => n + s.parked, 0),
379	    parkedHolding: adopted.reduce((n, s) => n + (s.parkedHolding ?? 0), 0),
380	    parkedInbox: adopted.reduce((n, s) => n + (s.parkedInbox ?? 0), 0),
381	    parkedApprovals: adopted.reduce((n, s) => n + (s.parkedApprovals ?? 0), 0),
382	    warnedItems: adopted.reduce((n, s) => n + (s.warned ?? 0), 0),
383	    warnedMembers: adopted.filter((s) => s.warned > 0).length,
384	    failingMembers: adopted.filter((s) => s.runs?.consecutiveFailures > 0).length,
385	    neverRan: adopted.filter((s) => s.runs && !s.runs.everRan).length,
386	    behindMembers: adopted.filter((s) => ['behind', 'behind-engine', 'unversioned'].includes(s.mount?.state)).length,
387	    openItems: adopted.reduce((n, s) => n + (s.open?.total ?? 0), 0),
388	    inFlight: adopted.reduce((n, s) => n + (s.runs?.inFlight ?? 0), 0),
389	    declaredTasks: adopted.reduce((n, s) => n + (s.declaredTasks ?? 0), 0),
390	    outcomes,
391	  };
392	}
393	
394	// --- what a person is actually holding -------------------------------------------
395	
396	// What one parked item costs a person, in minutes. A flat rate deliberately: the page
397	// has no measurement of how long a park actually takes, and the honest way to publish
398	// a number nothing measures is to publish the ASSUMPTION and let it be argued with,
399	// rather than to dress a guess up as a per-kind estimate. Refine it here, in one
400	// place, when there is something real to refine it from.
401	export const MINUTES_PER_PARK = 7;
402	
403	// The vocabulary both the per-member row and the fleet rollup speak, so one function
404	// itemises both. Each field is a count of THINGS waiting; the two callers differ only
405	// in whether their things are one member's or the whole fleet's.
406	const attentionCounts = ({
407	  broken = 0, decisions = 0, approvals = 0, tripping = 0,
408	  schedulersFailing = 0, schedulersNeverRan = 0,
409	} = {}) => ({ broken, decisions, approvals, tripping, schedulersFailing, schedulersNeverRan });
410	
411	// One member's attention, in the same shape the rollup uses.
412	export const memberAttention = (s) => attentionCounts({
413	  broken: s.parkedHolding ?? 0,
414	  decisions: s.parkedInbox ?? 0,
415	  approvals: s.parkedApprovals ?? 0,
416	  tripping: s.warned ?? 0,
417	});
418	
419	// The fleet's. Schedulers are counted in MEMBERS here rather than in items, because a
420	// scheduler is a member-shaped thing — there is one per repo.
421	export const fleetAttention = (roll) => attentionCounts({
422	  broken: roll.parkedHolding,
423	  decisions: roll.parkedInbox,
424	  approvals: roll.parkedApprovals,
425	  tripping: roll.warnedItems,
426	  schedulersFailing: roll.failingMembers,
427	  schedulersNeverRan: roll.neverRan,
428	});
429	
430	// Minutes of a person's time the parked work represents. Scheduler faults are NOT in
431	// it: a broken scheduler is not a queue of tasks to work through, and adding it would
432	// make the figure mean two different things at once.
433	export function estimateMinutes(counts) {
434	  const c = attentionCounts(counts);
435	  return (c.broken + c.decisions + c.approvals + c.tripping) * MINUTES_PER_PARK;
436	}
437	
438	// WHAT the human attention is, not how much of it there is. "3 members need you"
439	// is the length of this morning's list; it does not say whether that is three merges
440	// to approve or three broken lanes, and those are not the same morning.
441	//
442	// The split already exists one level down — `summariseMember` separates a failure
443	// park from an inbox park from an approval park precisely because a page that rings
444	// identically for all of them teaches its reader to ignore the ring — and the rollup
445	// used to throw it away and re-merge them into one word.
446	//
447	// Ordered worst first, and a kind nobody is waiting on is absent rather than zero.
448	export function attentionBreakdown(counts) {
449	  const c = attentionCounts(counts);
450	  const n = (count, one, many) => `${count} ${count === 1 ? one : many}`;
451	  return [
452	    c.broken && { level: 'critical', text: `${n(c.broken, 'task', 'tasks')} broken` },
453	    c.schedulersFailing && { level: 'critical', text: `${n(c.schedulersFailing, 'scheduler', 'schedulers')} failing` },
454	    c.decisions && { level: 'serious', text: `${n(c.decisions, 'item', 'items')} needing a decision` },
455	    c.tripping && { level: 'serious', text: `${n(c.tripping, 'item', 'items')} tripping a recovery rule` },
456	    c.approvals && { level: 'warning', text: `${n(c.approvals, 'item', 'items')} needing approval` },
457	    c.schedulersNeverRan && { level: 'serious', text: `${n(c.schedulersNeverRan, 'scheduler', 'schedulers')} never ran` },
458	  ].filter(Boolean);
459	}
460	
461	// Which packs the fleet uses, and how widely. Answers the question the canon actually
462	// asks of its fleet — "who would a change to this pack reach" — which no single
463	// member's page can.
464	export function packSpread(summaries) {
465	  const counts = new Map();
466	  for (const s of summaries) {
467	    for (const p of s.packs ?? []) counts.set(p, (counts.get(p) ?? 0) + 1);
468	  }
469	  return [...counts.entries()]
470	    .map(([pack, members]) => ({ pack, members }))
471	    .sort((a, b) => b.members - a.members || a.pack.localeCompare(b.pack));
472	}
473	
474	// Which tasks are running across the fleet, from the work items themselves. A task
475	// declared by a shared pack runs in many members, and its fleet-wide behaviour —
476	// especially a task that is parked in several at once — is a canon problem rather
477	// than any one member's.
478	export function taskSpread(reads, now) {
479	  const byTask = new Map();
480	  for (const read of reads) {
481	    for (const item of (read.items ?? []).filter(isWorkItem)) {
482	      const parsed = parseWorkItemTitle(item.title);
483	      if (!parsed) continue;
484	      const key = `${parsed.pack}/${parsed.task}`;
485	      if (!byTask.has(key)) byTask.set(key, { key, pack: parsed.pack, task: parsed.task, members: new Set(), open: 0, parked: 0, done: 0, failed: 0 });
486	      const row = byTask.get(key);
487	      row.members.add(read.repo);
488	      if (item.state === 'open') {
489	        row.open += 1;
490	        if (isParked(item)) row.parked += 1;
491	      } else {
492	        const outcome = outcomeOf(item);
493	        if (outcome === 'done' || outcome === 'delivered') row.done += 1;
494	        else if (outcome !== 'obsolete') row.failed += 1;
495	      }
496	    }
497	  }
498	  return [...byTask.values()]
499	    .map((r) => ({ ...r, members: r.members.size }))
500	    .sort((a, b) => b.parked - a.parked || b.members - a.members || a.key.localeCompare(b.key));
501	}
502	
503	export { URGENT };
504

file.content:
// The fleet view's derivation — many members' raw reads in, one ranked overview out.
// Pure: no clock, no I/O, no DOM.
//
// A fleet page answers a different question from the per-repo one. Per repo the
// question is "what is this scheduler doing"; across a fleet it is "WHERE DO I NEED
// TO LOOK", and a page that answers the first question twelve times over does not
// answer the second. So nothing here is a total for its own sake: every number is
// either something that needs a human, something that is about to, or the context
// needed to tell those apart.
//
// Three ideas do the work:
//
//   ATTENTION IS EARNED, NOT COUNTED. A member surfaces because something is true of
//   it — an item parked, a leash blown, a scheduler failing, a mount that stopped
//   converging — and each of those arrives as a REASON with a severity, not as a
//   number to be summed. The ranking is over the worst reason, so a member with one
//   parked item outranks one with forty healthy work items.
//
//   ABSENCE IS A STATE. A member that does not run Claudinite, one the viewer cannot
//   read, and one that is running fine are three different answers and never collapse
//   into "0". A fleet view whose blanks are ambiguous is worse than no fleet view.
//
//   ONE MEMBER'S FAILURE IS ONE ROW'S PROBLEM. Every member is summarised
//   independently and a read that failed becomes a row saying so, so a single private
//   repo or a rate-limit stumble cannot blank the page.

import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
import { periodMs } from '../../engine/scheduler/queue/anchors.mjs';
import {
  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN, URGENT,
  NEEDS_HUMAN_APPROVAL, outcomeOf, isParked,
} from '../../engine/scheduler/queue/work-item.mjs';
import { canonicalPackVersions } from '../../engine/pack_loader/renamed-packs.mjs';
import { VERSION_SOURCE, versionFromLiteral, isVersion, versionAbove } from '../../engine/version.mjs';
import { describeItem, isWorkItem, parseWorkItemTitle, taskDeclarationPaths } from './model.mjs';
import { commitDays } from './activity.mjs';

// Severity ladder, worst first. The order IS the sort, so it is stated once here
// rather than implied by comparisons scattered through the render.
export const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
const levelRank = (l) => {
  const i = LEVELS.indexOf(l);
  return i === -1 ? LEVELS.length : i;
};

const ms = (t) => (t == null ? null : new Date(t).getTime());

// --- the canon side of the comparison ---------------------------------------------

// The canon's versions are lifted as TEXT, like every declaration field: the page
// reads the canon over the API, where there is nothing to import. Comment-stripped
// so prose naming the field can never be mistaken for it, and null — never a guess —
// when the pattern is not there.
const ENGINE_VERSION_RE = new RegExp(String.raw`ENGINE_VERSION\s*=\s*'?(${VERSION_SOURCE})'?`);
const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[{,\s])version:\s*'?(${VERSION_SOURCE})'?`, 'm');

export function parseEngineVersion(text) {
  const m = ENGINE_VERSION_RE.exec(stripComments(String(text ?? '')));
  return m ? versionFromLiteral(m[1]) : null;
}

export function parsePackVersion(text) {
  const m = PACK_VERSION_RE.exec(stripComments(String(text ?? '')));
  return m ? versionFromLiteral(m[1]) : null;
}

// --- mount freshness ------------------------------------------------------------

// Whether a member's mount is current. Judged on the stamp's `engineVersion` and
// `packVersions` and NEVER on `ref` or `updated`: the versioned flows stamp versions
// and nothing else, so those two hold the provenance of the last FULL re-vendor —
// a member converging nightly carries a months-old ref and updated forever, and
// judging either reads every healthy member as behind or stalled (#1065; the same
// class as #786). `updated` travels through as display-only provenance.
//
// `canon` is the reference to compare against: its live `engineVersion` and the
// canon's own per-pack versions (`packVersions`, possibly partial — the loader
// fetches only the packs members actually stamp). A pack the canon side cannot
// price is counted `unknownPacks`, never silently judged current. With no canon
// supplied the honest answer is `unknown`, not `current`.
export function mountState(stamp, canon = null) {
  if (!stamp) return { state: 'none', engineVersion: null, updated: null };
  const engineVersion = stamp.engineVersion ?? null;
  // The stamp is stored data: a pack renamed since it was written still keys its
  // version under the old spelling, which must compare rather than read as unknown.
  const packVersions = stamp.packVersions ? canonicalPackVersions(stamp.packVersions) : null;
  const updated = stamp.updated ?? null;

  if (engineVersion == null && packVersions == null) {
    // A stamp with no versions predates the versioned flows entirely — this member
    // has not converged since they landed, which is its own kind of stale.
    return { state: 'unversioned', engineVersion, updated };
  }
  if (canon?.engineVersion == null) return { state: 'unknown', engineVersion, updated };

  if (isVersion(engineVersion) && versionAbove(canon.engineVersion, engineVersion)) {
    return { state: 'behind-engine', engineVersion, canonEngineVersion: canon.engineVersion, updated };
  }

  const behindPacks = [];
  let comparedPacks = 0;
  let unknownPacks = 0;
  for (const [pack, version] of Object.entries(packVersions ?? {})) {
    const canonVersion = canon.packVersions?.[pack];
    if (canonVersion == null) { unknownPacks += 1; continue; }
    comparedPacks += 1;
    if (versionAbove(canonVersion, version)) behindPacks.push({ pack, version, canonVersion });
  }
  if (behindPacks.length) {
    return { state: 'behind', engineVersion, behindPacks, comparedPacks, unknownPacks, updated };
  }
  return { state: 'current', engineVersion, comparedPacks, unknownPacks, updated };
}

// --- one member -----------------------------------------------------------------

// Everything a fleet row shows about one member, plus the reasons it needs looking
// at. `read` is what the loader managed to fetch; a member it could not read arrives
// with `error` set and every other field absent.
export function summariseMember(read, { now, canon = null } = {}) {
  const {
    repo, error = null, declaration = null, items = null, runs = null, paths = null,
    prs = null, head = null, stars = null, defaultBranch = null, commits = undefined,
  } = read ?? {};

  if (error) {
    // A read the page DECLINED to make is not the same fact as one it could not make:
    // the repo is fine, the budget is not, and the row must not read as a fault of the
    // member. It is raised a rung above a permissions miss because it is the one the
    // viewer can act on — sign in, or wait for the reset.
    const withheld = error?.status === 'budget';
    return {
      repo,
      status: withheld ? 'withheld' : 'unreadable',
      level: withheld ? 'warning' : 'info',
      error,
      // Not being able to read a member is not the member being broken. It is almost
      // always a private repo outside this viewer's grant, so it is reported at the
      // bottom of the page rather than raised as an alarm.
      reasons: [{ level: withheld ? 'warning' : 'info', text: describeReadError(error) }],
    };
  }

  if (!declaration) {
    return {
      repo,
      status: 'not-adopted',
      level: 'info',
      reasons: [{ level: 'info', text: 'does not run Claudinite' }],
    };
  }

  const work = (items ?? []).filter(isWorkItem);
  const open = work.filter((i) => i.state === 'open');
  const closed = work.filter((i) => i.state === 'closed');

  const declaredTasks = paths ? taskDeclarationPaths(paths, declaration).length : null;
  const periodFor = () => null;   // the fleet row needs no per-task cadence
  const described = open.map((i) => describeItem(i, now, { periodFor }));

  const byState = { [BLOCKED]: 0, [READY]: 0, [EXECUTING]: 0, [AGENT]: 0, [NEEDS_HUMAN]: 0, other: 0 };
  for (const d of described) {
    if (byState[d.state] === undefined) byState.other += 1;
    else byState[d.state] += 1;
  }

  const parked = described.filter((d) => d.state === NEEDS_HUMAN);
  // The triage split (tasks-dispatch DESIGN §4): a failure park — or one an older
  // engine left unclassified — holds its task's lane; an action or decision park is
  // a person's inbox; an approval park is a run that SUCCEEDED and waits on a merge.
  // Three different alarms, because a page that rings identically for all four
  // teaches the reader to ignore the ring.
  const holding = parked.filter((d) => d.blockingPark);
  const approvals = parked.filter((d) => !d.blockingPark && d.triage === NEEDS_HUMAN_APPROVAL);
  const inbox = parked.filter((d) => !d.blockingPark && d.triage !== NEEDS_HUMAN_APPROVAL);
  const warned = described.filter((d) => d.state !== NEEDS_HUMAN && d.warnings.length);

  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
  for (const i of closed) outcomes[outcomeOf(i) ?? 'none'] += 1;

  const lastActivity = closed
    .map((i) => ms(i.closed_at) ?? ms(i.updated_at))
    .filter(Boolean)
    .sort((a, b) => b - a)[0] ?? null;

  const runSummary = summariseRuns(runs ?? [], now);
  const ci = ciStatus(runs ?? [], defaultBranch);
  const mount = mountState(declaration.claudinite, canon);

  const n = (count, word) => `${count} ${word}${count > 1 ? 's' : ''}`;
  // Every reason carries a `kind`, because the row shows some of these twice
  // otherwise: parks have their own column with an estimate beside them, the mount
  // is a badge on the pack count, and CI is a dot. The RANKING still reads all of
  // them — a member is ordered by everything true of it — and only the rendering
  // drops what already has a cell of its own.
  const reasons = [];
  if (holding.length) {
    reasons.push({ kind: 'park', level: 'critical', text: `${n(holding.length, 'item')} parked broken — holding the task's lane` });
  }
  if (inbox.length) {
    reasons.push({ kind: 'park', level: 'serious', text: `${n(inbox.length, 'item')} parked for a person — an action or a decision` });
  }
  if (approvals.length) {
    reasons.push({ kind: 'park', level: 'warning', text: `${n(approvals.length, 'PR')} waiting for approval` });
  }
  if (runSummary.consecutiveFailures > 0) {
    reasons.push({
      kind: 'scheduler',
      level: runSummary.consecutiveFailures > 1 ? 'critical' : 'serious',
      text: `scheduler last run failed${runSummary.consecutiveFailures > 1 ? ` (${runSummary.consecutiveFailures} in a row)` : ''}`,
    });
  }
  if (warned.length) {
    reasons.push({ kind: 'park', level: 'serious', text: `${n(warned.length, 'item')} tripping a recovery rule` });
  }
  if (mount.state === 'behind-engine') {
    reasons.push({ kind: 'mount', level: 'serious', text: `mount is on engine v${mount.engineVersion}, canon is v${canon?.engineVersion}` });
  } else if (mount.state === 'behind') {
    reasons.push({ kind: 'mount', level: 'info', text: `mount behind canon on ${mount.behindPacks.map((p) => p.pack).join(', ')}` });
  } else if (mount.state === 'unversioned') {
    reasons.push({ kind: 'mount', level: 'warning', text: 'mount stamp carries no versions — it predates the versioned update flows' });
  } else if (mount.state === 'none') {
    reasons.push({ kind: 'mount', level: 'warning', text: 'declares Claudinite but carries no mount stamp' });
  }
  // A repo that declares tasks and has never produced a work item is not idle — its
  // scheduler is not running. That is invisible in every per-repo number here, which
  // is exactly why the fleet view is the place it shows up.
  if (declaredTasks !== null && declaredTasks > 0 && work.length === 0) {
    reasons.push({ kind: 'scheduler', level: 'serious', text: `${declaredTasks} task${declaredTasks > 1 ? 's' : ''} declared, no work item ever created` });
  }
  if (ci.state === 'failing') {
    // The member's own CI, said in the member's own words: this is not the scheduler
    // failing, and the two must not read as the same alarm.
    reasons.push({ kind: 'ci', level: 'warning', text: 'the repo\'s own CI is failing on its default branch' });
  }
  if (declaration.packs?.length === 0) {
    reasons.push({ kind: 'packs', level: 'warning', text: 'declares no packs' });
  }

  const level = reasons.length ? reasons.map((r) => r.level).sort((a, b) => levelRank(a) - levelRank(b))[0] : 'ok';

  return {
    repo,
    status: 'adopted',
    level,
    reasons,
    packs: (declaration.packs ?? []).map((p) => (typeof p === 'string' ? p : p?.id)).filter(Boolean),
    declaredTasks,
    open: { total: open.length, byState, urgent: described.filter((d) => d.urgent).length },
    parked: parked.length,
    parkedHolding: holding.length,
    parkedApprovals: approvals.length,
    parkedInbox: inbox.length,
    warned: warned.length,
    closedSeen: closed.length,
    outcomes,
    lastActivity,
    runs: runSummary,
    ci,
    stars,
    lastCommit: head?.committedAt ? ms(head.committedAt) : null,
    // Null all the way through when the read did not happen, so the row draws "not
    // read" rather than an empty quarter that reads as a repo nobody touched.
    commits: commitDays(commits, { now }),
    work: humanWork(items, prs, now),
    mount,
    schedule: declaration.taskScheduler ?? null,
  };
}

// A read that failed says something different depending on how. 404 on a repo the
// roster names is almost always "not shared with this viewer", which is a permissions
// fact rather than a fault.
function describeReadError(error) {
  const status = error?.status;
  if (status === 'budget') return 'not read — this page is holding back your last requests; sign in or wait for the reset';
  if (status === 404) return 'not visible to you — the roster names it, your credential cannot see it';
  if (status === 403) return 'forbidden — rate limit, or your credential lacks access';
  if (status === 401) return 'your credential was rejected';
  return error?.message ? `unreadable — ${error.message}` : 'unreadable';
}

// The repo's OWN CI, which is a different question from the scheduler's health: one
// says whether this project builds, the other whether Claudinite is running here. They
// are read from the same list and must never be conflated — a green scheduler on a
// repo whose tests are red is not a healthy member.
//
// The default branch's most recent completed run is the answer; a `schedule` run is
// excluded because that is the queue's own scheduler run, reported separately.
export function ciStatus(runs, defaultBranch) {
  const mine = (runs ?? []).filter((r) => r.event !== 'schedule'
    && (!defaultBranch || !r.head_branch || r.head_branch === defaultBranch));
  const inFlight = mine.some((r) => r.status === 'in_progress' || r.status === 'queued');
  const last = mine.find((r) => r.status === 'completed');
  if (!last) return { state: inFlight ? 'running' : 'unknown', at: null, name: null };
  const state = last.conclusion === 'success' ? 'passing'
    : (last.conclusion === 'cancelled' || last.conclusion === 'skipped') ? 'unknown'
      : 'failing';
  return { state: inFlight ? 'running' : state, at: ms(last.created_at), name: last.name ?? null, url: last.html_url ?? null };
}

// What is waiting on a PERSON here, as opposed to on the queue: issues that are not
// Claudinite work items, and open pull requests. Both come out of the issue page the
// row already reads, so this costs nothing and stops at that window — an issue older
// than the window is not counted, and the panel says the window is a window.
export function humanWork(items, prs, now) {
  const open = (items ?? []).filter((i) => i.state === 'open' && !isWorkItem(i));
  const oldest = (list) => list.map((i) => ms(i.created_at)).filter(Boolean).sort((a, b) => a - b)[0] ?? null;
  const openPrs = (prs ?? []).filter((p) => !p.draft);
  return {
    issues: open.length,
    issuesOldest: oldest(open),
    prs: openPrs.length,
    drafts: (prs ?? []).length - openPrs.length,
    prsOldest: oldest(openPrs),
    now,
  };
}

// The scheduler's own health. Only the workflow that drives the queue matters here —
// a failing unrelated CI run is the repo's business, not the fleet scheduler's — so
// runs are filtered to scheduled ones before anything is counted.
export function summariseRuns(runs, now) {
  const scheduled = runs.filter((r) => r.event === 'schedule');
  const completed = scheduled.filter((r) => r.status === 'completed');
  const inFlight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued').length;

  // Consecutive failures from the most recent backwards: one failure is noise, a run
  // of them is a member that has stopped working.
  let consecutiveFailures = 0;
  for (const r of completed) {
    if (r.conclusion === 'success') break;
    if (r.conclusion === 'cancelled' || r.conclusion === 'skipped') continue;
    consecutiveFailures += 1;
  }

  const lastAt = scheduled.map((r) => ms(r.created_at)).filter(Boolean).sort((a, b) => b - a)[0] ?? null;

  return {
    scheduled: scheduled.length,
    inFlight,
    consecutiveFailures,
    lastAt,
    // No scheduled run at all is not "healthy" — it is "we have never seen this
    // member's scheduler", which the row must be able to say.
    everRan: scheduled.length > 0,
  };
}

// --- the fleet ------------------------------------------------------------------

// Worst first, then by how much is waiting. Ties break on the repo name so the order
// is stable across loads — a table that reshuffles under you is unreadable.
export function rankMembers(summaries) {
  return [...summaries].sort((a, b) =>
    levelRank(a.level) - levelRank(b.level)
    || (b.parked ?? 0) - (a.parked ?? 0)
    || (b.warned ?? 0) - (a.warned ?? 0)
    || (b.open?.total ?? 0) - (a.open?.total ?? 0)
    || a.repo.localeCompare(b.repo));
}

// The headline numbers. Each is a count of MEMBERS needing something, not a count of
// things — "3 members need you" is actionable where "47 open items" is not.
export function rollUp(summaries) {
  const adopted = summaries.filter((s) => s.status === 'adopted');
  const outcomes = { done: 0, delivered: 0, obsolete: 0, none: 0 };
  for (const s of adopted) for (const [k, v] of Object.entries(s.outcomes ?? {})) outcomes[k] += v;

  return {
    members: summaries.length,
    adopted: adopted.length,
    notAdopted: summaries.filter((s) => s.status === 'not-adopted').length,
    unreadable: summaries.filter((s) => s.status === 'unreadable').length,
    withheld: summaries.filter((s) => s.status === 'withheld').length,
    needAttention: adopted.filter((s) => levelRank(s.level) <= levelRank('serious')).length,
    parkedMembers: adopted.filter((s) => s.parked > 0).length,
    parkedItems: adopted.reduce((n, s) => n + s.parked, 0),
    parkedHolding: adopted.reduce((n, s) => n + (s.parkedHolding ?? 0), 0),
    parkedInbox: adopted.reduce((n, s) => n + (s.parkedInbox ?? 0), 0),
    parkedApprovals: adopted.reduce((n, s) => n + (s.parkedApprovals ?? 0), 0),
    warnedItems: adopted.reduce((n, s) => n + (s.warned ?? 0), 0),
    warnedMembers: adopted.filter((s) => s.warned > 0).length,
    failingMembers: adopted.filter((s) => s.runs?.consecutiveFailures > 0).length,
    neverRan: adopted.filter((s) => s.runs && !s.runs.everRan).length,
    behindMembers: adopted.filter((s) => ['behind', 'behind-engine', 'unversioned'].includes(s.mount?.state)).length,
    openItems: adopted.reduce((n, s) => n + (s.open?.total ?? 0), 0),
    inFlight: adopted.reduce((n, s) => n + (s.runs?.inFlight ?? 0), 0),
    declaredTasks: adopted.reduce((n, s) => n + (s.declaredTasks ?? 0), 0),
    outcomes,
  };
}

// --- what a person is actually holding -------------------------------------------

// What one parked item costs a person, in minutes. A flat rate deliberately: the page
// has no measurement of how long a park actually takes, and the honest way to publish
// a number nothing measures is to publish the ASSUMPTION and let it be argued with,
// rather than to dress a guess up as a per-kind estimate. Refine it here, in one
// place, when there is something real to refine it from.
export const MINUTES_PER_PARK = 7;

// The vocabulary both the per-member row and the fleet rollup speak, so one function
// itemises both. Each field is a count of THINGS waiting; the two callers differ only
// in whether their things are one member's or the whole fleet's.
const attentionCounts = ({
  broken = 0, decisions = 0, approvals = 0, tripping = 0,
  schedulersFailing = 0, schedulersNeverRan = 0,
} = {}) => ({ broken, decisions, approvals, tripping, schedulersFailing, schedulersNeverRan });

// One member's attention, in the same shape the rollup uses.
export const memberAttention = (s) => attentionCounts({
  broken: s.parkedHolding ?? 0,
  decisions: s.parkedInbox ?? 0,
  approvals: s.parkedApprovals ?? 0,
  tripping: s.warned ?? 0,
});

// The fleet's. Schedulers are counted in MEMBERS here rather than in items, because a
// scheduler is a member-shaped thing — there is one per repo.
export const fleetAttention = (roll) => attentionCounts({
  broken: roll.parkedHolding,
  decisions: roll.parkedInbox,
  approvals: roll.parkedApprovals,
  tripping: roll.warnedItems,
  schedulersFailing: roll.failingMembers,
  schedulersNeverRan: roll.neverRan,
});

// Minutes of a person's time the parked work represents. Scheduler faults are NOT in
// it: a broken scheduler is not a queue of tasks to work through, and adding it would
// make the figure mean two different things at once.
export function estimateMinutes(counts) {
  const c = attentionCounts(counts);
  return (c.broken + c.decisions + c.approvals + c.tripping) * MINUTES_PER_PARK;
}

// WHAT the human attention is, not how much of it there is. "3 members need you"
// is the length of this morning's list; it does not say whether that is three merges
// to approve or three broken lanes, and those are not the same morning.
//
// The split already exists one level down — `summariseMember` separates a failure
// park from an inbox park from an approval park precisely because a page that rings
// identically for all of them teaches its reader to ignore the ring — and the rollup
// used to throw it away and re-merge them into one word.
//
// Ordered worst first, and a kind nobody is waiting on is absent rather than zero.
export function attentionBreakdown(counts) {
  const c = attentionCounts(counts);
  const n = (count, one, many) => `${count} ${count === 1 ? one : many}`;
  return [
    c.broken && { level: 'critical', text: `${n(c.broken, 'task', 'tasks')} broken` },
    c.schedulersFailing && { level: 'critical', text: `${n(c.schedulersFailing, 'scheduler', 'schedulers')} failing` },
    c.decisions && { level: 'serious', text: `${n(c.decisions, 'item', 'items')} needing a decision` },
    c.tripping && { level: 'serious', text: `${n(c.tripping, 'item', 'items')} tripping a recovery rule` },
    c.approvals && { level: 'warning', text: `${n(c.approvals, 'item', 'items')} needing approval` },
    c.schedulersNeverRan && { level: 'serious', text: `${n(c.schedulersNeverRan, 'scheduler', 'schedulers')} never ran` },
  ].filter(Boolean);
}

// Which packs the fleet uses, and how widely. Answers the question the canon actually
// asks of its fleet — "who would a change to this pack reach" — which no single
// member's page can.
export function packSpread(summaries) {
  const counts = new Map();
  for (const s of summaries) {
    for (const p of s.packs ?? []) counts.set(p, (counts.get(p) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([pack, members]) => ({ pack, members }))
    .sort((a, b) => b.members - a.members || a.pack.localeCompare(b.pack));
}

// Which tasks are running across the fleet, from the work items themselves. A task
// declared by a shared pack runs in many members, and its fleet-wide behaviour —
// especially a task that is parked in several at once — is a canon problem rather
// than any one member's.
export function taskSpread(reads, now) {
  const byTask = new Map();
  for (const read of reads) {
    for (const item of (read.items ?? []).filter(isWorkItem)) {
      const parsed = parseWorkItemTitle(item.title);
      if (!parsed) continue;
      const key = `${parsed.pack}/${parsed.task}`;
      if (!byTask.has(key)) byTask.set(key, { key, pack: parsed.pack, task: parsed.task, members: new Set(), open: 0, parked: 0, done: 0, failed: 0 });
      const row = byTask.get(key);
      row.members.add(read.repo);
      if (item.state === 'open') {
        row.open += 1;
        if (isParked(item)) row.parked += 1;
      } else {
        const outcome = outcomeOf(item);
        if (outcome === 'done' || outcome === 'delivered') row.done += 1;
        else if (outcome !== 'obsolete') row.failed += 1;
      }
    }
  }
  return [...byTask.values()]
    .map((r) => ({ ...r, members: r.members.size }))
    .sort((a, b) => b.parked - a.parked || b.members - a.members || a.key.localeCompare(b.key));
}

export { URGENT };

