1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `model.test.mjs` pins. Living inside `engine/scheduler/`
12	// makes the queue modules siblings, so the dashboard sits beside the mechanism it
13	// renders rather than reaching across the tree at it.
14	//
15	// `stripComments` is the one remaining cross-tree reach, and it is deliberate:
16	// `file-placement` flags it advisory and its own remedy sanctions exactly this case.
17	// Shortening it would mean copying a comment-stripper nearer, and a second stripper
18	// that drifts from the canonical one is worse than the distance.
19	
20	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
21	import { mostRecentAnchor, nextAnchor, periodMs } from '../../engine/scheduler/queue/anchors.mjs';
22	import {
23	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
24	} from '../../engine/scheduler/queue/leases.mjs';
25	import {
26	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
27	  outcomeOf as decodeOutcome,
28	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
29	  statusesOn, isParked, parkKindOf, triageLabelFor,
30	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
31	  NEEDS_HUMAN_FAILURE, isBlockingPark, parseLastVerdict,
32	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
33	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, hasLabel, labelNames,
