35	
36	export {
37	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
38	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
39	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
40	};
41	
42	// How long a due item may sit blocked before the page calls the scheduler run out. The scheduler run
43	// is the repo's one cron, hourly; two fires of slack keeps a single late fire from
44	// reading as a fault. Not an engine constant because nothing engine-side measures
45	// this — the scheduler run readies due items on its next fire, whenever that is.
46	export const DUE_SLACK_MS = 2 * 3600e3;
47	
48	const ms = (t) => (t == null ? null : new Date(t).getTime());
49	
50	// --- where a declared pack's tasks live ---------------------------------------
51	
52	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
53	// activation (core's rule), and the mount carries packs a repo never declared. So
54	// the roster is built from the declaration list, and a task directory belonging to
55	// an undeclared pack is skipped rather than rendered greyed-out.
56	//
57	// Two roots, because the same code reads the canon home and a member: the home
58	// runs from the repo root (`packs/<id>`), a member from the mount
59	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
60	// from `.claudinite/local/packs/<name>` in both.
61	export function declaredPackDirs(config) {
62	  const dirs = new Map();
63	  for (const entry of config?.packs ?? []) {
64	    const id = typeof entry === 'string' ? entry : entry?.id;
65	    if (!id) continue;
66	    if (id.startsWith('local/')) {
67	      const name = id.slice('local/'.length);
68	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
69	    } else {
70	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
71	    }
72	  }
73	  return dirs;
74	}
75	
76	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.mjs$/;
77	
78	// Every declared pack's task declarations, from one recursive tree listing.
79	// `paths` is the flat list of blob paths the tree API returned.
80	export function taskDeclarationPaths(paths, config) {
81	  const dirs = declaredPackDirs(config);
82	  const found = [];
83	  for (const path of paths ?? []) {
84	    const m = TASK_PATH_RE.exec(path);
85	    if (!m) continue;
86	    const [, packDir, task] = m;
87	    for (const [pack, roots] of dirs) {
88	      if (roots.includes(packDir)) found.push({ pack, task, path });
89	    }
90	  }
91	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
92	}
93	
94	// --- reading a task declaration -----------------------------------------------
95	
96	// The declaration is a JS object literal, and the page reads it as TEXT: it renders
97	// other repos over the API, where there is nothing to import and no Node to import
98	// it with. So the scalar fields are lifted by pattern, over comment-stripped source
99	// — the engine's own `stripComments`, so a `// frequency: 'weekly'` in a task's
100	// header prose can never be mistaken for the declaration.
101	//
102	// A field this cannot read comes back NULL and renders as "unknown". It is never
103	// defaulted: a task whose declaration this misreads must look unreadable, because a
104	// plausible wrong frequency would silently move a next-anchor the whole roster is
105	// read for.
106	// The key must open the line or follow a `{` / `,` — anchoring on the line start
107	// alone would miss a declaration written on one line, and anchoring on nothing
108	// would let `code_work` be found inside `agent_code_work`. The value may close on a
109	// comma, the object's brace, or the line's end, so a last field without a trailing
110	// comma still reads.
111	const at = (field) => `(?:^|[{,])\\s*${field}:\\s*`;
112	
113	const scalar = (src, field) => {
114	  const m = new RegExp(`${at(field)}(?:'([^']*)'|"([^"]*)"|(\\d+)|(true|false))\\s*(?=[,}\\n]|$)`, 'm').exec(src);
115	  if (!m) return null;
116	  if (m[3] !== undefined) return Number(m[3]);
117	  if (m[4] !== undefined) return m[4] === 'true';
118	  return m[1] ?? m[2];
119	};
120	
121	const stringArray = (src, field) => {
122	  const m = new RegExp(`${at(field)}\\[([^\\]]*)\\]`, 'm').exec(src);
123	  if (!m) return null;
124	  return [...m[1].matchAll(/'([^']*)'|"([^"]*)"/g)].map((x) => x[1] ?? x[2]);
125	};
126	
127	export function parseDeclaration(text) {
128	  const src = stripComments(String(text ?? ''));
129	  return {
130	    id: scalar(src, 'id'),
131	    frequency: scalar(src, 'frequency'),
132	    agent_model: scalar(src, 'agent_model'),
133	    expected_outcome: scalar(src, 'expected_outcome'),
134	    interrupt_policy: scalar(src, 'interrupt_policy'),
135	    code_work: scalar(src, 'code_work'),
136	    agent_execution_timeout: scalar(src, 'agent_execution_timeout'),
137	    precondition_signals: stringArray(src, 'precondition_signals'),
138	    // A task may decline to run; whether it CAN is the difference between "did not
139	    // run" being routine and being a fault, so the roster shows it.
140	    has_precondition: /^\s*(?:async\s+)?precondition\s*\(/m.test(src),
141	  };
142	}
143	
144	// --- work items ----------------------------------------------------------------
145	
146	// An item is a filed `[claudinite-work]` issue OR an adopted marked issue — the
147	// one-issue request model's other shape, which keeps the person's own title
148	// (tasks-dispatch DESIGN §16.1). One definition, shared with the queue's own reader.
149	export { isQueueItem as isWorkItem } from '../../engine/scheduler/queue/read.mjs';
150	
151	// The page's five state keys, one per decoded status. The keys are the engine's
152	// own constants rather than the canonical spellings, because a page groups the four
153	// park kinds under one "needs human" column and routes by the kind separately
154	// (`triageOf`).
155	const STATE_KEY = new Map([
156	  [STATUS_BLOCKED, BLOCKED], [STATUS_READY, READY],
157	  [STATUS_RUNNING_EXECUTOR, EXECUTING], [STATUS_RUNNING_AGENT, AGENT],
158	]);
159	
160	// The one state an open item is in, decoded from whatever spelling filed it, or
161	// `unlabelled` for an item wearing none — which is not a display quirk but the
162	// torn-label-swap leavings the janitor repairs, so it gets its own rendered state
163	// rather than being folded into "blocked".
164	export function stateOf(item) {
165	  if (item?.state === 'closed') return 'closed';
166	  if (isParked(item)) return NEEDS_HUMAN;
167	  const worn = statusesOn(item).filter((s) => STATE_KEY.has(s));
168	  if (worn.length === 1) return STATE_KEY.get(worn[0]);
169	  if (worn.length > 1) return 'torn';
170	  return 'unlabelled';
171	}
172	
173	// What the park is asking for, or null for an item that is not parked. A park whose
174	// kind cannot be decoded — an older engine's bare one, a word a newer engine
175	// invented — reads as `failure`, the lane that says "someone diagnose this".
176	export const triageOf = (item) => (isParked(item) ? triageLabelFor(parkKindOf(item)) : null);
177	
178	const TRIAGE_TEXT = {
179	  [NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
180	  [NEEDS_HUMAN_ACTION]: 'something to change outside the code',
181	  [NEEDS_HUMAN_DECISION]: 'a decision to make',
182	  [NEEDS_HUMAN_FAILURE]: 'a break to diagnose, holding the task\'s lane',
183	};
184	
185	// The outcome as its canonical word ('done' | 'delivered' | 'obsolete' | null) —
186	// the engine's decoder, which maps every legacy spelling straight to today's.
187	export const outcomeOf = decodeOutcome;
188	
189	// How long the item has sat where it is. Every transition is a label write, so
190	// `updated_at` is the last touch — the same quantity the janitor's rules count.
191	const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));
192	
193	// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
194	// what the page flags is what the engine will actually act on — and how long the
195	// viewer waits for it.
196	//
197	// `isOpen(number)` answers whether a `Blocked-by` issue is still open — true, false,
198	// or null for one outside what the caller fetched. Unknown is never alarmed on.
199	export function warningsFor(item, now, { periodFor = () => null, isOpen = () => null } = {}) {
200	  const out = [];
201	  const state = stateOf(item);
202	  const idle = idleMs(item, now);
203	  if (state === EXECUTING && idle >= EXECUTING_LEASH_MS) {
204	    out.push({ level: 'serious', text: 'executing past the leash — the next scheduler run reclaims it' });
205	  }
206	  if (state === AGENT && idle >= AGENT_LEASH_MS) {
207	    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
208	  }
209	  if (state === READY) {
210	    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
211	    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
212	  }
213	  if (state === BLOCKED) {
214	    // The standing-item model: blocked is the queue's healthy quiet state, not a
215	    // fault. A rolled item waiting out its Not-before never warns; what does warn is
216	    // the two things the engine would actually act on — dependencies unresolved past
217	    // the janitor's threshold, and an item DUE that the scheduler run has failed to ready.
218	    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
219	    const wake = ms(notBefore);
220	    const depStates = blockedBy.map((n) => isOpen(n));
221	    if (wake !== null && wake > ms(now)) {
222	      // waiting out its stamped wake — healthy, whatever its age
223	    } else if (depStates.some((s) => s === true)) {
224	      if (idle >= STUCK_BLOCKED_MS) {
225	        out.push({ level: 'warning', text: `blocked on ${blockedBy.map((n) => `#${n}`).join(', ')} for over 2 days — the janitor flags stuck dependencies` });
226	      }
227	    } else if (!depStates.some((s) => s === null)) {
228	      // Nothing blocks it any more: the next scheduler run readies it. Due only measures from
229	      // the stamped wake — with dependencies the closing time is not on this item,
230	      // and a guess would alarm on an item that became due minutes ago.
231	      if (wake !== null && ms(now) - wake >= DUE_SLACK_MS) {
232	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
233	      } else if (wake === null && blockedBy.length === 0 && idle >= DUE_SLACK_MS) {
234	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
235	      }
236	    }
237	  }
238	  if (state === NEEDS_HUMAN) {
239	    // What the park is asking for, and whether it is holding the task's lane —
240	    // an approval waiting on a reviewer is not the same alarm as a broken run
241	    // that has stopped its task being scheduled at all.
242	    const t = triageOf(item);
243	    out.push({
244	      level: isBlockingPark(item) ? 'critical' : 'warning',
245	      text: t ? `parked for a human — ${TRIAGE_TEXT[t]}` : 'parked for a human — unclassified, holding the task\'s lane',
246	    });
247	  }
248	  if (state === 'torn') out.push({ level: 'warning', text: 'wearing more than one state label' });
249	  if (state === 'unlabelled') out.push({ level: 'warning', text: 'open with no state label' });
250	  return out;
251	}
252	
253	// An open item, decorated with everything the queue lane renders.
254	export function describeItem(item, now, opts = {}) {
255	  // A marked issue keeps the person's own title, so its task comes from the worker
256	  // path its machine block names — without that the page would render every request
257	  // run as an item belonging to no task at all.
258	  const parsed = parseWorkItemTitle(item.title)
259	    ?? (taskIdFromPath(parseWorkItemBody(item.body).taskPath) ? { ...taskIdFromPath(parseWorkItemBody(item.body).taskPath), qualifier: null } : null)
260	    ?? { pack: null, task: null, qualifier: null };
261	  const body = parseWorkItemBody(item.body);
262	  const state = stateOf(item);
263	  return {
264	    number: item.number,
265	    key: parsed.pack && parsed.task ? `${parsed.pack}/${parsed.task}` : null,
266	    ...parsed,
267	    state,
268	    outcome: outcomeOf(item),
269	    triage: triageOf(item),
270	    blockingPark: state === NEEDS_HUMAN && isBlockingPark(item),
271	    urgent: hasLabel(item, URGENT),
272	    labels: labelNames(item),
273	    notBefore: body.notBefore,
274	    blockedBy: body.blockedBy,
275	    taskPath: body.taskPath,
276	    // The roll's record: when the last ask declined, why, and the stamped wake.
277	    lastVerdict: parseLastVerdict(item.body),
278	    createdAt: item.created_at,
279	    updatedAt: item.updated_at,
280	    closedAt: item.closed_at ?? null,
281	    idleMs: idleMs(item, now),
282	    comments: item.comments ?? 0,
283	    warnings: warningsFor(item, now, opts),
284	  };
285	}
286	
287	// --- the roster ----------------------------------------------------------------
288	
289	// One row per DECLARED task, whether or not it has ever run — a task that has never
290	// produced an item is exactly the interesting case, and an issue-derived list would
291	// omit it entirely.
292	export function buildRoster({ tasks = [], items = [], now, schedule, isOpen }) {
293	  const byKey = new Map();
294	  for (const it of items) {
295	    const p = parseWorkItemTitle(it.title);
296	    if (!p) continue;
297	    const key = `${p.pack}/${p.task}`;
298	    if (!byKey.has(key)) byKey.set(key, []);
299	    byKey.get(key).push(it);
300	  }
301	
302	  return tasks.map((t) => {
303	    const key = `${t.pack}/${t.task}`;
304	    const mine = (byKey.get(key) ?? []).slice()
305	      .sort((a, b) => ms(b.created_at) - ms(a.created_at));
306	    const open = mine.filter((i) => i.state === 'open');
307	    const closed = mine.filter((i) => i.state === 'closed');
308	    const freq = t.declaration?.frequency ?? null;
309	
310	    // A frequency this could not read yields no anchor rather than a guessed one,
311	    // and `manual` genuinely has none — the two are different and render differently.
312	    let next = null;
313	    let anchorNote = null;
314	    if (freq === 'manual') anchorNote = 'manual — only a hand-created item';
315	    else if (!freq) anchorNote = 'frequency unknown';
316	    else if (!schedule) anchorNote = 'no schedule configured';
317	    else next = nextAnchor(freq, schedule, now);
318	
319	    const current = open.length
320	      ? describeItem(open[0], now, { periodFor: () => (freq ? periodMs(freq) : null), isOpen })
321	      : null;
322	
323	    return {
324	      key,
325	      pack: t.pack,
326	      task: t.task,
327	      path: t.path,
328	      declaration: t.declaration ?? null,
329	      frequency: freq,
330	      nextAnchor: next,
331	      anchorNote,
332	      periodMs: freq && freq !== 'manual' ? periodMs(freq) : null,
333	      current,
334	      nextAsk: nextAskOf(current, next, anchorNote),
335	      openCount: open.length,
336	      lastClosed: closed.length ? describeItem(closed[0], now) : null,
337	      history: closed.map((i) => describeItem(i, now)),
338	    };
339	  });
340	}
341	
342	// What will actually happen to this task next, derived from the standing item where
343	// one exists — the calendar answers only when no item does (the next instantiation).
344	// This is where the standing-item model's facts become the roster's advice:
345	//   - the stamped Not-before IS the schedule (DESIGN §14, S28), so it wins over the
346	//     computed anchor;
347	//   - a blocking park stops the task being scheduled at all (§4) — showing an anchor
348	//     there would promise a run that will never be filed;
349	//   - a non-blocking park consumed its occurrence but leaves the lane open, so the
350	//     next anchor stands beside it.
351	function nextAskOf(current, anchor, anchorNote) {
352	  if (!current) return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
353	  if (current.state === READY) return { kind: 'ready', urgent: current.urgent };
354	  if (current.state === EXECUTING || current.state === AGENT) {
355	    return { kind: 'running', phase: current.state === AGENT ? 'agent' : 'executor' };
356	  }
357	  if (current.state === NEEDS_HUMAN) {
358	    if (current.blockingPark) return { kind: 'held' };
359	    return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
360	  }
361	  if (current.state === BLOCKED) {
362	    if (current.notBefore) return { kind: 'wake', at: new Date(current.notBefore) };
363	    return current.blockedBy.length ? { kind: 'deps', on: current.blockedBy } : { kind: 'ready-soon' };
364	  }
365	  // torn / unlabelled — off the state machine until the janitor repairs it.
366	  return { kind: 'off-machine' };
367	}
368	
369	// Outcome tallies over the closed items the scan actually saw. `scanned` travels
370	// with them: every count here is over a window, and a window is not "all of it".
371	export function outcomeTally(rows) {
372	  const t = { done: 0, delivered: 0, obsolete: 0, none: 0 };
373	  for (const r of rows) for (const h of r.history) t[h.outcome ?? 'none'] += 1;
374	  return t;
375	}
376	
377	// --- the protocol comments ------------------------------------------------------
378	
379	// Which of the three markers a comment carries. The markers are HTML comments so a
380	// human reading the issue sees prose; the page shows the protocol beat instead.
381	export function commentKind(body) {
382	  const b = String(body ?? '');
383	  if (b.includes(EPISODE_MARKER)) return 'episode';
384	  if (b.includes(HANDOFF_MARKER)) return 'handoff';
385	  if (b.includes(CLAIM_MARKER)) return 'claim';
386	  return null;
387	}
388

