242	  .chart-card.digest h3 { font-size: 14px; margin: 0; letter-spacing: 0; text-transform: none; }
243	  .chart-card.digest h4 { font-size: 12px; margin: 6px 0 0; color: var(--ink-2); font-weight: 600;
244	                          letter-spacing: 0; text-transform: none; }
245	  .chart-card.digest p { margin: 0; color: var(--ink-2); }
246	  .chart-card.digest ul.digest-items { margin: 0; padding-left: 18px; color: var(--ink-2); }
247	  .chart-card.digest ul.digest-items li { margin-bottom: 6px; }
248	  .movement .k { font-size: 12px; color: var(--ink-2); margin: 2px 0 6px; }
249	
250	  tr.pending-row td { color: var(--muted); }
251	  #fleet-progress { font-size: 12px; color: var(--muted); margin: 0 0 10px; }
252	  .pill { font-size: 12px; border: 1px solid var(--border); border-radius: 999px;
253	          padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
254	  .pill.warn-pill { border-color: var(--serious); color: var(--serious); }
255	  .pill.stop-pill { border-color: var(--critical); color: var(--critical); }
256	  .notice { border-left: 3px solid var(--serious); background: var(--surface);
257	            padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; color: var(--ink-2); }
258	  .notice b { color: var(--ink); }
259	
260	  .empty { padding: 22px; text-align: center; color: var(--muted); }
261	  .err { border-left: 3px solid var(--critical); background: var(--surface);
262	         padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; }
263	  /* The explainer rides in the topbar and opens OVER the page. It answers a question
264	     you have once — "what is this thing doing with my credential" — and as a block in
265	     the flow it pushed the content it explains down the screen on every load after
266	     that one. `position: fixed` rather than absolute: the topbar is sticky, and an
267	     absolutely-positioned panel inside it is clipped by the bar's own height. */
268	  details.setup { position: relative; }
269	  details.setup > summary { cursor: pointer; list-style: none; font-size: 12px;
270	                  border: 1px solid var(--border); border-radius: 999px;
271	                  padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
272	  details.setup > summary::-webkit-details-marker { display: none; }
273	  details.setup > summary:hover { border-color: var(--ink-2); color: var(--ink); }
274	  details.setup[open] > summary { border-color: var(--ink-2); color: var(--ink); }
275	  .setup-body { position: fixed; top: 52px; right: 20px; z-index: 20; width: min(480px, calc(100vw - 40px));
276	                max-height: calc(100vh - 72px); overflow: auto;
277	                background: var(--surface); border: 1px solid var(--border);
