// What the fleet DID — the counterpart to every other derivation here, which answers
// where to look. Pure: no clock, no I/O, no DOM.
//
// The page's panels are all fault-finding, and fault-finding has a blind spot: after
// a good week every count is zero, so a healthy fleet and a dead one render
// identically. Nothing on the page can tell them apart, because "nothing is wrong" and
// "nothing happened" are the same picture. This module is the other reading — closed
// work, scheduler runs, and which members moved at all — over a window of days.
//
// EVERY NUMBER COMES FROM A READ THE PAGE ALREADY MAKES. A per-member call to get a
// commit count would undo the budget work the whole client is built around, so the
// inputs are exactly the fleet loader's existing per-member reads: the first page of
// issues, the recent Actions runs, and the head commit whose date arrives with the sha
// the content cache is keyed by. Nothing here adds a request.
//
// WHAT THAT COSTS IS DEPTH, AND DEPTH IS DECLARED. One issue page is the most recent
// hundred issues by creation, and one runs page is the most recent thirty runs — so a
// day at the far end of the window is under-read rather than empty, and every series
// carries the horizon past which it stops being a count and starts being a floor.

import { isParked, outcomeOf } from '../../engine/scheduler/queue/work-item.mjs';
import { isWorkItem } from './model.mjs';

export const DAY_MS = 86400e3;

const ms = (t) => (t == null ? null : new Date(t).getTime());

// A UTC day. The queue's anchors, the digests' file names and GitHub's timestamps are
// all UTC, so a local-time bucketing would put a member's midnight run on the wrong
// day depending on who is looking.
export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);

// The window's days, oldest first, including today. Built from keys rather than from
// arithmetic on a rendered date so a DST-free UTC ladder is the only thing anyone has
// to trust.
export function dayLadder(now, days) {
  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
}

// --- the daily series -----------------------------------------------------------

// Work closed, runs finished and members moving, per day. `reads` is the fleet
// loader's raw per-member reads; a member that could not be read contributes nothing
// and is counted as unread rather than as a quiet day.
export function activitySeries(reads, { now, days = 14 } = {}) {
  const ladder = dayLadder(now, days);
  const index = new Map(ladder.map((d, i) => [d, i]));
  const blank = () => ladder.map((day) => ({
    day,
    work: { done: 0, delivered: 0, obsolete: 0, none: 0 },
    workClosed: 0,
    otherClosed: 0,
    runs: { success: 0, failure: 0, other: 0 },
    movers: new Set(),
  }));

  const series = blank();
  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);
  // The oldest thing each read could see. A day before this is under-read for that
  // member — not quiet — and the series says so rather than drawing a confident zero.
  let issueHorizon = null;
  let runHorizon = null;
  const seen = (at, keep) => {
    const t = ms(at);
    if (t == null) return keep;
    return keep == null ? t : Math.max(keep, t);
  };

  for (const read of readable) {
    const items = read.items ?? [];
    let oldestIssue = null;
    for (const i of items) {
      const created = ms(i.created_at);
      if (created != null) oldestIssue = oldestIssue == null ? created : Math.min(oldestIssue, created);
      if (i.state !== 'closed') continue;
      const at = ms(i.closed_at) ?? ms(i.updated_at);
      const slot = at == null ? undefined : index.get(dayKey(at));
      if (slot === undefined) continue;
      series[slot].movers.add(read.repo);
      if (isWorkItem(i)) {
        series[slot].workClosed += 1;
        series[slot].work[outcomeOf(i) ?? 'none'] += 1;
      } else {
        series[slot].otherClosed += 1;
      }
    }
    // A member whose page-1 window does not reach the start of the ladder truncates
    // the series for everyone, so the horizon is the LATEST such floor across members.
    if (!read.itemsComplete && oldestIssue != null) issueHorizon = seen(oldestIssue, issueHorizon);

    let oldestRun = null;
    for (const r of read.runs ?? []) {
      const at = ms(r.created_at);
      if (at == null) continue;
      oldestRun = oldestRun == null ? at : Math.min(oldestRun, at);
      const slot = index.get(dayKey(at));
      if (slot === undefined) continue;
      series[slot].movers.add(read.repo);
      const bucket = r.status !== 'completed' ? 'other'
        : r.conclusion === 'success' ? 'success'
          : (r.conclusion === 'failure' || r.conclusion === 'timed_out' || r.conclusion === 'startup_failure') ? 'failure'
            : 'other';
      series[slot].runs[bucket] += 1;
    }
    if (oldestRun != null) runHorizon = seen(oldestRun, runHorizon);

    // The default branch's tip. One date, so it marks the day that member last
    // landed something — not a commit count, and never drawn as one.
    const tip = ms(read.head?.committedAt);
    const tipSlot = tip == null ? undefined : index.get(dayKey(tip));
    if (tipSlot !== undefined) series[tipSlot].movers.add(read.repo);
  }

  const rows = series.map((d) => ({ ...d, movers: [...d.movers].sort(), moved: d.movers.size }));
  const movedInWindow = new Set(rows.flatMap((d) => d.movers));

  return {
    days: rows,
    from: ladder[0],
    to: ladder[ladder.length - 1],
    members: readable.length,
    unread: (reads ?? []).filter((r) => r?.error).length,
    moved: [...movedInWindow].sort(),
    quiet: readable.map((r) => r.repo).filter((r) => !movedInWindow.has(r)).sort(),
    totals: {
      workClosed: rows.reduce((n, d) => n + d.workClosed, 0),
      otherClosed: rows.reduce((n, d) => n + d.otherClosed, 0),
      runs: rows.reduce((n, d) => n + d.runs.success + d.runs.failure + d.runs.other, 0),
      runsFailed: rows.reduce((n, d) => n + d.runs.failure, 0),
    },
    // The day before which the series is a floor rather than a count, per source. Null
    // means every read reached past the window and the whole ladder is a real count.
    horizon: {
      issues: issueHorizon != null && issueHorizon > now - days * DAY_MS ? dayKey(issueHorizon) : null,
      runs: runHorizon != null && runHorizon > now - days * DAY_MS ? dayKey(runHorizon) : null,
    },
  };
}

// --- what the machinery bought --------------------------------------------------

// The window's work, and the same window before it. Two rules shape what may appear
// here, and both are the owner's:
//
//   NO VANITY TOTAL. Every figure is bounded by a window, because a number that only
//   grows says nothing about today. The comparison is against the preceding window of
//   the same length, so "more than last week" is a fact and not a feeling.
//
//   NOTHING INVENTED. No estimated hours, no saved-effort multiplier, no score. Each
//   figure is a count of things that are individually true and individually clickable.
//   A quantity nothing on this page measures does not get a tile with a guess in it.
export function fleetBenefits(reads, { now, windowDays = 7, digests = null } = {}) {
  const span = windowDays * DAY_MS;
  const readable = (reads ?? []).filter((r) => r && !r.error && r.declaration);

  const inWindow = (t, from, to) => t != null && t >= from && t < to;

  const window = (from, to) => {
    let completed = 0;
    let unattended = 0;
    let parked = 0;
    let runs = 0;
    let runsFailed = 0;
    const members = new Set();

    for (const read of readable) {
      for (const i of (read.items ?? []).filter(isWorkItem)) {
        // Decoded, never a literal label test: a member's items wear whatever
        // spelling the engine that filed them wrote (work-item's `statusOf`).
        const wasParked = isParked(i);
        // An item that needed a person is counted whether or not it has closed —
        // being parked IS the event, and the ones still sitting there are the whole
        // point. `updated_at` is when its label was last written, which is the
        // closest thing the queue leaves to "when it was handed over".
        if (wasParked && inWindow(ms(i.updated_at), from, to)) parked += 1;

        if (i.state !== 'closed') continue;
        const at = ms(i.closed_at) ?? ms(i.updated_at);
        if (!inWindow(at, from, to)) continue;
        const outcome = outcomeOf(i);
        if (outcome === 'done' || outcome === 'delivered') {
          completed += 1;
          members.add(read.repo);
          // The parked label is the record of a human being pulled in: the queue puts
          // it on when a run cannot finish itself, and takes it off only when the item
          // is re-queued by hand. An item that closed without wearing it therefore ran
          // start to finish with nobody in the loop AT THE POINT IT CLOSED — an item
          // triaged and re-queued earlier in its life counts here too, and the panel
          // says so rather than claiming more than the labels can carry.
          if (!wasParked) unattended += 1;
        }
      }
      for (const r of read.runs ?? []) {
        if (!inWindow(ms(r.created_at), from, to)) continue;
        if (r.status !== 'completed') continue;
        runs += 1;
        if (r.conclusion !== 'success' && r.conclusion !== 'skipped' && r.conclusion !== 'cancelled') runsFailed += 1;
      }
    }
    return { completed, unattended, parked, runs, runsFailed, members: members.size };
  };

  const current = window(now - span, now + 1);
  const previous = window(now - 2 * span, now - span);

  // Converging is read off each member's own stamp, which carries ONE date — the last
  // converge. So this is a count for the current window only and never a comparison:
  // a member that converged this morning cannot also be counted for last week, and
  // pretending the previous window's figure means the same thing would make a healthy
  // fleet look like it had stopped.
  const converged = readable.filter((r) => {
    const at = ms(r.declaration?.claudinite?.updated);
    return at != null && at >= now - span;
  }).length;

  return {
    windowDays,
    current,
    previous,
    members: readable.length,
    converged,
    // Whatever the digests panel actually found on disk, so this counts files that
    // exist rather than days the task was scheduled for.
    digests: digests == null ? null : digests.filter((d) => d?.text).length,
  };
}

// A window-over-window change, in the only form that is honest when the previous
// window may itself be under-read: the delta, and which way it points.
export function delta(current, previous) {
  if (!Number.isFinite(current) || !Number.isFinite(previous)) return { dir: 'flat', by: 0 };
  const by = current - previous;
  return { dir: by > 0 ? 'up' : by < 0 ? 'down' : 'flat', by: Math.abs(by) };
}

// --- one member's commit history -------------------------------------------------

// The last N days of a member's commits, as a flat oldest-first ladder — the shape a
// GitHub-style square grid draws straight from.
//
// The input is `/stats/commit_activity`: 52 weeks, each a UTC-Sunday start and seven
// daily counts. This is the ONE read on the fleet page that is not derived from
// something already fetched, which is why it is priced as decoration everywhere it
// appears — and why its three empty answers must stay distinguishable. `null` is "not
// read" (withheld, or GitHub still computing the statistics) and is NOT the same fact
// as an array of zeroes, which is a repo that genuinely did nothing.
//
// A day the year does not cover is `null` rather than `0` for the same reason: a
// window wider than the data is under-read at its far end, not quiet there.
export function commitDays(weeks, { now, days = 90 } = {}) {
  if (!Array.isArray(weeks)) return null;

  const byDay = new Map();
  for (const w of weeks) {
    const start = Number(w?.week);
    if (!Number.isFinite(start)) continue;
    (w.days ?? []).forEach((count, i) => {
      byDay.set(dayKey(start * 1000 + i * DAY_MS), Number(count) || 0);
    });
  }

  const ladder = dayLadder(now, days);
  const rows = ladder.map((day) => ({ day, count: byDay.has(day) ? byDay.get(day) : null }));
  const counted = rows.filter((r) => r.count != null);
  return {
    days: rows,
    buckets: bucketWeekly(rows),
    total: counted.reduce((n, r) => n + r.count, 0),
    peak: counted.reduce((n, r) => Math.max(n, r.count), 0),
    // Days inside the window the year of statistics did not reach. Stated rather than
    // drawn as blank squares that read as quiet ones.
    unread: rows.length - counted.length,
  };
}

// The same window in weeks, which is the resolution a QUARTER of history is legible
// at. Drawn daily, an ordinary repo's weekend is a trough and a Tuesday a spike, so a
// 90-point curve across a column is a sawtooth that hides the only thing the column is
// for: whether this repo is being worked on, and whether it always was.
//
// The daily counts are kept — they are the total, the peak and the hover — and only
// the drawn line is smoothed. Weeks run back from today, so the OLDEST bucket is the
// short one, and a week is null only when every day in it was unread; a week that was
// partly read is a real sum over what there was.
const WEEK = 7;

export function bucketWeekly(rows) {
  const out = [];
  for (let end = rows.length; end > 0; end -= WEEK) {
    const slice = rows.slice(Math.max(0, end - WEEK), end);
    const read = slice.filter((r) => r.count != null);
    out.unshift({
      from: slice[0].day,
      to: slice[slice.length - 1].day,
      days: slice.length,
      count: read.length ? read.reduce((n, r) => n + r.count, 0) : null,
    });
  }
  return out;
}

// claudinite-dashboard — a browser view of what a repo's (or a fleet's) Claudinite
// scheduler is doing, published as a static site.
//
// WHY A PACK AND NOT ENGINE CODE. The dashboard is not part of running the scheduler:
// nothing converges, scheduler runs or executes because it exists, and a member that never
// looks at it should not carry it. Engine code is what every member runs; this is
// content a member OPTS INTO, and adoptable content in this corpus is a pack. That
// also buys it the things a pack has and engine code does not — its own version and
// migration lane, a declaration that gates it, and an adoption moment at which its
// deployment can be wired.
//
// WHAT IT READS. Only the queue's own vocabulary and the task declarations at HEAD,
// through the engine modules that define them (`../../engine/scheduler/queue/*`), so
// the page cannot drift from the mechanism it renders. Those relative paths resolve
// identically in the canon (`packs/<id>/` beside `engine/`) and in a member's mount
// (`.claudinite/shared/packs/<id>/` beside `.claudinite/shared/engine/`), which is
// why the pack can be read straight out of the mount with nothing rewritten.
//
// NO PROSE. There is no way to write the dashboard wrongly in a consuming repo — it is
// a page, not a practice — and prose here would cost every session in every declaring
// repo tokens for something no session acts on. Its README carries the explanation
// instead and `prose` stays null.
//
// TWO CHECKS, AND A TASK, ALL THE DIGEST'S. `tasks/fleet-digest/` writes the fleet's
// dated morning brief that the fleet page reads (it moved here from the `claudinite-fleet-sheepdog`
// pack, which enumerated the fleet but never showed anyone the result). Its two checks
// live in its own folder because nothing else reads them: `digest-plain-text` holds the
// landed briefs to plain text — they are sent verbatim through a renderer that neither
// parses markdown nor keeps line breaks — and `dated-fixture-collision` keeps the
// task's own test fixtures out of the year range the fleet writes real briefs in.
//
// THE TASK IS NOT GATED, and that is the cost of declaring this pack: a repo that wants
// only the page gets the digest task too, and the task needs `FLEET_GITHUB_TOKEN` to
// read every repo under the owner. Without that secret the executor parks its item
// asking for one. The README says so where someone deciding to adopt will read it.
//
// PUBLISHING IS THE ADOPTION MOMENT. `.github/workflows/` is the one directory the
// nightly update can never push to (the Action's `GITHUB_TOKEN` is refused there), so
// a deploy workflow can only arrive by being SEEDED — written by the install flow and
// committed by the adopting session, which holds a credential the Action does not.
// Hence the `seedOps` entry: adopting the pack is what wires the Pages deploy, and
// the workflow is the member's from the moment it lands.
//
// THE BUILD SCRIPT DELIBERATELY IS NOT SEEDED. `build-site.mjs` lives in the pack and
// is read out of the mount by the seeded workflow, exactly as the scheduler stub reads
// the engine's scheduler run. So the assembly logic keeps converging with the canon while the
// workflow — the part that cannot converge — stays a one-time seed. Only the file that
// has to be frozen is frozen.
import datedFixtureCollision from './tasks/fleet-digest/dated-fixture-collision.mjs';
import digestPlainText from './tasks/fleet-digest/digest-plain-text.mjs';
import { fleetTokenHandoverStep } from './tasks/fleet-digest/fleet-token.mjs';

export default {
  id: 'claudinite-dashboard',
  // 7: the fleet-digest task arrives from the claudinite-fleet-sheepdog pack, with its two checks. A
  // declaring repo gains a daily task; nothing in a member is rewritten, and the task
  // still reads an enforcer's existing `claudinite-fleet-sheepdog` config as its legacy source, so the
  // bump carries no migration record.
  // 8: the FLEET_GITHUB_TOKEN the digest needs is stated once, in its own
  // fleet-token.mjs, and rendered into the missing-secret message, the adoption step
  // and a 403's hint — additive, no migration (#1030).
  // 9: adoption hands over the sign-in decision as well as the Pages setting — prose
  // and a handover entry, so a member gains a checkbox and nothing else changes.
  // 10: the page carries a favicon — a file the mount has to deliver, so the version
  // moves; nothing in a member's tree changes shape and there is no migration.
  // 11: mount freshness judged on stamped versions against the canon's live ones
  // (never ref/updated), and the scheduler panels re-derived for the standing-item
  // model — next asks, roll records, triage-split parks. Page-only; no migration.
  // 12: the workflow-practice neighbour is git-github now that github-actions
  // collapsed into it (#1079).
  // 60820.1: versions become date-anchored (#1100) — the counter this list is written
  // in retires here, and every pack in the canon restarts from the same day.
  // 60820.2: fleet-digest's machine-issue filter learns the schedule board's
  // `[claudinite-schedule]` title (#1115).
  // 60821.1: item state, triage and parked counts are decoded from the label
  // vocabulary rather than matched literally, so a member's items read the same
  // whichever engine filed them (#1119).
  version: '60821.1',
  minEngineVersion: 4,
  ruleRoutingGuidance: {
    belongs: 'the browser dashboard over Claudinite scheduler state, the site that publishes it, and the fleet morning brief it reads',
    excludes: 'how the scheduler behaves — core; workflow practice — git-github; product sites — static-website',
  },
  badge: 'badge.svg',

  // Never fingerprinted. Nothing in a repo's shape implies wanting a dashboard, and a
  // scan that suspected one from the presence of a scheduler would suspect it in every
  // member on the fleet.
  detect: null,
  marker: null,
  seededByDefault: false,

  // A page, not a practice — see the header.
  prose: null,
  // Audits the landed briefs and the task's own fixtures as they stand, whatever this
  // session touched: a markdown brief that landed last week is just as unreadable in the
  // owner's inbox as one that landed today.
  worldRules: [digestPlainText, datedFixtureCollision],
  workRules: [],

  // Nothing to ask. Every fork this pack has is answered by a default that is right for
  // nearly every project: a member's dashboard shows that member, signs in with a
  // pasted token, and compares against no canon. The fleet deployment — one repo, not
  // twelve — says so in its declaration's `config`, which is read as optional
  // throughout: an unset key is the default, never a misconfiguration.
  //
  // config keys, all optional:
  //   canonRepo   — the reference member mounts are compared against (fleet view)
  //   rosterUrl   — a roster artifact; more than one member makes the fleet the landing view
  //   repos       — an inline roster instead of a URL
  //   clientId    — GitHub App / OAuth App client id, for the sign-in button
  //   exchangeUrl — the code-to-token endpoint that sign-in needs
  //   digestsRepo — where the fleet's morning briefs are written; unset turns that panel off
  //   digestsPath — the directory inside it (defaults to `digests`)
  //   owner       — whose repos the fleet-digest task covers (defaults to this repo's owner)
  //   exclude     — repos it keeps out (defaults to none)
  //   digest      — { pick, nudge } — how many items a brief names, and the quiet-project prod
  questions: [],

  // The one step adoption CANNOT take, stated where the install flow can print it and
  // the adopting session can file it. Enabling Pages is a repository setting, and
  // `actions/configure-pages`' own `enablement` input cannot do it with the Action's
  // `GITHUB_TOKEN` — it needs a PAT with `repo`, or an app with `administration:write`.
  // Holding a credential that wide, in every member, to save one click is a far worse
  // trade than naming the click. So it is named.
  //
  // In a README this would be met after the first deploy had already failed; here it
  // arrives at the moment someone is present and the pack is new.
  adoptionHandover: [
    {
      step: 'Enable GitHub Pages on this repo with source "GitHub Actions" (Settings → Pages).',
      breaks: 'the deploy job fails on every run; the build still succeeds, so nothing else is affected',
      done: 'the Pages URL serves the dashboard, and the Claudinite dashboard workflow is green',
    },
    // The fleet-digest task's credential, and a person is the only one who can mint it.
    // RENDERED from the task's own fleet-token.mjs rather than written here, so the
    // human granting it is handed the complete list: a message stating only what the
    // read in front of it needed is how a fleet went two days short one permission
    // (#1030).
    fleetTokenHandoverStep(),
    // ONE entry, not the four mechanical steps, because for many deployments the right
    // answer is "nothing" — a member's own dashboard read with a pasted token is on the
    // same 5,000/hour as a signed-in one. What every adopter does have to meet is the
    // DECISION, since until someone makes it their page reads GitHub anonymously; four
    // unconditional checkboxes that are mostly no-ops teach the reader to skim exactly
    // the list that exists to stop them skimming. The mechanics live in the README,
    // where they are read at the moment the answer is yes.
    {
      step: 'Decide how this dashboard authenticates its viewers: leave it on the pasted-token box (nothing to do), '
        + 'or give it a Sign in button — register a GitHub App with read-only Contents, Issues and Actions, install it on '
        + 'the account holding these repos, deploy the pack\'s oauth-exchange example, and set `clientId` and `exchangeUrl` '
        + 'on this pack\'s declaration. See "Who has to register the app" in the pack README: one App serves every '
        + 'deployment you own, and none can be inherited from another owner.',
      breaks: 'nothing fails, but a viewer who has not pasted a token reads GitHub anonymously at 60 requests/hour per IP — '
        + 'which one fleet sweep exceeds, so the page serves cached data or empty rows until the hour rolls',
      done: 'a signed-in viewer sees the rate pill read “…/5000 · user”, or this repo has recorded that the token box is '
        + 'this deployment\'s answer',
    },
  ],

  // Seeded, never converged: `.github/workflows/` cannot be written by the nightly, so
  // this arrives once, at adoption, and the repo owns it from there. It is a thin shim
  // over `build-site.mjs` in the mount for exactly that reason — the part that cannot
  // be updated is kept as small as possible.
  seedOps: [
    {
      template: 'stubs/workflows/claudinite-dashboard-pages.yml',
      dest: '.github/workflows/claudinite-dashboard-pages.yml',
    },
  ],
};

content.content:
1	// The fleet overview: every member at once, worst first, with a way into any one of
2	// them. `fleet.mjs` decides what the rows MEAN; this file fetches and draws them.
3	
4	import * as gh from './github.mjs';
5	import {
6	  summariseMember, rankMembers, rollUp, packSpread, taskSpread, attentionBreakdown,
7	  memberAttention, fleetAttention, estimateMinutes, MINUTES_PER_PARK,
8	  parseEngineVersion, parsePackVersion,
9	} from './fleet.mjs';
10	import { canonicalPackVersions } from '../../engine/pack_loader/renamed-packs.mjs';
11	import { activitySeries, fleetBenefits, delta, commitDays } from './activity.mjs';
12	import { digestDates, digestPath, digestEntry } from './digest.mjs';
13	import {
14	  $, el, ago, duration, groupedHead, columnCount, groupStarts, emptyRow, repoLink, tiles, segmentBar,
15	  reasonNodes, stackedColumns, chartLegend, windowFigure, starMark, ciMark, commitGraph, packMark,
16	  LEVEL_GLYPH, STATE_ORDER, STATE_COLOR, STATE_UI, OUTCOME_COLOR,
17	} from './ui.mjs';
18	
19	// Members are read concurrently, but not all at once: a dozen members at six calls
20	// each is enough parallel load to trip secondary rate limiting, and the page is not
21	// in a hurry. Small and steady beats a burst that gets throttled.
22	const CONCURRENCY = 4;
23	
24	async function pool(items, worker, limit = CONCURRENCY) {
25	  const out = new Array(items.length);
26	  let next = 0;
27	  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
28	    for (;;) {
29	      const i = next; next += 1;
30	      if (i >= items.length) return;
31	      out[i] = await worker(items[i], i);
32	    }
33	  });
34	  await Promise.all(runners);
35	  return out;
36	}
37	
38	// One member's raw reads. Everything is wrapped: a member that 404s, times out or is
39	// rate-limited becomes a row that SAYS SO, because one unreadable repo must not blank
40	// the other eleven.
41	async function readMember(repo, token, { withTree = true } = {}) {
42	  try {
43	    const meta = await gh.getRepo(repo, token);
44	    // The head commit, kept whole: its date is when this member last landed anything,
45	    // and it arrives in the call the content cache already makes for the sha.
46	    const head = await gh.getHead(repo, meta.default_branch, token);
47	    const sha = head.sha;
48	    const configText = await gh.getTextAtSha(repo, sha, '.claudinite-checks.json', token);
49	
50	    let declaration = null;
51	    if (configText) {
52	      try { declaration = JSON.parse(configText); } catch { declaration = null; }
53	    }
54	
55	    // A member that does not run Claudinite needs no further reads — and skipping
56	    // them is most of the saving on a fleet where not everything is adopted.
57	    if (!declaration) return { repo, declaration: null, defaultBranch: meta.default_branch, head, stars: meta.stars };
58	
59	    const [tree, issuePage, runs, commits] = await Promise.all([
60	      withTree ? gh.listTreeAtSha(repo, sha, token).catch(() => null) : Promise.resolve(null),
61	      // One page is the whole live queue plus recent history, which is all a fleet row
62	      // needs. Deep history is the per-repo view's job.
63	      gh.listIssues(repo, token, { pages: 1 }).catch(() => ({ issues: [] })),
64	      // No per-page of its own: the repo view reads the same URL, and a different
65	      // depth here would be a second cache entry for one question.
66	      gh.listRuns(repo, token).catch(() => []),
67	      // Decoration, and the only read here that is. It withholds itself when the
68	      // budget is tight, and a failure is a row without a graph rather than a row
69	      // that could not be read.
70	      gh.commitActivity(repo, token).catch(() => null),
71	    ]);
72	
73	    return {
74	      repo,
75	      declaration,
76	      defaultBranch: meta.default_branch,
77	      stars: meta.stars,
78	      archived: meta.archived,
79	      sha,
80	      head,
81	      paths: tree?.paths ?? null,
82	      items: issuePage.issues,
83	      // Whether that page reached the end of this member's history. The activity
84	      // series needs it to tell a quiet day from a day it simply could not see.
85	      itemsComplete: issuePage.complete,
86	      prs: issuePage.prs ?? [],
87	      runs,
88	      commits,
89	    };
90	  } catch (error) {
91	    return { repo, error };
92	  }
93	}
94	
95	// The canon reference the mount column compares against. Optional by design: with no
96	// `canonRepo` configured the column reads `unknown` rather than inventing `current`,
97	// and no repo name is ever hardcoded in engine code.
98	//
99	// The reference is VERSIONS, never a sha: the versioned flows stamp members with
100	// `engineVersion`/`packVersions` only, so the canon side is the live `ENGINE_VERSION`
101	// out of `engine/version.mjs` plus each pack's `version:` out of its `pack.mjs` —
102	// lifted as text like every declaration field, sha-cached like every content read.
103	// Pack versions are fetched LAZILY, only for packs some member actually stamps: a
104	// fleet's union of declared packs is around a dozen reads where the full canon
105	// catalog is three times that, and a warm load pays for none of them.
106	async function readCanon(config, token) {
107	  if (!config?.canonRepo) return null;
108	  try {
109	    const repo = config.canonRepo;
110	    const meta = await gh.getRepo(repo, token);
111	    const ref = await gh.getHeadSha(repo, meta.default_branch, token);
112	    // Two-root form: the reference is normally the canon itself (repo root), but a
113	    // mount carries both files too, so a deployment pointed at a member still reads.
114	    const at = async (path) => (await gh.getTextAtSha(repo, ref, path, token))
115	      ?? (await gh.getTextAtSha(repo, ref, `.claudinite/shared/${path}`, token));
116	
117	    const engineVersion = parseEngineVersion(await at('engine/version.mjs'));
118	    const packVersions = {};
119	    const pending = new Map();
120	    const packVersion = (id) => {
121	      // A local pack lives in the member's own tree — the canon has no version for it.
122	      if (!id || id.startsWith('local/')) return Promise.resolve(null);
123	      if (!pending.has(id)) {
124	        pending.set(id, (async () => {
125	          const v = parsePackVersion(await at(`packs/${id}/pack.mjs`).catch(() => null));
126	          if (v != null) packVersions[id] = v;
127	          return v;
128	        })());
129	      }
130	      return pending.get(id);
131	    };
132	    return { repo, ref, engineVersion, packVersions, packVersion };
133	  } catch {
134	    return null;
135	  }
136	}
137	
138	// The last two days' briefs, from wherever the fleet keeps them. Optional in every
139	// direction: no `digestsRepo` configured means the panel is not part of this
140	// deployment, and a day with no file is a normal state rather than an error — the task
141	// had nothing to report, or has not run yet.
142	//
143	// Content at a path in a repo, so both reads are immutable-cacheable by sha and a warm
144	// load costs nothing. The 404 for a missing day is cached the same way, so a fleet
145	// whose digest task is idle does not re-ask every load.
146	async function readDigests(config, token) {
147	  if (!config?.digestsRepo) return null;
148	  const dates = digestDates(Date.now());
149	  try {
150	    const meta = await gh.getRepo(config.digestsRepo, token);
151	    const sha = await gh.getHeadSha(config.digestsRepo, meta.default_branch, token);
152	    return await Promise.all(dates.map(async (date) => {
153	      try {
154	        const text = await gh.getTextAtSha(config.digestsRepo, sha, digestPath(config.digestsPath, date), token);
155	        return digestEntry(date, text);
156	      } catch (error) {
157	        return digestEntry(date, null, error);
158	      }
159	    }));
160	  } catch (error) {
161	    // The repo itself could not be read — a permissions fact about the viewer, not a
162	    // statement about any day's brief. Every day reports it rather than reading as
163	    // "nothing was written".
164	    return dates.map((date) => digestEntry(date, null, error));
165	  }
166	}
167	
168	// --- render ---------------------------------------------------------------------
169	
170	// The member grid, as three questions rather than one wall of columns:
171	//
172	//   ACTIVITY    — is anyone working on this repo.
173	//   WAITING     — what is on a person's plate here, and roughly how long it is.
174	//   CLAUDINITE  — what the machinery is doing.
175	//
176	// They are in that order because it is the order a reader asks them in: a repo nobody
177	// touches and a repo with a queue behind it are different problems, and what the
178	// scheduler is doing only matters once you know which one you are looking at.
179	//
180	// The identity pair at the left belongs to none of them. Stars, CI and the name are
181	// how you recognise the row; the reasons beside them are why it is where it is.
182	//
183	// Every column but one is derived from a read the page ALREADY makes. Four fields the
184	// issue asked for are absent for that reason and not by oversight — rule tokens, test
185	// counts and time saved would each need a member's own file read, and conversation-log
186	// sessions a branch listing. They are named in the panel's own note rather than
187	// guessed at. The exception is the commit graph, which is priced as decoration.
188	//
189	// `Tasks — declared` is gone, and that one WAS a read the page makes: it is the whole
190	// reason each member's tree is fetched. The count answered "how much is wired up
191	// here", which the pack count answers more directly and without a number that means
192	// nothing until you know which packs. The tree is still read — "declares tasks and has
193	// never produced a work item" is a finding only it can make.
194	const MEMBER_GROUPS = [
195	  ['', ['Member']],
196	  ['Activity', ['Commits']],
197	  ['Waiting on a person', ['Est.', 'What it is', 'Issues', 'Pull requests']],
198	  ['Claudinite', ['Packs', 'Queue', 'Recent outcomes', 'Scheduler']],
199	];
200	
201	// The same split, one level down: a task's identity, where it stands right now, and
202	// what it has done. `Parked` sits under Now because it is a live state, not a record.
203	const FLEET_TASK_GROUPS = [
204	  ['', ['Task']],
205	  ['Now', ['Members', 'Open', 'Parked']],
206	  ['History', ['Succeeded', 'No outcome']],
207	];
208	
209	// Reason kinds the row already SHOWS somewhere of their own — parks in the Waiting
210	// group with an estimate beside them, the mount as a badge on the pack count, CI as a
211	// dot by the name. Spelling those out again in prose was the same fact twice and, at
212	// 180px of sentences, the column that decided how wide the whole grid was.
213	//
214	// What is left is rare and has no cell: "declares no packs", and a scheduler fault
215	// the runs column reports as a state but not as a sentence. So it goes UNDER THE NAME
216	// when there is any, and costs nothing on the rows — nearly all of them — where there
217	// is not. The ranking is untouched: `summariseMember` still weighs every reason, and
218	// only the rendering filters, so a member at the top for a park still shows its park
219	// one cell to the right.
220	//
221	// Kept beside the group list, because the two move together: folding a signal into a
222	// mark is what puts its kind in here.
223	const SHOWN_ELSEWHERE = new Set(['park', 'mount', 'ci']);
224	
225	const MEMBER_COLS = columnCount(MEMBER_GROUPS);
226	const MEMBER_STARTS = groupStarts(MEMBER_GROUPS);
227	
228	// The group's first cell carries the same rule the header band draws, so the three
229	// questions stay legible down the length of the table.
230	const banded = (cells) => cells.map((cell, i) => {
231	  if (MEMBER_STARTS.includes(i)) cell.classList.add('group-start');
232	  return cell;
233	});
234	
235	const CI_UI = {
236	  passing: { label: 'passing', cls: 'ok' },
237	  failing: { label: 'failing', cls: 'critical' },
238	  running: { label: 'running', cls: 'info' },
239	  unknown: { label: '—', cls: 'info' },
240	};
241	
242	function memberRow(s, onOpen, now) {
243	  const open = (e) => { e.preventDefault(); onOpen(s.repo); };
244	
245	  // Two marks ahead of the name, neither of them a column: stars say what KIND of
246	  // repo this is, and CI whether it builds. Both are read as part of identifying the
247	  // row rather than as findings, which is why they sit with the name and not in a
248	  // question group of their own.
249	  const ciUi = CI_UI[s.ci?.state] ?? CI_UI.unknown;
250	  const identity = (kids) => el('td', { className: 'member-cell' }, [el('div', { className: 'member' }, [
251	    starMark(s.stars),
252	    ciMark(ciUi, s.ci?.at ? duration(now - s.ci.at) : 'no run'),
253	    el('div', {}, [
254	      el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, className: 'name', textContent: s.repo.split('/')[1] ?? s.repo, onclick: open }),
255	      el('div', { className: 'sub' }, [repoLink(s.repo)]),
256	      ...kids,
257	    ]),
258	  ])]);
259	  const name = identity([]);
260	
261	  if (s.status !== 'adopted') {
262	    return el('tr', { className: `lvl-${s.level} muted-row` }, [
263	      name,
264	      el('td', { colSpan: MEMBER_COLS - 2 }, reasonNodes(s.reasons)),   // the last cell is the open link
265	      el('td', { className: 'nw' }, [el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, textContent: 'open', onclick: open })]),
266	    ]);
267	  }
268	
269	  // Whatever is left once every reason with a cell of its own is dropped — see
270	  // SHOWN_ELSEWHERE. Usually nothing, and then the name cell is the plain one.
271	  const spoken = s.reasons.filter((r) => !SHOWN_ELSEWHERE.has(r.kind));
272	  const identified = spoken.length ? identity(reasonNodes(spoken)) : name;
273	
274	  // --- Activity: is this repo being worked on ------------------------------------
275	
276	  // Where a single "3h ago" used to sit. One date says whether a repo moved today; a
277	  // quarter of them, as a shape, says whether it is being worked on — which is the
278	  // question the group is actually asking, and the reason it is no longer called
279	  // "Status".
280	  const commit = el('td', { className: 'nw' }, [
281	    commitGraph(s.commits, { note: s.lastCommit ? `last ${duration(now - s.lastCommit)}` : null }),
282	  ]);
283	
284	  // --- Waiting on a person -------------------------------------------------------
285	
286	  // The estimate, and immediately beside it what the estimate is made of. A number
287	  // with no breakdown is a number nobody can check; a breakdown with no total is a
288	  // list nobody can prioritise between rows.
289	  const attention = memberAttention(s);
290	  const minutes = estimateMinutes(attention);
291	  const est = el('td', { className: 'num nw' }, [
292	    el('div', { className: 'est num', textContent: minutes ? String(minutes) : '—' }),
293	    el('div', { className: 'sub', textContent: minutes ? 'min' : '' }),
294	  ]);
295	
296	  const needs = attentionBreakdown(attention);
297	  const what = el('td', {}, needs.length
298	    ? [el('div', { className: 'needs' }, needs.map((r) =>
299	      el('div', { className: `warn ${r.level}`, textContent: `${LEVEL_GLYPH[r.level]} ${r.text}` })))]
300	    : [el('span', { className: 'sub', textContent: 'nothing waiting' })]);
301	
302	  // --- Claudinite: what the machinery is doing here -------------------------------
303	
304	  // How much Claudinite is declared here, wearing whether it is current. Two facts
305	  // read together, and the second is a scheduler run on nearly every row — so it earns a
306	  // corner of the first rather than a column beside it, with the versions on hover.
307	  const packs = el('td', { className: 'nw' }, [packMark(s.packs.length, s.mount)]);
308	
309	  // Queue: the state mix as one thin bar plus the counts that are non-zero, so a
310	  // member with nothing open reads as empty rather than as a row of zeros.
311	  const counts = STATE_ORDER.filter((st) => s.open.byState[st] > 0)
312	    .map((st) => `${s.open.byState[st]} ${STATE_UI[st].label}`);
313	  const queue = el('td', {}, [
314	    segmentBar(STATE_ORDER.map((st) => [STATE_UI[st].label, s.open.byState[st], STATE_COLOR[st]]), { width: 92 }),
315	    el('div', { className: 'sub', textContent: counts.length ? counts.join(' · ') : 'nothing open' }),
316	  ]);
317	
318	  const outcomes = el('td', {}, [
319	    segmentBar([
320	      ['done', s.outcomes.done, OUTCOME_COLOR.done],
321	      ['delivered', s.outcomes.delivered, OUTCOME_COLOR.delivered],
322	      ['obsolete', s.outcomes.obsolete, OUTCOME_COLOR.obsolete],
323	      ['no outcome', s.outcomes.none, OUTCOME_COLOR.none],
324	    ], { width: 92 }),
325	    el('div', { className: 'sub', textContent: s.lastActivity ? ago(s.lastActivity, now) : (s.closedSeen ? 'unknown' : 'nothing closed yet') }),
326	  ]);
327	
328	  const runs = el('td', { className: 'nw' }, [
329	    el('div', {
330	      className: s.runs.consecutiveFailures ? 'warn critical' : 'sub',
331	      textContent: s.runs.consecutiveFailures
332	        ? `${LEVEL_GLYPH.critical} ${s.runs.consecutiveFailures} failing`
333	        : (s.runs.everRan ? 'passing' : 'never run'),
334	    }),
335	    el('div', { className: 'sub', textContent: s.runs.lastAt ? ago(s.runs.lastAt, now) : '—' }),
336	  ]);
337	
338	  // --- Work: what is waiting on a person ------------------------------------------
339	
340	  // Issues that are NOT queue items, and open pull requests. Both are inside the
341	  // issue page's window, so an old enough one is not counted — "in the window" is
342	  // said once under the table rather than in every cell.
343	  const issues = el('td', { className: 'num nw' }, [
344	    el('div', { textContent: String(s.work?.issues ?? 0) }),
345	    el('div', { className: 'sub', textContent: s.work?.issuesOldest ? `oldest ${duration(now - s.work.issuesOldest)}` : '—' }),
346	  ]);
347	
348	  const prs = el('td', { className: 'num nw' }, [
349	    el('div', { textContent: String(s.work?.prs ?? 0) }),
350	    el('div', {
351	      className: 'sub',
352	      textContent: s.work?.prsOldest
353	        ? `oldest ${duration(now - s.work.prsOldest)}${s.work.drafts ? ` · ${s.work.drafts} draft` : ''}`
354	        : (s.work?.drafts ? `${s.work.drafts} draft` : '—'),
355	    }),
356	  ]);
357	
358	  return el('tr', { className: `lvl-${s.level}` },
359	    banded([identified, commit, est, what, issues, prs, packs, queue, outcomes, runs]));
360	}
361	
362	// --- what the machinery bought ---------------------------------------------------
363	
364	// The block above everything else, and the only one that opens on what the machinery
365	// is FOR rather than on what is broken. Its content is decided in `activity.mjs`; the
366	// two rules that keep it honest are worth restating where it is drawn:
367	//
368	//   NO VANITY TOTAL. Every figure is this week's, against last week's. A number that
369	//   only ever grows is a decoration.
370	//
371	//   NOTHING INVENTED. No estimated hours saved, no multiplier, no score — only counts
372	//   of things that individually happened, from reads the page already made. Two
373	//   quantities the issue asked for are deliberately ABSENT rather than approximated:
374	//   checks enforced (a member's check count is not in any read this page makes) and
375	//   anything expressed in time saved (nothing measures it).
376	function renderBenefits(b) {
377	  const node = $('fleet-benefits');
378	  const runsPassed = b.current.runs - b.current.runsFailed;
379	  const prevPassed = b.previous.runs - b.previous.runsFailed;
380	
381	  // `replaceChildren` renders a null child as the text "null", so the optional tile is
382	  // filtered out rather than passed through.
383	  node.replaceChildren(...[
384	    windowFigure(b.current.completed, 'work items completed',
385	      delta(b.current.completed, b.previous.completed),
386	      `in ${b.current.members} member(s)`),
387	    windowFigure(b.current.unattended, 'of those, closed with nobody in the loop',
388	      delta(b.current.unattended, b.previous.unattended),
389	      'not parked for a human when it closed'),
390	    windowFigure(b.current.parked, 'items that did need a person',
391	      delta(b.current.parked, b.previous.parked),
392	      'the honest other half of the figure above', { better: 'down' }),
393	    windowFigure(runsPassed, 'scheduler runs passed',
394	      delta(runsPassed, prevPassed),
395	      b.current.runsFailed ? `${b.current.runsFailed} failed` : 'none failed'),
396	    // No delta: a mount stamp carries ONE date, so last week's figure would count
397	    // members whose last converge happens to sit in that window, not members that
398	    // converged then. A comparison built on that would read as a fleet slowing down.
399	    windowFigure(`${b.converged}/${b.members}`, 'members converged on their own', null,
400	      `in the last ${b.windowDays} days`),
401	    b.digests === null ? null
402	      : windowFigure(b.digests, 'digests written', null, 'of the last two days'),
403	  ].filter(Boolean));
404	}
405	
406	// --- the digests panel -----------------------------------------------------------
407	
408	const BLOCK_TAG = { title: 'h3', section: 'h4', item: 'li', para: 'p' };
409	
410	// One card per day. The brief is plain text by its writer's contract, so this is
411	// headings, paragraphs and links — never a Markdown renderer, which would be the wrong
412	// reader for the file and a dependency for a page that has none.
413	function digestCard(entry, repo, dir) {
414	  const kids = [el('div', { className: 'k', textContent: entry.date })];
415	
416	  if (entry.state === 'missing') {
417	    kids.push(el('p', { className: 'sub', textContent: 'No brief for this day — the digest task had nothing to report, or has not run.' }));
418	  } else if (entry.state === 'unreadable') {
419	    kids.push(el('p', { className: 'sub', textContent: `Not read — ${entry.error?.message ?? 'the digest repo could not be read'}.` }));
420	  } else if (entry.state === 'empty') {
421	    kids.push(el('p', { className: 'sub', textContent: 'The file for this day is empty.' }));
422	  }
423	
424	  let list = null;
425	  for (const b of entry.blocks) {
426	    const nodes = b.runs.map((r) => (r.href
427	      ? el('a', { href: r.href, target: '_blank', rel: 'noopener', textContent: r.text })
428	      : r.text));
429	    if (b.kind === 'item') {
430	      if (!list) { list = el('ul', { className: 'digest-items' }); kids.push(list); }
431	      list.append(el('li', {}, nodes));
432	      continue;
433	    }
434	    list = null;
435	    kids.push(el(BLOCK_TAG[b.kind] ?? 'p', {}, nodes));
436	  }
437	
438	  if (entry.state === 'written' && repo) {
439	    kids.push(el('div', { className: 'sub' }, [
440	      el('a', {
441	        href: `https://github.com/${repo}/blob/HEAD/${digestPath(dir, entry.date)}`,
442	        target: '_blank', rel: 'noopener', textContent: 'the file',
443	      }),
444	    ]));
445	  }
446	  return el('div', { className: 'chart-card digest' }, kids);
447	}
448	
449	function renderDigests(entries, config) {
450	  const section = $('fleet-digests-section');
451	  if (!entries) { section.hidden = true; return; }
452	  section.hidden = false;
453	  $('fleet-digests').replaceChildren(...entries.map((e) => digestCard(e, config?.digestsRepo, config?.digestsPath)));
454	}
455	
456	// --- the activity panel ----------------------------------------------------------
457	
458	// The one panel that answers "what has this fleet been doing". Everything else here
459	// is fault-finding, and fault-finding cannot distinguish a good week from a dead one:
460	// healthy means every count is zero, and so does abandoned.
461	//
462	// Two charts rather than one, because the two series answer different questions and
463	// share no scale: work CLOSED is the fleet's output, runs are the machinery that
464	// produced it, and stacking them together would let a noisy scheduler read as
465	// productivity.
466	const WORK_SERIES = [
467	  { label: 'done', color: OUTCOME_COLOR.done, value: (d) => d.work.done },
468	  { label: 'delivered', color: OUTCOME_COLOR.delivered, value: (d) => d.work.delivered },
469	  { label: 'obsolete', color: OUTCOME_COLOR.obsolete, value: (d) => d.work.obsolete },
470	  { label: 'no outcome', color: OUTCOME_COLOR.none, value: (d) => d.work.none },
471	  { label: 'other issues closed', color: 'var(--s-blue)', value: (d) => d.otherClosed },
472	];
473	
474	const RUN_SERIES = [
475	  { label: 'runs passed', color: 'var(--good)', value: (d) => d.runs.success },
476	  { label: 'runs failed', color: 'var(--critical)', value: (d) => d.runs.failure },
477	  { label: 'runs other', color: 'var(--muted)', value: (d) => d.runs.other },
478	];
479	
480	function renderActivity(series) {
481	  const charts = $('fleet-activity');
482	  const pass = series.totals.runs
483	    ? Math.round(((series.totals.runs - series.totals.runsFailed) / series.totals.runs) * 100)
484	    : null;
485	
486	  // Which members moved AT ALL. A fleet where two of twelve did anything is a fact
487	  // about the fleet, and it is invisible in any per-member row.
488	  const movement = el('div', { className: 'movement' }, [
489	    el('div', { className: 'v num', textContent: `${series.moved.length}/${series.members}` }),
490	    el('div', { className: 'k', textContent: 'members moved in the window' }),
491	    el('div', { className: 'sub', textContent: series.quiet.length ? `quiet: ${series.quiet.map((r) => r.split('/')[1] ?? r).join(', ')}` : 'every readable member did something' }),
492	    series.unread ? el('div', { className: 'sub', textContent: `${series.unread} member(s) unread — not counted either way` }) : null,
493	  ]);
494	
495	  charts.replaceChildren(
496	    el('div', { className: 'chart-card' }, [
497	      el('div', { className: 'k', textContent: `${series.totals.workClosed} work items closed · ${series.totals.otherClosed} other issues` }),
498	      chartLegend(WORK_SERIES),
499	      stackedColumns(series.days, WORK_SERIES),
500	      // A window that reaches past what one issue page holds is a floor, not a count,
501	      // and a chart that does not say so reads as a fleet that went quiet.
502	      series.horizon.issues
503	        ? el('div', { className: 'sub', textContent: `before ${series.horizon.issues} this is a floor — one issue page per member does not reach further back` })
504	        : null,
505	    ]),
506	    el('div', { className: 'chart-card' }, [
507	      el('div', { className: 'k', textContent: pass == null ? 'no scheduler runs in the window' : `${series.totals.runs} runs · ${pass}% passed` }),
508	      chartLegend(RUN_SERIES),
509	      stackedColumns(series.days, RUN_SERIES),
510	      series.horizon.runs
511	        ? el('div', { className: 'sub', textContent: `before ${series.horizon.runs} this is a floor — the last 30 runs per member do not reach further back` })
512	        : null,
513	    ]),
514	    el('div', { className: 'chart-card' }, [movement]),
515	  );
516	}
517	
518	// A member whose read has not landed yet. It is a row from the first paint rather
519	// than a gap that fills in, because a fleet page that appears all at once at the end
520	// looks broken for the whole sweep — and on a slow or throttled read, the sweep is
521	// most of the time the viewer spends here.
522	const pendingRow = (repo) => el('tr', { className: 'pending-row' }, [
523	  el('td', {}, [el('div', { className: 'member' }, [
524	    starMark(null),
525	    el('div', {}, [
526	      el('span', { className: 'name', textContent: repo.split('/')[1] ?? repo }),
527	      el('div', { className: 'sub' }, [repoLink(repo)]),
528	    ]),
529	  ])]),
530	  el('td', { colSpan: MEMBER_COLS - 1 }, [el('span', { className: 'sub', textContent: 'reading…' })]),
531	]);
532	
533	function renderFleet(summaries, reads, now, onOpen, canon, progress = null, digests = null, canonConfig = null) {
534	  const resolved = summaries.filter(Boolean);
535	  const pending = summaries.map((s, i) => (s ? null : reads.names?.[i])).filter(Boolean);
536	  const roll = rollUp(resolved);
537	
538	  // The headline tile counts MEMBERS, which is the length of the morning's list — but
539	  // the list is only actionable once it says what kind of attention each is waiting
540	  // for. Three merges to approve and three broken lanes are not the same morning.
541	  const needs = attentionBreakdown(fleetAttention(roll));
542	
543	  tiles($('fleet-tiles'), [
544	    [roll.needAttention, 'members need you', roll.needAttention ? 'var(--critical)' : null,
545	      needs.length
546	        ? el('div', { className: 'needs' }, needs.map((r) =>
547	          el('div', { className: `warn ${r.level}`, textContent: `${LEVEL_GLYPH[r.level]} ${r.text}` })))
548	        : 'nothing is on fire'],
549	    [roll.parkedItems, 'items parked', roll.parkedItems ? 'var(--critical)' : null,
550	      roll.parkedMembers ? `across ${roll.parkedMembers} member(s)` : ''],
551	    [roll.failingMembers, 'schedulers failing', roll.failingMembers ? 'var(--critical)' : null,
552	      roll.neverRan ? `${roll.neverRan} never ran` : ''],
553	    [roll.behindMembers, 'mounts behind', roll.behindMembers ? 'var(--serious)' : null,
554	      canon ? (canon.engineVersion != null ? `canon engine v${canon.engineVersion}` : 'canon versions unreadable') : 'no canon configured'],
555	    [estimateMinutes(fleetAttention(roll)), 'minutes of your time', null,
556	      `at ${MINUTES_PER_PARK} min a parked item`],
557	    [roll.openItems, 'open work items', null, `${roll.inFlight} run(s) in flight`],
558	    [`${roll.adopted}/${roll.members}`, 'members adopted', null,
559	      [roll.notAdopted ? `${roll.notAdopted} not adopted` : '', roll.unreadable ? `${roll.unreadable} unreadable` : ''].filter(Boolean).join(', ')],
560	  ]);
561	
562	  // Every number above is a number about the members READ SO FAR, and a partial
563	  // rollup that does not say so is a wrong one. The count is stated rather than the
564	  // page waiting to be sure.
565	  $('fleet-progress').textContent = progress && progress.done < progress.total
566	    ? `${progress.done}/${progress.total} repos read — figures below cover those`
567	    : (progress ? `${progress.total} repos read` : '');
568	
569	  const body = groupedHead($('fleet'), MEMBER_GROUPS);
570	  if (!summaries.length) { body.append(emptyRow(MEMBER_COLS, 'No members in the roster.')); return; }
571	  for (const s of rankMembers(resolved)) body.append(memberRow(s, onOpen, now));
572	  for (const repo of pending) body.append(pendingRow(repo));
573	
574	  // Tasks across the fleet. This is the view a per-repo page structurally cannot
575	  // give: a shared pack's task parked in four members at once is a canon problem,
576	  // and in any single repo it looks like that repo's bad luck.
577	  const resolvedReads = reads.filter(Boolean);
578	  renderDigests(digests, canonConfig);
579	  renderBenefits(fleetBenefits(resolvedReads, { now, digests }));
580	  renderActivity(activitySeries(resolvedReads, { now }));
581	
582	  const spread = taskSpread(resolvedReads, now).filter((t) => t.members > 0);
583	  const tbody = groupedHead($('fleet-tasks'), FLEET_TASK_GROUPS);
584	  if (!spread.length) tbody.append(emptyRow(columnCount(FLEET_TASK_GROUPS), 'No work items seen across the fleet.'));
585	  for (const t of spread.slice(0, 25)) {
586	    tbody.append(el('tr', { className: t.parked ? 'lvl-critical' : '' }, [
587	      el('td', {}, [
588	        el('div', { className: 'name', textContent: t.task }),
589	        el('div', { className: 'sub', textContent: t.pack }),
590	      ]),
591	      el('td', { className: 'num', textContent: String(t.members) }),
592	      el('td', { className: 'num', textContent: String(t.open) }),
593	      el('td', {}, t.parked
594	        ? [el('span', { className: 'warn critical', textContent: `${LEVEL_GLYPH.critical} ${t.parked}` })]
595	        : [el('span', { className: 'sub', textContent: '0' })]),
596	      el('td', { className: 'num', textContent: String(t.done) }),
597	      el('td', {}, t.failed
598	        ? [el('span', { className: 'warn serious', textContent: `${LEVEL_GLYPH.serious} ${t.failed}` })]
599	        : [el('span', { className: 'sub', textContent: '0' })]),
600	    ]));
601	  }
602	
603	  const packs = packSpread(resolved);
604	  $('fleet-packs').replaceChildren(...packs.map((p) =>
605	    el('span', { className: 'chip', title: `${p.members} member(s)` }, [
606	      p.pack, el('b', { className: 'count', textContent: String(p.members) }),
607	    ])));
608	}
609	
610	// --- entry ----------------------------------------------------------------------
611	
612	export async function loadFleet({ repos, token, config, onOpen, onError, onProgress }) {
613	  gh.resetCounters();
614	  const now = Date.now();
615	
616	  const canon = await readCanon(config, token);
617	  // Read before the sweep so the panel is there from the first paint: it is two small
618	  // reads, and it is the thing a viewer opening this page in the morning came for.
619	  const digests = await readDigests(config, token);
620	
621	  // Rendered on every arrival rather than once at the end: the page is useful from
622	  // the first member back, and the member a viewer opened it for may be the first.
623	  const reads = new Array(repos.length).fill(null);
624	  reads.names = repos;
625	  const summaries = new Array(repos.length).fill(null);
626	  let done = 0;
627	  const paint = () => renderFleet(summaries, reads, now, onOpen, canon, { done, total: repos.length }, digests, config);
628	  paint();
629	
630	  await pool(repos, async (repo, i) => {
631	    const r = await readMember(repo, token);
632	    reads[i] = r;
633	    // Price this member's stamped packs on the canon side before judging its mount —
634	    // lazily and memoized across members, under today's spelling for a stamp written
635	    // before a pack rename.
636	    if (canon?.packVersion && r.declaration?.claudinite?.packVersions) {
637	      const stamped = canonicalPackVersions(r.declaration.claudinite.packVersions);
638	      await Promise.all(Object.keys(stamped ?? {}).map(canon.packVersion));
639	    }
640	    summaries[i] = summariseMember(r, { now, canon });
641	    done += 1;
642	    onProgress?.(done, repos.length, repo);
643	    paint();
644	    return r;
645	  });
646	  const failed = summaries.filter((s) => s?.status === 'unreadable');
647	  // Surfaced once at the top rather than as twelve separate errors: on a fleet, some
648	  // members being invisible to you is the normal case, not an incident.
649	  if (failed.length === repos.length && repos.length > 0) {
650	    onError?.(`None of the ${repos.length} members could be read — check that you are signed in with an account that can see them.`);
651	  }
652	
653	  paint();
654	  return { summaries: summaries.filter(Boolean), now, canon, digests };
655	}
