    // a growth task still cannot see its own merged output and re-trigger on it.
    const closed = await pagedWindow(
      gh,
      `/repos/${ctx.repo}/pulls?state=closed&sort=updated&direction=desc`,
      (p) => new Date(p.updated_at) >= since,
