60	    }
61	  }
62	  // A held lane is a fact about the TASK, not about the item holding it: nothing new
63	  // will be filed for this task until the park clears, and the item's own row says
64	  // only that it is parked.
65	  if (row.nextAsk?.kind === 'held') {
66	    out.push({ level: 'critical', text: 'the task\'s lane is held — nothing new is scheduled until this clears' });
67	  }
68	  return out.sort((a, b) => levelRank(a.level) - levelRank(b.level));
69	}
70	
71	// Which view a row belongs to. `stuck` and `pending` are exclusive: an item that has
72	// stopped is not also in flight, whatever label it wears.
73	export function classify(row) {
