75	  return row.current ? 'pending' : 'idle';
76	}
77	
78	// What acts soonest, for ordering within a severity band. Acting now beats every date;
79	// a held or unreadable schedule sinks, because it has no next.
80	export function askOrder(row) {
81	  const ask = row.nextAsk ?? { kind: 'note' };
82	  if (ask.kind === 'ready' || ask.kind === 'running' || ask.kind === 'ready-soon') return 0;
83	  if (ask.at) return ask.at.getTime();
84	  return Infinity;
85	}
86	
87	// Every piece of work as one row: the declared tasks, plus any open item whose task
88	// this repo no longer declares — which is exactly the item nobody will ever pick up,
89	// and precisely what a roster-only table cannot show.
90	//
91	// `rows` is `buildRoster`'s output; `open` is the described open items.
92	export function workRows(rows, open) {
