98	      pack: i.pack,
99	      task: i.task,
100	      declaration: null,
101	      frequency: null,
102	      // Not a schedule problem to be waited out: the item names a task this repo does
103	      // not declare, so nothing will ever pick it up until a person acts.
104	      nextAsk: { kind: 'note', note: 'no declared task — nothing will pick this up' },
105	      anchorNote: null,
106	      current: i,
107	      openCount: 1,
108	      lastClosed: null,
109	      history: [],
110	      undeclared: true,
111	    }));
112	
113	  return [...rows.map((r) => ({ ...r, undeclared: false })), ...orphans].map((r) => {
114	    const t = troubles(r);
115	    return {
116	      ...r,
117	      troubles: t,
118	      // An undeclared item is a stop of its own kind, and it has no warning of its own
119	      // to carry it — the queue's recovery rules are about items whose task exists.
