123	  }).sort((a, b) => levelRank(a.level) - levelRank(b.level) || askOrder(a) - askOrder(b) || a.key.localeCompare(b.key));
124	}
125	
126	// The rows one view shows. `all` is every row; the other two are their own kind.
127	export const rowsFor = (all, view) => (view === 'all' ? all : all.filter((r) => r.view === view));
128	
129	// How many rows each view holds, so the switcher can say what it is offering instead of
130	// making the reader click to find out — and so a view with nothing in it can say
131	// "nothing is stuck" rather than rendering an empty table.
132	export function viewCounts(all) {
133	  return {
134	    stuck: all.filter((r) => r.view === 'stuck').length,
135	    pending: all.filter((r) => r.view === 'pending').length,
136	    all: all.length,
137	  };
138	}
139	
140	// The view to open on: whatever is worst and non-empty. A page whose default view is
141	// empty on a healthy repo teaches its reader that the page is broken.
142	export const defaultView = (counts) => (counts.stuck ? 'stuck' : counts.pending ? 'pending' : 'all');
143	
144	// --- what is waiting on a person ----------------------------------------------------
145	
146	// The park split, in the vocabulary the fleet page's estimate already speaks. Kept here
147	// rather than recomputed in the view so the repo page's minutes and the fleet row's
148	// minutes are the same arithmetic over the same definitions.
149	export function attentionOf(open) {
150	  const parked = open.filter((i) => i.state === NEEDS_HUMAN);
151	  return {
152	    broken: parked.filter((i) => i.blockingPark).length,
153	    approvals: parked.filter((i) => !i.blockingPark && i.triage === NEEDS_HUMAN_APPROVAL).length,
154	    decisions: parked.filter((i) => !i.blockingPark && i.triage !== NEEDS_HUMAN_APPROVAL).length,
155	    tripping: open.filter((i) => i.state !== NEEDS_HUMAN && i.warnings.length).length,
156	  };
157	}

