/* The work table's view switcher. A segmented control rather than a dropdown: there
   are three, they are always all available, and each carries its own count so the
   reader knows what a click is offering before making it. */
.views { display: flex; gap: 6px; margin-bottom: 10px; flex-wrap: wrap; }
button.view-tab { font-size: 12px; padding: 4px 11px; border-radius: 999px;
                  color: var(--ink-2); text-transform: capitalize; }
button.view-tab.on { border-color: var(--ink-2); color: var(--ink); font-weight: 600; }
/* The rows animate from where they were to where they are now, which needs each row
   to be its own containing block for the transform. */
#work tbody tr { will-change: transform; }
#work { min-width: 900px; }

/* Two series, two scales. The right-hand axis label sits at the right so it reads
   against the axis it belongs to. */
.chart-axis .axis.right { text-align: right; }
.series-line { fill: none; stroke-width: 1.5; vector-effect: non-scaling-stroke;
               stroke-linejoin: round; stroke-linecap: round; }
svg.chart.dual { height: 96px; }
/* The growth chart earns the full width: a month at daily resolution squeezed into a
   third of the row is a smear. */
.chart-card.wide { grid-column: 1 / -1; }

tr.pending-row td { color: var(--muted); }

