1	import { test, beforeEach } from 'node:test';
2	import assert from 'node:assert/strict';
3	
4	// `cache.mjs` is browser code talking to `localStorage`, so the test supplies one.
5	// A Map-backed stand-in with a byte ceiling is enough to exercise the two behaviours
6	// that actually matter: that a full quota degrades instead of throwing, and that
7	// eviction drops the OLDEST entries rather than whatever the engine iterated first.
8	class FakeStorage {
9	  constructor(limit = Infinity) { this.m = new Map(); this.limit = limit; }
10	  get length() { return this.m.size; }
11	  key(i) { return [...this.m.keys()][i] ?? null; }
12	  getItem(k) { return this.m.has(k) ? this.m.get(k) : null; }
13	  removeItem(k) { this.m.delete(k); }
14	  setItem(k, v) {
15	    const next = [...this.m.entries()].reduce((n, [a, b]) => n + a.length + b.length, 0)
16	      + k.length + String(v).length - (this.m.has(k) ? k.length + this.m.get(k).length : 0);
17	    if (next > this.limit) { const e = new Error('QuotaExceededError'); e.name = 'QuotaExceededError'; throw e; }
18	    this.m.set(k, String(v));
19	  }
20	}
21	
22	const load = async () => import(`../../packs/claudinite-dashboard/cache.mjs?t=${Math.random()}`);
23	
24	beforeEach(() => { globalThis.localStorage = new FakeStorage(); });
25	
26	test('an immutable blob round-trips under its sha', async () => {
27	  const c = await load();
28	  assert.equal(c.immutable.get('o/r', 'sha1', 'a.mjs'), undefined, 'cold read is a miss');
29	  c.immutable.set('o/r', 'sha1', 'a.mjs', 'contents');
30	  assert.equal(c.immutable.get('o/r', 'sha1', 'a.mjs'), 'contents');
31	  // A different sha is a different world — this is the whole point of the key.
32	  assert.equal(c.immutable.get('o/r', 'sha2', 'a.mjs'), undefined);
33	});
34	
35	// A 404 is a real answer that must be cached, and `null` must not read as a miss —
36	// otherwise every fleet sweep re-asks every member for files that are not there.
37	test('a cached absence is a hit, not a miss', async () => {
38	  const c = await load();
39	  c.immutable.set('o/r', 'sha1', 'missing.json', null);
40	  assert.equal(c.immutable.get('o/r', 'sha1', 'missing.json'), null);
41	  assert.notEqual(c.immutable.get('o/r', 'sha1', 'missing.json'), undefined);
42	});
43	
44	test('a validated entry keeps its etag, and touch refreshes only the timestamp', async () => {
45	  const c = await load();
46	  c.validated.set('/x', 'W/"abc"', { v: 1 });
47	  const first = c.validated.get('/x');
48	  assert.equal(first.etag, 'W/"abc"');
49	  assert.deepEqual(first.data, { v: 1 });
50	  c.validated.touch('/x');
51	  const second = c.validated.get('/x');
52	  assert.deepEqual(second.data, { v: 1 }, 'a 304 must not disturb the cached body');
53	  assert.ok(second.at >= first.at);
54	});
55	
56	test('an ageing entry expires at its ttl and not before', async () => {
57	  const c = await load();
58	  c.ageing.set('h', [1, 2, 3]);
59	  assert.deepEqual(c.ageing.get('h', 1000), [1, 2, 3]);
60	  assert.equal(c.ageing.get('h', 0), undefined, 'a zero ttl is always expired');
61	  assert.equal(c.DAY_MS, 24 * 3600e3);
62	});
63	
64	test('a full quota degrades to a miss instead of throwing', async () => {
65	  globalThis.localStorage = new FakeStorage(120);
66	  const c = await load();
67	  assert.doesNotThrow(() => c.ageing.set('big', 'x'.repeat(5000)));
68	  assert.equal(c.ageing.get('big'), undefined, 'the oversized write is simply absent');
