// One parameterised driver for the dashboard, re-pointed rather than re-written:
//   node drive.mjs <url> <fixtures.json> <out.png>
// Every api.github.com call is answered from the fixture file (path substring → body),
// so the page renders a whole repo with no network. Console errors and page errors are
// printed, and the exit code is non-zero if any appeared.
import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';

