15	
16	const problems = [];
17	page.on('console', (m) => { if (m.type() === 'error') problems.push(`console: ${m.text()}`); });
18	page.on('pageerror', (e) => problems.push(`pageerror: ${e.message}`));
19	
20	// A real ETag round trip, so a second load measures what a warm one actually costs:
21	// a request carrying a matching `If-None-Match` is answered 304 with no body, which is
22	// what GitHub does and what the page's whole budget story rests on.
23	let spent = 0;
24	let revalidated = 0;
25	await page.route('**://api.github.com/**', async (route) => {
26	  const req = route.request();
27	  const u = req.url().replace('https://api.github.com', '');
28	  if (req.headers()['if-none-match'] === 'W/"x"') {
29	    revalidated += 1;
30	    return route.fulfill({ status: 304, headers: { etag: 'W/"x"', 'x-ratelimit-remaining': '4900', 'access-control-expose-headers': 'etag, x-ratelimit-remaining, x-ratelimit-limit, x-ratelimit-reset, retry-after', }, body: '' });
31	  }
32	  spent += 1;
33	  if (process.env.TRACE) console.log('  ->', req.headers()['if-none-match'] ?? '(no inm)', u.slice(0, 70));
34	  // The LONGEST matching fragment wins: `/user` is a substring of `/users/o/repos`,
35	  // and first-match routing quietly answered a repo enumeration with the viewer object.
36	  const hit = Object.entries(fixtures)
37	    .filter(([frag]) => u.includes(frag))
38	    .sort((a, b) => b[0].length - a[0].length)[0];
39	  if (!hit) { problems.push(`unstubbed: ${u}`); return route.fulfill({ status: 404, body: '{}' }); }
40	  const [, value] = hit;
41	  const body = typeof value === 'string' ? value : JSON.stringify(value);
42	  await route.fulfill({
43	    status: 200,
44	    headers: { 'content-type': 'application/json', 'x-ratelimit-remaining': '4900', 'x-ratelimit-limit': '5000', etag: 'W/"x"', 'access-control-expose-headers': 'etag, x-ratelimit-remaining, x-ratelimit-limit, x-ratelimit-reset, retry-after', },
45	    body,
46	  });
47	});
