1	// The deep dive: one repo's scheduler in full — what is stuck, what is queued, what
2	// ran, and what the machinery has been doing for the last month. Reached from the
3	// fleet view or by `?repo=` directly.
4	//
5	// TWO KINDS OF DATA, AND THEY ARE READ DIFFERENTLY. What is true RIGHT NOW comes from
6	// live reads, and they are kept to a handful: the repo, its head commit, one page of
7	// issues and one page of runs, all ETag-revalidated so a warm load spends nothing. What
8	// happened BEFORE comes from one file — the repo's own `usage.GENERATED.json`, keyed by
9	// the head sha, so it is not re-read at all while the branch has not moved. Reaching a
10	// month back over the API instead would be a paginated crawl per load.
11	//
12	// Everything past the live window therefore depends on the repo folding that file. A
13	// repo that does not says so in the panel that wanted it, and the rest of the page is
14	// unaffected.
15	
16	import * as gh from './github.mjs';
17	import {
18	  buildRoster, describeItem, isWorkItem, parseDeclaration, taskDeclarationPaths, periodMs,
19	  NEEDS_HUMAN,
20	} from './model.mjs';
21	import {
22	  ciStatus, humanWork, mountState, estimateMinutes, attentionBreakdown, MINUTES_PER_PARK,
23	} from './fleet.mjs';
24	import { readCanon, priceStampedPacks } from './canon.mjs';
25	import { workRows, rowsFor, viewCounts, defaultView, attentionOf, VIEWS } from './work.mjs';
26	import { readUsage, growthSeries, queueSeries, hourSeries } from './usage.mjs';
27	import {
28	  $, el, ago, until, stamp, duration, chip, head, emptyRow, issueLink, tiles, segmentBar,
29	  warnNodes, stackedColumns, chartLegend, dualAxisChart, flipRows,
30	  LEVEL_GLYPH, OUTCOME_COLOR,
31	} from './ui.mjs';
32	
33	// How far each past-data panel looks back. The month is the growth panel's, because a
34	// fortnight of a corpus's own numbers is noise; the fortnight is the queue's, because
35	// that is the span over which "did this task actually close anything" is a question;
36	// and two days is the runs panel's, which is a live picture rather than a history.
37	const GROWTH_DAYS = 30;
38	const OUTCOME_DAYS = 14;
39	const RUN_HOURS = 48;
40	
41	const CI_UI = {
42	  passing: { label: 'passing', color: 'var(--good)' },
43	  failing: { label: 'failing', color: 'var(--critical)' },
44	  running: { label: 'running', color: 'var(--s-yellow)' },
45	  unknown: { label: 'no run', color: null },
46	};
47	
48	// --- at a glance -------------------------------------------------------------------
49	
50	// The tiles, in the order the questions get asked: what is waiting on ME, then what is
51	// waiting on anyone, then what kind of repo this is and whether it is healthy.
52	//
53	// A tile is coloured only when it is REPORTING something, so a coloured tile always
54	// means look here — and a tile whose answer is unknown says so rather than showing a
55	// zero. The mount tile especially: with no canon configured there is nothing to compare
56	// against, and "current" would be a claim nothing checked.
57	function renderTiles({ open, runs, meta, work, mount, ci, now }) {
58	  const attention = attentionOf(open);
59	  const minutes = estimateMinutes(attention);
60	  const needs = attentionBreakdown(attention);
61	  const parked = open.filter((i) => i.state === NEEDS_HUMAN);
62	  const inflight = runs.filter((r) => r.status === 'in_progress' || r.status === 'queued');
63	
64	  const needsNodes = needs.length
65	    ? el('div', { className: 'needs' }, needs.map((r) =>
66	      el('div', { className: `warn ${r.level}`, textContent: `${LEVEL_GLYPH[r.level]} ${r.text}` })))
